                lo: "ຄລີນິກສາກົນໃນໂຮງໝໍໃຫຍ່ (ໂຮງໝໍມະຫາວິທະຍາໄລແຫ່ງຊາດໂຊລ, ໂຮງໝໍເຊເວີແຣນສ໌, ສູນການແພດອາຊານ, ແລະ ອື່ນໆ) ມີຜູ້ປະສານງານພາສາຕ່າງປະເທດໂດຍສະເພາະ.",
