                km: "មជ្ឈមណ្ឌលសុខភាពសាធារណៈក្នុងស្រុកក៏អាចផ្តល់ព័ត៌មានអំពីមន្ទីរពេទ្យដែលបានចុះកិច្ចសន្យាសម្រាប់ការព្យាបាលជនបរទេសផងដែរ។",
