                lo: "ໂຮງໝໍທີ່ໄດ້ເຊັນສັນຍາທີ່ຖືກກຳນົດໂດຍກະຊວງສາທາລະນະສຸກ ແລະ ສະຫວັດດີການ ຫຼື ອົງການປົກຄອງທ້ອງຖິ່ນ ມີແນວໂນ້ມທີ່ຈະໃຫ້ບໍລິການຄຳແນະນຳ ແລະ ການແປພາສາຫຼາຍພາສາທີ່ສະດວກກວ່າ.",
