                vi: 'Các bệnh viện hợp tác khám chữa bệnh cho người nước ngoài do Bộ Y tế và Phúc lợi hoặc chính quyền địa phương chỉ định thường có hướng dẫn đa ngôn ngữ và kết nối phiên dịch thuận tiện hơn.',
