                ur: "اپنا غیر ملکی رجسٹریشن کارڈ (ARC) اور صحت بیمہ کی حیثیت پہلے سے چیک کر لیں، اور اگر ممکن ہو تو، مواصلت کو آسان بنانے کے لیے اپنی علامات کو پہلے سے نوٹ کر لیں۔",
                th: "ตรวจสอบบัตรทะเบียนคนต่างด้าว (ARC) และสถานะประกันสุขภาพของท่านล่วงหน้า และหากเป็นไปได้ ให้จดอาการของท่านล่วงหน้าเพื่ออำนวยความสะดวกในการสื่อสาร",
                ky: "Чет өлкөлүктү каттоо картаңызды (ARC) жана медициналык камсыздандыруу статусуңузду алдын ала текшериңиз жана мүмкүн болсо, байланышты жеңилдетүү үчүн симптомдоруңузду алдын ала жазып алыңыз.",
                km: "ពិនិត្យមើលប័ណ្ណចុះឈ្មោះជនបរទេស (ARC) និងស្ថានភាពធានារ៉ាប់រងសុខភាពរបស់អ្នកជាមុន ហើយប្រសិនបើអាចធ្វើទៅបាន សូមកត់ចំណាំរោគសញ្ញារបស់អ្នកជាមុន ដើម្បីសម្រួលដល់ការទំនាក់ទំនង។",
                id: "Periksa Kartu Pendaftaran Orang Asing (ARC) dan status asuransi kesehatan Anda terlebih dahulu, dan jika memungkinkan, catat gejala Anda sebelumnya untuk memfasilitasi komunikasi.",
