                bn: "আপনার বিদেশি নিবন্ধন কার্ড (ARC) এবং স্বাস্থ্য বীমার অবস্থা আগে থেকে পরীক্ষা করুন এবং সম্ভব হলে যোগাযোগ সহজ করার জন্য আপনার লক্ষণগুলি আগে থেকে লিখে রাখুন।",
                my: "သင်၏နိုင်ငံခြားသား မှတ်ပုံတင်ကတ် (ARC) နှင့် ကျန်းမာရေးအာမခံအခြေအနေကို ကြိုတင်စစ်ဆေးပြီး ဖြစ်နိုင်ပါက ဆက်သွယ်ရေးကို လွယ်ကူချောမွေ့စေရန် သင်၏ရောဂါလက္ခဏာများကို ကြိုတင်မှတ်သားထားပါ။",
                mn: "Гадаадын иргэний бүртгэлийн карт (ARC) болон эрүүл мэндийн даатгалын статусаа урьдчилан шалгаж, боломжтой бол харилцаа холбоог хөнгөвчлөхийн тулд шинж тэмдгүүдээ урьдчилан тэмдэглэж аваарай.",
                lo: "ກະລຸນາກວດສອບບັດລົງທະບຽນຄົນຕ່າງດ້າວ (ARC) ແລະ ສະຖານະປະກັນໄພສຸຂະພາບຂອງທ່ານລ່ວງໜ້າ, ແລະ ຖ້າເປັນໄປໄດ້, ໃຫ້ຈົດອາການຂອງທ່ານໄວ້ກ່ອນເພື່ອອຳນວຍຄວາມສະດວກໃນການສື່ສານ.",
                tet:
                    "Verifika uluk Ita-nia Karta Rejistu Estranjeiru (ARC) no estatutu seguru saúde, no se bele, nota uluk Ita-nia sintoma sira atu fasilita komunikasaun.",
                ne: "आफ्नो विदेशी दर्ता कार्ड (ARC) र स्वास्थ्य बीमाको स्थिति अग्रिम जाँच गर्नुहोस्, र सम्भव भएमा सञ्चारलाई सहज बनाउनका लागि आफ्ना लक्षणहरू अग्रिम नोट गर्नुहोस्।",
                zh: '请提前确认好您的外国人登录证和健康保险参保情况，如果可以，最好将症状写下来带去，这样沟通会更顺畅。',
                vi: 'Hãy kiểm tra trước Thẻ đăng ký người nước ngoài (ARC) và tình trạng bảo hiểm y tế, nếu có thể hãy ghi chú triệu chứng trước khi đi để việc trao đổi được thuận lợi hơn.',
                uz: "Chet el fuqarosi roʻyxatga olish kartangiz (ARC) va tibbiy sugʻurta holatingizni oldindan tekshiring, iloji boʻlsa, muloqotni osonlashtirish uchun alomatlaringizni oldindan yozib oling.",
              ),
