        summary: L10nText(
          ko: '야간·주말에 문을 연 병의원과 약국은 응급의료포털에서 실시간으로 조회할 수 있습니다.',
          en: 'You can check in real time which hospitals, clinics, and pharmacies are open at night and on weekends through the Emergency Medical Information Portal.',
          tr: "Acil Tıbbi Bilgi Portalı aracılığıyla hangi hastanelerin, kliniklerin ve eczanelerin gece ve hafta sonları açık olduğunu gerçek zamanlı olarak kontrol edebilirsiniz.",
          tg: "Шумо метавонед тавассути Портали иттилооти тиббии фавқулодда дар вақти воқеӣ тафтиш кунед, ки кадом беморхонаҳо, клиникаҳо ва дорихонаҳо шабона ва рӯзҳои истироҳат кушодаанд.",
          fil:
              "Maaari mong suriin sa real-time kung aling mga ospital, klinika, at botika ang bukas sa gabi at sa mga weekend sa pamamagitan ng Emergency Medical Information Portal.",
          ur: "آپ ایمرجنسی میڈیکل انفارمیشن پورٹل کے ذریعے حقیقی وقت میں چیک کر سکتے ہیں کہ کون سے ہسپتال، کلینکس اور فارمیسیز رات اور ہفتے کے آخر میں کھلے ہیں۔",
          th: "ท่านสามารถตรวจสอบได้แบบเรียลไทม์ว่าโรงพยาบาล คลินิก และร้านขายยาใดบ้างที่เปิดทำการในเวลากลางคืนและวันหยุดสุดสัปดาห์ผ่านพอร์ทัลข้อมูลการแพทย์ฉุกเฉิน",
          ky: "Шашылыш медициналык маалымат порталы аркылуу кайсы ооруканалар, клиникалар жана дарыканалар түнкүсүн жана дем алыш күндөрү ачык экенин реалдуу убакыт режиминде текшере аласыз.",
          km: "អ្នកអាចពិនិត្យមើលថាតើមន្ទីរពេទ្យ គ្លីនិក និងឱសថស្ថានណាខ្លះដែលបើកនៅពេលយប់ និងចុងសប្តាហ៍តាមពេលវេលាជាក់ស្តែង តាមរយៈវិបផតថលព័ត៌មានវេជ្ជសាស្ត្របន្ទាន់។",
          id: "Anda dapat memeriksa secara real-time rumah sakit, klinik, dan apotek mana yang buka pada malam hari dan akhir pekan melalui Portal Informasi Medis Darurat.",
          si: "හදිසි වෛද්‍ය තොරතුරු ද්වාරය හරහා රාත්‍රී සහ සති අන්තවල විවෘතව ඇති රෝහල්, සායන සහ ෆාමසි තත්‍ය කාලීනව පරීක්ෂා කළ හැකිය.",
          bn: "আপনি ইমার্জেন্সি মেডিকেল ইনফরমেশন পোর্টালের মাধ্যমে রিয়েল-টাইমে পরীক্ষা করতে পারেন যে কোন হাসপাতাল, ক্লিনিক এবং ফার্মেসিগুলি রাতে এবং সপ্তাহান্তে খোলা থাকে।",
          my: "အရေးပေါ်ဆေးဘက်ဆိုင်ရာ အချက်အလက်ပေါ်တယ်မှတစ်ဆင့် မည်သည့်ဆေးရုံများ၊ ဆေးခန်းများနှင့် ဆေးဆိုင်များ ညပိုင်းနှင့် ရက်သတ္တပတ်ကုန်များတွင် ဖွင့်သည်ကို အချိန်နှင့်တစ်ပြေးညီ စစ်ဆေးနိုင်ပါသည်။",
          mn: "Та Яаралтай тусламжийн мэдээллийн порталаар дамжуулан шөнө болон амралтын өдрүүдэд ямар эмнэлэг, клиник, эмийн сангууд ажиллаж байгааг бодит цагаар шалгах боломжтой.",
          lo: "ທ່ານສາມາດກວດສອບໄດ້ແບບສົດໆວ່າໂຮງໝໍ, ຄລີນິກ, ແລະ ຮ້ານຂາຍຢາໃດແດ່ທີ່ເປີດບໍລິການໃນຕອນກາງຄືນ ແລະ ວັນທ້າຍອາທິດຜ່ານປະຕູຂໍ້ມູນການແພດສຸກເສີນ.",
          tet:
              "Liuhusi Portál Informasaun Médika Emerjénsia, Ita bele verifika iha tempu reál ospitál, klínika no farmásia sira ne'ebé loke iha kalan no fim-de-semana.",
          ne: "आपतकालीन चिकित्सा सूचना पोर्टल मार्फत कुन अस्पताल, क्लिनिक र फार्मेसीहरू रात र सप्ताहान्तमा खुला छन् भनी वास्तविक समयमा जाँच गर्न सक्नुहुन्छ।",
          zh: '您可以通过急诊医疗信息门户实时查询夜间、周末营业的医院、诊所和药店。',
          vi: 'Bạn có thể tra cứu theo thời gian thực các bệnh viện, phòng khám và hiệu thuốc mở cửa vào ban đêm, cuối tuần trên Cổng thông tin y tế cấp cứu.',
          uz: "Qaysi shifoxonalar, klinikalar va dorixonalar tunda va dam olish kunlari ochiq ekanligini Favqulodda Tibbiy Maʼlumotlar Portali orqali real vaqt rejimida tekshirishingiz mumkin.",
        ),
