                mn: "Одоогийн байршлаар хайхын тулд E-Gen вэбсайт эсвэл аппликейшн дээрх “Эмийн сан олох / Яаралтай тусламж олох” цэсийг ашиглана уу.",
                lo: "ໃຊ້ເມນູ \"ຊອກຫາຮ້ານຂາຍຢາ / ຊອກຫາບໍລິການສຸກເສີນ\" ໃນເວັບໄຊທ໌ ຫຼື ແອັບພລິເຄຊັນ E-Gen ເພື່ອຄົ້ນຫາຕາມສະຖານທີ່ປັດຈຸບັນຂອງທ່ານ.",
