              L10nText(
                ko: '보건복지부 콜센터 129, 서울시는 다산콜센터 120으로 전화 문의 가능',
                en: 'You can also call the Ministry of Health and Welfare Call Center at 129, or in Seoul, the Dasan Call Center at 120',
                tr: "Ayrıca Sağlık ve Refah Bakanlığı Çağrı Merkezi'ni 129'dan veya Seul'de Dasan Çağrı Merkezi'ni 120'den arayabilirsiniz",
                tg: "Шумо инчунин метавонед ба Маркази тамос бо Вазорати тандурустӣ ва некӯаҳволӣ бо рақами 129 ё ба Маркази тамос бо Дасан дар Сеул бо рақами 120 занг занед.",
