                ky: "Ошондой эле Саламаттыкты сактоо жана социалдык камсыздоо министрлигинин чалуу борборуна 129 номери аркылуу же Сеулдагы Дасан чалуу борборуна 120 номери аркылуу чалсаңыз болот.",
                km: "អ្នកក៏អាចទូរស័ព្ទទៅមជ្ឈមណ្ឌលហៅទូរស័ព្ទរបស់ក្រសួងសុខាភិបាល និងសុខុមាលភាពតាមរយៈលេខ 129 ឬមជ្ឈមណ្ឌលហៅទូរស័ព្ទ Dasan នៅទីក្រុងសេអ៊ូលតាមរយៈលេខ 120។",
