                bn: "এছাড়াও আপনি স্বাস্থ্য ও কল্যাণ মন্ত্রণালয়ের কল সেন্টারে 129 নম্বরে অথবা সিউলে দাসান কল সেন্টারে 120 নম্বরে কল করতে পারেন।",
                my: "ကျန်းမာရေးနှင့် လူမှုဖူလုံရေးဝန်ကြီးဌာန၏ Call Center ကို 129 သို့မဟုတ် ဆိုးလ်ရှိ Dasan Call Center ကို 120 သို့လည်း ခေါ်ဆိုနိုင်ပါသည်။",
