          bn: "জীবন-হুমকির জরুরি অবস্থায়, 119 নম্বরে কল করলে আপনাকে একই সাথে নিকটতম জরুরি পরিষেবাতে নিয়ে যাওয়া হবে এবং নির্দেশিত করা হবে।",
          my: "အသက်အန္တရာယ်ရှိသော အရေးပေါ်အခြေအနေတွင် 119 ကို ခေါ်ဆိုခြင်းဖြင့် သင့်အား အနီးဆုံးအရေးပေါ်ဌာနသို့ တစ်ပြိုင်နက်တည်း ချိတ်ဆက်ပေးပြီး လမ်းညွှန်ပေးပါမည်။",
          mn: "Амь насанд аюултай яаралтай тохиолдолд 119 руу залгаснаар таныг хамгийн ойрын яаралтай тусламжийн тасаг руу нэгэн зэрэг холбож, чиглүүлнэ.",
          lo: "ໃນກໍລະນີສຸກເສີນທີ່ເປັນອັນຕະລາຍເຖິງຊີວິດ, ການໂທຫາເບີ 119 ຈະເຊື່ອມຕໍ່ ແລະ ນໍາພາທ່ານໄປຫາບໍລິການສຸກເສີນທີ່ໃກ້ທີ່ສຸດໃນເວລາດຽວກັນ.",
          tet:
              "Iha kazu emerjénsia ne'ebé ameasa moris, bolu 119 sei lori no dirije Ita kedas ba servisu emerjénsia ne'ebé besik liu.",
          ne: "जीवन-घातक आपतकालीन अवस्थामा, 119 मा कल गर्दा तपाईंलाई एकैचोटि नजिकको आपतकालीन सेवामा पुर्‍याउनेछ र मार्गदर्शन गर्नेछ।",
          zh: '在危及生命的紧急情况下，拨打119即可获得转运服务，同时被引导前往最近的急诊室。',
          vi: 'Trong tình huống nguy hiểm đến tính mạng, hãy gọi 119 để được đưa đi cấp cứu và hướng dẫn đến phòng cấp cứu gần nhất cùng lúc.',
          uz: "Hayotga xavf tugʻdiradigan favqulodda vaziyatda 119 raqamiga qoʻngʻiroq qilish sizni eng yaqin tez yordam xonasiga bir vaqtning oʻzida olib boradi va yoʻnaltiradi.",
