                bn: "আপনার অবস্থান, লক্ষণ এবং বয়স যতটা সম্ভব স্পষ্টভাবে বলুন, এবং যদি ভাষা একটি বাধা হয়, তবে একজন দোভাষীর সাথে সংযোগ স্থাপনের জন্য অনুরোধ করুন।",
