                km: "ប័ណ្ណចុះឈ្មោះជនបរទេស (ARC) ព័ត៌មានធានារ៉ាប់រងសុខភាព និងព័ត៌មានលម្អិតអំពីថ្នាំដែលអ្នកកំពុងប្រើប្រាស់បច្ចុប្បន្ន",
