                bn: "বিদেশী নিবন্ধন কার্ড (ARC), স্বাস্থ্য বীমা তথ্য এবং বর্তমানে আপনি যে ওষুধগুলি ব্যবহার করছেন তার বিবরণ।",
                my: "နိုင်ငံခြားသား မှတ်ပုံတင်ကတ် (ARC)၊ ကျန်းမာရေးအာမခံ အချက်အလက်များနှင့် သင်လက်ရှိသောက်သုံးနေသော ဆေးဝါးများ၏ အသေးစိတ်အချက်အလက်များ",
                mn: "Гадаадын иргэний бүртгэлийн карт (ARC), эрүүл мэндийн даатгалын мэдээлэл, одоогоор хэрэглэж буй эмийн дэлгэрэнгүй мэдээлэл",
                lo: "ບັດລົງທະບຽນຄົນຕ່າງດ້າວ (ARC), ຂໍ້ມູນປະກັນໄພສຸຂະພາບ ແລະ ລາຍລະອຽດຂອງຢາທີ່ທ່ານກໍາລັງໃຊ້ໃນປັດຈຸບັນ.",
