              L10nText(
                ko: '산업재해로 인한 부상이라면 접수 시 "일하다 다쳤다"고 명확히 알려야 합니다 — ⑪산업재해 참고',
                en: 'If the injury was caused by a workplace accident, clearly state at check-in that you "were injured while working" — see ⑪ Industrial Accidents',
                tr: "Yaralanma bir iş kazasından kaynaklandıysa, girişte açıkça \"çalışırken yaralandığınızı\" belirtin — bkz. ⑪ İş Kazaları",
                tg: "Агар ҷароҳат дар натиҷаи садамаи корӣ бошад, ҳангоми қабул ба таври возеҳ изҳор кунед, ки шумо \"ҳангоми кор ҷароҳат бардоштаед\" — нигаред ба ⑪ Садамаҳои корӣ.",
                fil:
                    "Kung ang pinsala ay nagmula sa isang aksidente sa trabaho, malinaw na sabihin sa pagpasok na \"nasugatan ka habang nagtatrabaho\" — tingnan ang ⑪ Mga Aksidente sa Trabaho.",
                ur: "اگر چوٹ کام کے حادثے کی وجہ سے ہوئی ہے، تو داخلے کے وقت واضح طور پر بتائیں کہ \"آپ کام کے دوران زخمی ہوئے ہیں\" — ملاحظہ کریں ⑪ کام کے حادثات",
                th: "หากการบาดเจ็บเกิดจากอุบัติเหตุจากการทำงาน ให้ระบุอย่างชัดเจนเมื่อเข้ารับการรักษาว่า “คุณได้รับบาดเจ็บขณะทำงาน” — ดู ⑪ อุบัติเหตุจากการทำงาน",
                ky: "Эгер жаракат өндүрүштүк кырсыктан улам болсо, кирүүдө \"жумушта жаракат алганыңызды\" так айтыңыз — караңыз ⑪ Өндүрүштүк кырсыктар.",
                km: "ប្រសិនបើរបួសបណ្តាលមកពីគ្រោះថ្នាក់ការងារ សូមបញ្ជាក់យ៉ាងច្បាស់នៅពេលចូលថា «អ្នកបានរងរបួសនៅពេលកំពុងធ្វើការ» — សូមមើល ⑪ គ្រោះថ្នាក់ការងារ",
                id: "Jika cedera disebabkan oleh kecelakaan kerja, nyatakan dengan jelas di pintu masuk bahwa Anda \"terluka saat bekerja\" — lihat ⑪ Kecelakaan Kerja.",
                si: "තුවාලය රැකියා අනතුරකින් සිදුවී ඇත්නම්, ඇතුල්වීමේදී “රැකියාවේදී තුවාල වූ බව” පැහැදිලිව සඳහන් කරන්න — ⑪ රැකියා අනතුරු බලන්න.",
                bn: "যদি আঘাতটি কর্মক্ষেত্রে দুর্ঘটনার কারণে হয়, তবে প্রবেশপথে স্পষ্টভাবে বলুন যে আপনি \"কাজের সময় আহত হয়েছেন\" — দেখুন ⑪ কর্মক্ষেত্রে দুর্ঘটনা।",
                my: "ထိခိုက်ဒဏ်ရာသည် လုပ်ငန်းခွင်မတော်တဆမှုကြောင့် ဖြစ်ပါက၊ ဝင်ရောက်သည့်အခါ “အလုပ်လုပ်နေစဉ် ထိခိုက်ဒဏ်ရာရရှိခဲ့ကြောင်း” ရှင်းလင်းစွာ ဖော်ပြပါ — ⑪ လုပ်ငန်းခွင်မတော်တဆမှုများကို ကြည့်ပါ။",
                mn: "Хэрэв гэмтэл нь ажлын ослоос үүдэлтэй бол, орохдоо “ажлын үеэр гэмтсэн” гэдгээ тодорхой хэлээрэй — ⑪ Ажлын осол хэсгийг үзнэ үү.",
                lo: "ຖ້າການບາດເຈັບເກີດຈາກອຸບັດຕິເຫດໃນບ່ອນເຮັດວຽກ, ໃຫ້ລະບຸຢ່າງຊັດເຈນວ່າ \"ທ່ານໄດ້ຮັບບາດເຈັບໃນເວລາເຮັດວຽກ\" ເມື່ອເຂົ້າຮັບການປິ່ນປົວ — ເບິ່ງ ⑪ ອຸບັດຕິເຫດໃນບ່ອນເຮັດວຽກ.",
                tet:
                    "Se kanek ne'e mai husi asidente servisu, fó sai klaru iha entrada katak Ita \"kanek bainhira servisu\" — haree ⑪ Asidente Servisu.",
                ne: "यदि चोट काममा भएको दुर्घटनाबाट लागेको हो भने, प्रवेश गर्दा स्पष्ट रूपमा \"तपाईं काममा घाइते हुनुभएको\" बताउनुहोस् — हेर्नुहोस् ⑪ कार्य दुर्घटनाहरू।",
                zh: '如果是因工伤导致的受伤，登记时必须明确说明"工作时受伤"——请参考⑪工伤事故',
                vi: 'Nếu bị thương do tai nạn lao động, khi làm thủ tục phải nói rõ là "bị thương trong khi làm việc" — tham khảo mục ⑪ Tai nạn lao động',
                uz: "Agar jarohat ish joyidagi baxtsiz hodisa natijasida yuzaga kelgan boʻlsa, roʻyxatdan oʻtishda aniq qilib \"ishlayotganimda jarohat oldim\" deb ayting — ⑪ Ishdagi baxtsiz hodisalarga qarang.",
