            bullets: [
              L10nText(
                ko: '응급실은 진료 후 응급의료관리료가 별도로 부과되며, 경증으로 판단되면 본인부담이 늘어날 수 있습니다.',
                en: 'An emergency medical management fee is charged separately after treatment, and if your condition is judged to be minor, your out-of-pocket share may increase.',
                tr: "Tedaviden sonra acil tıbbi yönetim ücreti ayrıca tahsil edilir ve durumunuz hafif olarak değerlendirilirse, cebinizden ödeyeceğiniz pay artabilir.",
                tg: "Пас аз табобат, ҳаққи идоракунии тиббии таъҷилӣ алоҳида ситонида мешавад ва агар ҳолати шумо сабук арзёбӣ шавад, ҳиссаи шумо аз ҳисоби худ метавонад афзоиш ёбад.",
                fil:
                    "Pagkatapos ng paggamot, ang bayad sa emergency medical management ay hiwalay na sinisingil, at kung ang iyong kondisyon ay itinuturing na banayad, maaaring tumaas ang iyong out-of-pocket share.",
                ur: "علاج کے بعد ایمرجنسی میڈیکل مینجمنٹ فیس الگ سے وصول کی جاتی ہے، اور اگر آپ کی حالت کو ہلکا سمجھا جاتا ہے، تو آپ کی جیب سے ادا کی جانے والی رقم بڑھ سکتی ہے۔",
                th: "หลังจากได้รับการรักษา จะมีการเรียกเก็บค่าธรรมเนียมการจัดการทางการแพทย์ฉุกเฉินเพิ่มเติม และหากอาการของคุณถูกจัดว่าไม่รุนแรง ส่วนที่คุณต้องจ่ายเองอาจเพิ่มขึ้น",
                ky: "Дарылоодон кийин тез медициналык башкаруу акысы кошумча алынат, эгер абалыңыз жеңил деп бааланса, чөнтөгүңүздөн төлөй турган үлүшүңүз көбөйүшү мүмкүн.",
                km: "បន្ទាប់ពីការព្យាបាល ថ្លៃសេវាគ្រប់គ្រងវេជ្ជសាស្ត្របន្ទាន់នឹងត្រូវគិតថ្លៃបន្ថែម ហើយប្រសិនបើស្ថានភាពរបស់អ្នកត្រូវបានចាត់ទុកថាស្រាល ចំណែកដែលអ្នកត្រូវបង់ដោយខ្លួនឯងអាចនឹងកើនឡើង។",
                id: "Biaya administrasi medis darurat akan dikenakan secara terpisah setelah perawatan, dan jika kondisi Anda dinilai ringan, bagian yang harus Anda bayar sendiri mungkin meningkat.",
                si: "ප්‍රතිකාරයෙන් පසු හදිසි වෛද්‍ය කළමනාකරණ ගාස්තුව වෙනම අය කරනු ලබන අතර, ඔබගේ තත්ත්වය සුළු ලෙස සලකනු ලැබුවහොත්, ඔබගේ සාක්කුවෙන් ගෙවිය යුතු කොටස වැඩි විය හැක.",
                bn: "চিকিৎসার পরে জরুরি চিকিৎসা ব্যবস্থাপনা ফি আলাদাভাবে চার্জ করা হয়, এবং যদি আপনার অবস্থা হালকা বলে বিবেচিত হয়, তবে আপনার পকেট থেকে পরিশোধের অংশ বাড়তে পারে।",
                my: "ကုသမှုခံယူပြီးနောက် အရေးပေါ်ဆေးဘက်ဆိုင်ရာ စီမံခန့်ခွဲမှုအခကြေးငွေကို သီးခြားကောက်ခံမည်ဖြစ်ပြီး၊ သင်၏အခြေအနေကို အသေးစားဟု သတ်မှတ်ပါက၊ သင်ကိုယ်တိုင်ပေးချေရမည့် ဝန်ထုပ်ဝန်ပိုး တိုးလာနိုင်ပါသည်။",
                mn: "Эмчилгээний дараа яаралтай тусламжийн удирдлагын төлбөрийг нэмэлтээр авдаг бөгөөд хэрэв таны нөхцөл байдлыг хөнгөн гэж үзвэл таны халааснаас төлөх хувь нэмэгдэж болно.",
                lo: "ຫຼັງຈາກການປິ່ນປົວ, ຄ່າທໍານຽມການຄຸ້ມຄອງການແພດສຸກເສີນຈະຖືກເກັບເພີ່ມຕ່າງຫາກ, ແລະ ຖ້າສະພາບຂອງທ່ານຖືກພິຈາລະນາວ່າບໍ່ຮຸນແຮງ, ສ່ວນທີ່ທ່ານຕ້ອງຈ່າຍເອງອາດຈະເພີ່ມຂຶ້ນ.",
                tet:
                    "Hafoin tratamentu, taxa jestaun médika emerjénsia sei kobra liuliu, no se Ita-nia kondisaun konsidera la grave, Ita-nia parte ne'ebé selu husi bolsu bele sa'e.",
                ne: "उपचार पछि, आपतकालीन चिकित्सा व्यवस्थापन शुल्क छुट्टै लिइन्छ र यदि तपाईंको अवस्था सामान्य मानिन्छ भने, तपाईंले आफ्नो खल्तीबाट तिर्नुपर्ने अंश बढ्न सक्छ।",
                zh: '急诊就诊后会另行收取急诊医疗管理费，若被判定为轻症，本人自付比例可能会提高。',
                vi: 'Sau khi khám tại phòng cấp cứu sẽ bị tính thêm phí quản lý y tế cấp cứu riêng, và nếu được chẩn đoán là nhẹ thì phần tự chi trả có thể tăng lên.',
                uz: "Davolashdan soʻng favqulodda tibbiy boshqaruv toʻlovi alohida undiriladi va agar sizning ahvolingiz yengil deb baholansa, oʻzingiz toʻlaydigan ulush oshishi mumkin.",
              ),
              L10nText(
                ko: '야간·공휴일 진료는 가산료가 붙을 수 있으니 급하지 않다면 야간 진료 병원(2페이지)을 먼저 고려하세요.',
                en: 'Night and holiday treatment may incur an additional surcharge, so if it is not urgent, consider a night-hours hospital first (see page 2).',
                tr: "Gece ve tatil tedavisi ek bir ücret gerektirebilir, bu nedenle acil değilse, öncelikle gece açık bir hastaneyi düşünün (bkz. sayfa 2).",
                tg: "Табобати шабона ва рӯзҳои ид метавонад ҳаққи иловагиро талаб кунад, аз ин рӯ, агар фавқулодда набошад, аввал беморхонаи шабонарӯзиро баррасӣ кунед (нигаред ба саҳифаи 2).",
                fil:
                    "Ang paggamot sa gabi at holiday ay maaaring mangailangan ng karagdagang bayad, kaya kung hindi ito emergency, isaalang-alang muna ang isang ospital na bukas sa gabi (tingnan ang pahina 2).",
                ur: "رات اور چھٹیوں کے علاج کے لیے اضافی فیس کی ضرورت پڑ سکتی ہے، لہذا اگر یہ ہنگامی صورتحال نہیں ہے، تو پہلے رات کو کھلے ہسپتال پر غور کریں (ملاحظہ کریں صفحہ 2)۔",
                th: "การรักษาในเวลากลางคืนและวันหยุดอาจมีค่าใช้จ่ายเพิ่มเติม ดังนั้นหากไม่ฉุกเฉิน ให้พิจารณาโรงพยาบาลที่เปิดทำการในเวลากลางคืนก่อน (ดูหน้า 2)",
                ky: "Түнкү жана майрам күндөрү дарылоо кошумча акы талап кылышы мүмкүн, андыктан шашылыш болбосо, биринчи кезекте түнкүсүн ачык оорукананы карап көрүңүз (караңыз 2-бет).",
                km: "ការព្យាបាលពេលយប់ និងថ្ងៃឈប់សម្រាកអាចតម្រូវឱ្យមានថ្លៃសេវាបន្ថែម ដូច្នេះប្រសិនបើវាមិនបន្ទាន់ទេ សូមពិចារណាមន្ទីរពេទ្យដែលបើកពេលយប់ជាមុនសិន (សូមមើលទំព័រ 2)។",
                id: "Perawatan malam hari dan hari libur mungkin memerlukan biaya tambahan, jadi jika tidak darurat, pertimbangkan rumah sakit yang buka di malam hari terlebih dahulu (lihat halaman 2).",
                si: "රාත්‍රී සහ නිවාඩු ප්‍රතිකාර සඳහා අමතර ගාස්තුවක් අවශ්‍ය විය හැකි බැවින්, එය හදිසි නොවේ නම්, පළමුව රාත්‍රියේ විවෘතව ඇති රෝහලක් සලකා බලන්න (පිටුව 2 බලන්න).",
                bn: "রাতের বেলা এবং ছুটির দিনে চিকিৎসার জন্য অতিরিক্ত ফি লাগতে পারে, তাই যদি জরুরি না হয়, তবে প্রথমে রাতে খোলা একটি হাসপাতাল বিবেচনা করুন (পৃষ্ঠা 2 দেখুন)।",
                my: "ညပိုင်းနှင့် အားလပ်ရက် ကုသမှုအတွက် အပိုအခကြေးငွေ လိုအပ်နိုင်သောကြောင့် အရေးပေါ်မဟုတ်ပါက၊ ဦးစွာ ညပိုင်းဖွင့်သော ဆေးရုံကို စဉ်းစားပါ (စာမျက်နှာ 2 ကို ကြည့်ပါ)။",
                mn: "Шөнийн болон баярын эмчилгээнд нэмэлт төлбөр шаардагдаж болно, тиймээс яаралтай биш бол эхлээд шөнө ажилладаг эмнэлгийг бодож үзээрэй (хуудас 2-г үзнэ үү).",
                lo: "ການປິ່ນປົວໃນຕອນກາງຄືນ ແລະ ວັນພັກອາດຈະມີຄ່າທໍານຽມເພີ່ມເຕີມ, ດັ່ງນັ້ນຖ້າບໍ່ແມ່ນກໍລະນີສຸກເສີນ, ໃຫ້ພິຈາລະນາໂຮງໝໍທີ່ເປີດໃນຕອນກາງຄືນກ່ອນ (ເບິ່ງໜ້າ 2).",
                tet:
                    "Tratamentu kalan no feriadu bele presiza taxa adisionál, tanba ne'e, se la'ós emerjénsia, konsidera uluk ospitál ida ne'ebé loke kalan (haree pájina 2).",
                ne: "रात र बिदाको उपचारमा अतिरिक्त शुल्क लाग्न सक्छ, त्यसैले यदि यो आपतकालीन छैन भने, पहिले रातमा खुल्ने अस्पतालको बारेमा विचार गर्नुहोस् (पृष्ठ 2 हेर्नुहोस्)।",
                zh: '夜间、公休日诊疗可能会加收附加费，如果情况不紧急，请优先考虑夜间诊疗医院（见第2页）。',
                vi: 'Khám vào ban đêm, ngày lễ có thể bị tính thêm phụ phí, nếu không quá khẩn cấp hãy cân nhắc bệnh viện khám đêm trước (xem trang 2).',
                uz: "Tungi va bayram kunlari davolash qoʻshimcha toʻlovga olib kelishi mumkin, shuning uchun agar shoshilinch boʻlmasa, avval tungi ishlaydigan shifoxonani koʻrib chiqing (2-sahifaga qarang).",
              ),
            ],
          ),
        ],
      ),
      BookPage(
        title: L10nText(
          ko: '건강보험 적용 여부 확인',
          en: 'Checking Your Health Insurance Coverage',
          tr: "Sağlık Sigortası Kapsamınızı Kontrol Etme",
          tg: "Санҷиши фарогирии суғуртаи тиббии шумо",
          fil: "Pagsusuri sa Saklaw ng Iyong Health Insurance",
          ur: "صحت بیمہ کی کوریج کی جانچ کرنا",
          th: "การตรวจสอบความคุ้มครองประกันสุขภาพของคุณ",
          ky: "Медициналык камсыздандырууңуздун камтылышын текшерүү",
          km: "ការត្រួតពិនិត្យការគ្របដណ្តប់ធានារ៉ាប់រងសុខភាពរបស់អ្នក",
