          si: "ඔබගේ සෞඛ්‍ය රක්ෂණ ආවරණය පරීක්ෂා කිරීම",
          bn: "আপনার স্বাস্থ্য বীমা কভারেজ পরীক্ষা করা",
          my: "ကျန်းမာရေးအာမခံ အကျုံးဝင်မှုကို စစ်ဆေးခြင်း",
          mn: "Эрүүл мэндийн даатгалын хамрах хүрээг шалгах",
          lo: "ການກວດສອບການຄຸ້ມຄອງປະກັນໄພສຸຂະພາບຂອງທ່ານ",
          tet: "Verifika Ita-nia Kobertura Seguru Saúde",
          ne: "आफ्नो स्वास्थ्य बीमा कभरेज जाँच गर्ने",
          zh: '确认健康保险适用情况',
          vi: 'Kiểm tra tình trạng áp dụng bảo hiểm y tế',
          uz: "Tibbiy sugʻurta qoplamangizni tekshirish",
        ),
        summary: L10nText(
          ko: '건강보험 가입 여부에 따라 진료비 부담이 크게 달라지므로, 본인이 직장가입자인지 지역가입자인지 먼저 확인해야 합니다.',
          en: 'Your treatment costs vary greatly depending on whether you have health insurance, so first check whether you are a workplace-based subscriber or a self-employed/regional subscriber.',
          tr: "Tedavi masraflarınız, sağlık sigortanız olup olmadığına bağlı olarak büyük ölçüde değişir, bu nedenle öncelikle işyeri tabanlı bir abone mi yoksa serbest meslek sahibi/bölgesel bir abone mi olduğunuzu kontrol edin.",
          tg: "Хароҷоти табобати шумо вобаста ба доштани суғуртаи тиббӣ хеле фарқ мекунад, аз ин рӯ, аввал санҷед, ки оё шумо муштарии корхона ҳастед ё мустақил/минтақавӣ.",
          fil:
              "Ang iyong mga gastos sa paggamot ay lubhang nag-iiba depende kung mayroon kang health insurance, kaya suriin muna kung ikaw ay isang workplace-based subscriber o isang self-employed/regional subscriber.",
          ur: "آپ کے علاج کے اخراجات اس بات پر منحصر ہوتے ہیں کہ آیا آپ کے پاس صحت بیمہ ہے یا نہیں، لہذا پہلے یہ چیک کریں کہ آیا آپ کام کی جگہ پر مبنی سبسکرائبر ہیں یا خود روزگار/علاقائی سبسکرائبر ہیں۔",
          th: "ค่าใช้จ่ายในการรักษาของคุณจะแตกต่างกันอย่างมากขึ้นอยู่กับว่าคุณมีประกันสุขภาพหรือไม่ ดังนั้นให้ตรวจสอบก่อนว่าคุณเป็นผู้สมัครแบบอิงสถานที่ทำงาน หรือผู้ประกอบอาชีพอิสระ/ผู้สมัครแบบภูมิภาค",
          ky: "Дарылоо чыгымдары медициналык камсыздандырууңуз бар же жок экенине жараша абдан өзгөрөт, андыктан биринчи кезекте сиз жумуш ордуна негизделген абонентсизби же жеке ишкер/аймактык абонентсизби, текшериңиз.",
          km: "ថ្លៃព្យាបាលរបស់អ្នកប្រែប្រួលយ៉ាងខ្លាំងអាស្រ័យលើថាតើអ្នកមានធានារ៉ាប់រងសុខភាពឬអត់ ដូច្នេះដំបូងត្រូវពិនិត្យមើលថាតើអ្នកជាអតិថិជនដែលមានមូលដ្ឋានលើកន្លែងធ្វើការ ឬជាអតិថិជនឯករាជ្យ/ក្នុងតំបន់។",
          id: "Biaya perawatan Anda sangat bervariasi tergantung pada apakah Anda memiliki asuransi kesehatan, jadi periksa terlebih dahulu apakah Anda adalah pelanggan berbasis tempat kerja atau pelanggan wiraswasta/regional.",
          si: "ඔබගේ ප්‍රතිකාර වියදම් ඔබ සෞඛ්‍ය රක්ෂණයෙන් ආවරණය කර තිබේද නැද්ද යන්න මත විශාල වශයෙන් වෙනස් වේ, එබැවින් පළමුව ඔබ සේවා ස්ථානය පදනම් කරගත් ග්‍රාහකයෙක්ද නැතහොත් ස්වයං රැකියා/ප්‍රාදේශීය ග්‍රාහකයෙක්ද යන්න පරීක්ෂා කරන්න.",
          bn: "আপনার চিকিৎসার খরচ আপনার স্বাস্থ্য বীমা আছে কিনা তার উপর নির্ভর করে ব্যাপকভাবে পরিবর্তিত হয়, তাই প্রথমে আপনি কর্মস্থল-ভিত্তিক গ্রাহক নাকি স্ব-নিযুক্ত/আঞ্চলিক গ্রাহক তা পরীক্ষা করুন।",
          my: "သင်၏ကုသမှုကုန်ကျစရိတ်များသည် သင့်တွင် ကျန်းမာရေးအာမခံရှိမရှိအပေါ် မူတည်၍ များစွာကွာခြားသောကြောင့်၊ သင်သည် လုပ်ငန်းခွင်အခြေပြု စာရင်းသွင်းသူ သို့မဟုတ် ကိုယ်ပိုင်လုပ်ငန်းရှင်/ဒေသတွင်း စာရင်းသွင်းသူ ဟုတ်မဟုတ်ကို ဦးစွာစစ်ဆေးပါ။",
          mn: "Эмчилгээний зардал нь таны эрүүл мэндийн даатгалтай эсэхээс хамаарч ихээхэн өөрчлөгддөг тул эхлээд та ажлын байран дээр суурилсан захиалагч уу эсвэл хувиараа хөдөлмөр эрхлэгч/бүс нутгийн захиалагч уу гэдгээ шалгаарай.",
          lo: "ຄ່າໃຊ້ຈ່າຍໃນການປິ່ນປົວຂອງທ່ານແຕກຕ່າງກັນຢ່າງຫຼວງຫຼາຍຂຶ້ນຢູ່ກັບວ່າທ່ານມີປະກັນໄພສຸຂະພາບຫຼືບໍ່, ດັ່ງນັ້ນ, ກ່ອນອື່ນໝົດໃຫ້ກວດເບິ່ງວ່າທ່ານເປັນຜູ້ສະໝັກໃຊ້ປະກັນໄພທີ່ອີງໃສ່ບ່ອນເຮັດວຽກ ຫຼື ເປັນຜູ້ປະກອບອາຊີບອິດສະຫຼະ/ຜູ້ສະໝັກໃຊ້ປະກັນໄພພາກພື້ນ.",
          tet:
              "Kustu tratamentu sei la hanesan tebes depende ba Ita iha seguru saúde ka lae, tanba ne'e, verifika uluk se Ita nu'udar membru bazeia ba fatin servisu ka membru autónomu/rejionál.",
          ne: "तपाईंको उपचार खर्च तपाईंको स्वास्थ्य बीमा छ वा छैन भन्नेमा धेरै निर्भर गर्दछ, त्यसैले पहिले तपाईं कार्यस्थल-आधारित ग्राहक हुनुहुन्छ वा स्वरोजगार/क्षेत्रीय ग्राहक हुनुहुन्छ भनी जाँच गर्नुहोस्।",
          zh: '是否参加健康保险会极大影响诊疗费用的负担，因此请先确认自己属于职场参保人还是地区参保人。',
          vi: 'Chi phí khám chữa bệnh sẽ khác nhau rất nhiều tùy theo việc bạn có tham gia bảo hiểm y tế hay không, vì vậy trước tiên cần xác định bạn là người tham gia theo nơi làm việc hay người tham gia theo khu vực.',
          uz: "Sizning davolanish xarajatlaringiz tibbiy sugʻurtangiz bor-yoʻqligiga qarab sezilarli darajada farq qiladi, shuning uchun avval ish joyiga asoslangan obunachi yoki oʻz-oʻzini ish bilan taʼminlagan/hududiy obunachi ekanligingizni tekshiring.",
        ),
        blocks: [
          ContentBlock(
            title: L10nText(
              ko: '가입 유형',
              en: 'Types of Enrollment',
              tr: "Kayıt Türleri",
              tg: "Намудҳои бақайдгирӣ",
              fil: "Mga Uri ng Pagpaparehistro",
              ur: "رجسٹریشن کی اقسام",
              th: "ประเภทการลงทะเบียน",
              ky: "Каттоо түрлөрү",
              km: "ប្រភេទនៃការចុះឈ្មោះ",
              id: "Jenis Pendaftaran",
              si: "ලියාපදිංචි වර්ග",
              bn: "নিবন্ধনের প্রকারভেদ",
              my: "စာရင်းသွင်းခြင်း အမျိုးအစားများ",
              mn: "Бүртгэлийн төрлүүд",
              lo: "ປະເພດການລົງທະບຽນ",
              tet: "Tipu Rejistu sira",
              ne: "दर्ताका प्रकारहरू",
              zh: '参保类型',
              vi: 'Loại hình tham gia bảo hiểm',
              uz: "Roʻyxatdan oʻtish turlari",
            ),
            bullets: [
              L10nText(
                ko: '직장가입자: 사업장에 고용되면 체류기간과 관계없이 가입, 보험료는 근로자·사업주가 절반씩 부담',
                en: 'Workplace-based subscriber: Enrolled as soon as you are employed at a workplace, regardless of length of stay; the premium is split equally between employee and employer',
                tr: "İşyeri tabanlı abone: Bir işyerinde istihdam edildiğiniz anda, kalış sürenizden bağımsız olarak kaydolursunuz; prim çalışan ve işveren arasında eşit olarak bölünür",
                tg: "Муштарии корхона: Ҳамин ки шумо дар корхона кор мекунед, новобаста аз давомнокии будубоши шумо ба қайд гирифта мешавед; мукофот байни корманд ва корфармо баробар тақсим карда мешавад.",
                fil:
                    "Workplace-based subscriber: Sa sandaling ikaw ay nagtatrabaho sa isang lugar ng trabaho, ikaw ay awtomatikong nakarehistro anuman ang tagal ng iyong pananatili; ang premium ay pantay na hinahati sa pagitan ng empleyado at employer.",
                ur: "کام کی جگہ پر مبنی سبسکرائبر: جیسے ہی آپ کسی کام کی جگہ پر ملازم ہوتے ہیں، آپ اپنی قیام کی مدت سے قطع نظر رجسٹر ہو جاتے ہیں؛ پریمیم ملازم اور آجر کے درمیان برابر تقسیم ہوتا ہے",
                th: "ผู้สมัครแบบอิงสถานที่ทำงาน: คุณจะได้รับการลงทะเบียนทันทีที่คุณได้รับการจ้างงานในสถานที่ทำงาน โดยไม่คำนึงถึงระยะเวลาที่คุณพำนักอยู่; เบี้ยประกันจะถูกแบ่งเท่า ๆ กันระหว่างพนักงานและนายจ้าง",
                ky: "Жумуш ордуна негизделген абонент: Жумушка орношкондон кийин, жашоо мөөнөтүңүзгө карабастан катталасыз; премия кызматкер менен иш берүүчүнүн ортосунда тең бөлүнөт.",
                km: "អតិថិជនដែលមានមូលដ្ឋានលើកន្លែងធ្វើការ៖ នៅពេលអ្នកត្រូវបានជួលនៅកន្លែងធ្វើការ អ្នកនឹងត្រូវបានចុះឈ្មោះដោយមិនគិតពីរយៈពេលស្នាក់នៅរបស់អ្នក។ បុព្វលាភត្រូវបានបែងចែកស្មើៗគ្នារវាងនិយោជិត និងនិយោជក។",
                id: "Pelanggan berbasis tempat kerja: Anda terdaftar segera setelah Anda dipekerjakan di tempat kerja, terlepas dari durasi tinggal Anda; premi dibagi rata antara karyawan dan pemberi kerja.",
                si: "සේවා ස්ථානය පදනම් කරගත් ග්‍රාහකයා: ඔබ සේවා ස්ථානයක සේවය කරන විට, ඔබගේ රැඳී සිටීමේ කාලය නොසලකා ඔබ ලියාපදිංචි වේ; වාරිකය සේවකයා සහ සේවායෝජකයා අතර සමානව බෙදී යයි.",
                bn: "কর্মস্থল-ভিত্তিক গ্রাহক: কর্মস্থলে নিযুক্ত হওয়ার সাথে সাথে, আপনার থাকার সময়কাল নির্বিশেষে আপনি নিবন্ধিত হন; প্রিমিয়াম কর্মচারী এবং নিয়োগকর্তার মধ্যে সমানভাবে ভাগ করা হয়।",
                my: "လုပ်ငန်းခွင်အခြေပြု စာရင်းသွင်းသူ- လုပ်ငန်းခွင်တစ်ခုတွင် အလုပ်ခန့်ထားသည်နှင့် သင်၏နေထိုင်မှုကာလ မည်မျှပင်ရှိစေကာမူ စာရင်းသွင်းရပါမည်။ ပရီမီယံကို ဝန်ထမ်းနှင့် အလုပ်ရှင်အကြား တန်းတူခွဲဝေပေးပါသည်။",
                mn: "Ажлын байран дээр суурилсан захиалагч: Та ажлын байранд ажилд орсон даруйдаа, оршин суух хугацаанаас үл хамааран бүртгүүлдэг; шимтгэлийг ажилтан болон ажил олгогч тэнцүү хувааж төлдөг.",
                lo: "ຜູ້ສະໝັກໃຊ້ປະກັນໄພທີ່ອີງໃສ່ບ່ອນເຮັດວຽກ: ທັນທີທີ່ທ່ານໄດ້ຮັບການຈ້າງງານຢູ່ບ່ອນເຮັດວຽກ, ທ່ານຈະຖືກລົງທະບຽນໂດຍບໍ່ຄໍານຶງເຖິງໄລຍະເວລາທີ່ທ່ານພັກເຊົາ; ຄ່າປະກັນໄພຈະຖືກແບ່ງປັນເທົ່າທຽມກັນລະຫວ່າງພະນັກງານ ແລະ ນາຍຈ້າງ.",
                tet:
                    "Membru bazeia ba fatin servisu: Bainhira Ita hetan empregu iha fatin servisu ida, Ita sei rejista kedas, la depende ba tempu Ita hela; prémiu sei fahe hanesan entre traballadór no empregadór.",
                ne: "कार्यस्थल-आधारित ग्राहक: तपाईं कुनै कार्यस्थलमा रोजगारमा लाग्ने बित्तिकै, तपाईंको बसाइको अवधि जस्तोसुकै भए पनि दर्ता हुनुहुन्छ; प्रिमियम कर्मचारी र रोजगारदाताबीच समान रूपमा विभाजित हुन्छ।",
                zh: '职场参保人：受雇于用人单位后，无论居留期限长短均自动参保，保险费由劳动者和用人单位各承担一半',
                vi: 'Người tham gia theo nơi làm việc: Khi được tuyển dụng tại nơi làm việc thì tham gia bảo hiểm bất kể thời gian lưu trú, phí bảo hiểm do người lao động và chủ sử dụng lao động chia đều mỗi bên một nửa',
                uz: "Ish joyiga asoslangan obunachi: Ish joyida ishga joylashishingiz bilanoq, qolish muddatingizdan qatʼi nazar, roʻyxatdan oʻtasiz; mukofot ishchi va ish beruvchi oʻrtasida teng taqsimlanadi.",
              ),
              L10nText(
                ko: '지역가입자: 국내 체류 6개월 이상이면서 직장가입 대상이 아닌 경우 가입, 보험료 전액 본인 부담',
                en: 'Self-employed/regional subscriber: Applies if you have stayed in Korea for 6 months or more and are not a workplace-based subscriber; you bear the entire premium yourself',
                tr: "Serbest meslek sahibi/bölgesel abone: Kore'de 6 ay veya daha uzun süre kaldıysanız ve işyeri tabanlı bir abone değilseniz geçerlidir; primin tamamını kendiniz karşılarsınız",
                tg: "Муштарии мустақил/минтақавӣ: Агар шумо дар Корея 6 моҳ ё бештар аз он монда бошед ва муштарии корхона набошед, эътибор дорад; шумо тамоми мукофотро худатон мепӯшонед.",
                fil:
                    "Self-employed/regional subscriber: Nalalapat kung nanatili ka sa Korea nang 6 buwan o higit pa at hindi isang workplace-based subscriber; ikaw mismo ang sumasagot sa buong premium.",
                ur: "خود روزگار/علاقائی سبسکرائبر: اگر آپ کوریا میں 6 ماہ یا اس سے زیادہ عرصے سے مقیم ہیں اور کام کی جگہ پر مبنی سبسکرائبر نہیں ہیں تو لاگو ہوتا ہے؛ آپ خود پورا پریمیم ادا کرتے ہیں",
                th: "ผู้ประกอบอาชีพอิสระ/ผู้สมัครแบบภูมิภาค: ใช้ได้หากคุณพำนักอยู่ในเกาหลีเป็นเวลา 6 เดือนหรือนานกว่านั้น และไม่ใช่ผู้สมัครแบบอิงสถานที่ทำงาน; คุณจะรับผิดชอบเบี้ยประกันทั้งหมดด้วยตนเอง",
                ky: "Жеке ишкер/аймактык абонент: Эгер сиз Кореяда 6 ай же андан көп убакыт жашаган болсоңуз жана жумуш ордуна негизделген абонент болбосоңуз колдонулат; премиянын баарын өзүңүз төлөйсүз.",
                km: "អតិថិជនឯករាជ្យ/ក្នុងតំបន់៖ អនុវត្តប្រសិនបើអ្នកបានស្នាក់នៅក្នុងប្រទេសកូរ៉េរយៈពេល 6 ខែ ឬច្រើនជាងនេះ ហើយមិនមែនជាអតិថិជនដែលមានមូលដ្ឋានលើកន្លែងធ្វើការ។ អ្នកត្រូវបង់បុព្វលាភពេញលេញដោយខ្លួនឯង។",
                id: "Pelanggan wiraswasta/regional: Berlaku jika Anda telah tinggal di Korea selama 6 bulan atau lebih dan bukan pelanggan berbasis tempat kerja; Anda menanggung seluruh premi sendiri.",
                si: "ස්වයං රැකියා/ප්‍රාදේශීය ග්‍රාහකයා: ඔබ කොරියාවේ මාස 6ක් හෝ ඊට වැඩි කාලයක් රැඳී සිට ඇත්නම් සහ සේවා ස්ථානය පදනම් කරගත් ග්‍රාහකයෙක් නොවේ නම් අදාළ වේ; ඔබ සම්පූර්ණ වාරිකයම දරයි.",
                bn: "স্ব-নিযুক্ত/আঞ্চলিক গ্রাহক: যদি আপনি কোরিয়াতে 6 মাস বা তার বেশি সময় ধরে থাকেন এবং কর্মস্থল-ভিত্তিক গ্রাহক না হন তবে প্রযোজ্য; আপনি নিজেই পুরো প্রিমিয়াম বহন করেন।",
                my: "ကိုယ်ပိုင်လုပ်ငန်းရှင်/ဒေသတွင်း စာရင်းသွင်းသူ- သင်သည် ကိုရီးယားတွင် 6 လ သို့မဟုတ် ထို့ထက်ပို၍ နေထိုင်ခဲ့ပြီး လုပ်ငန်းခွင်အခြေပြု စာရင်းသွင်းသူ မဟုတ်ပါက အကျုံးဝင်ပါသည်။ ပရီမီယံတစ်ခုလုံးကို သင်ကိုယ်တိုင် ကျခံရပါမည်။",
                mn: "Хувиараа хөдөлмөр эрхлэгч/бүс нутгийн захиалагч: Хэрэв та Солонгост 6 сар буюу түүнээс дээш хугацаагаар оршин суусан бөгөөд ажлын байран дээр суурилсан захиалагч биш бол хамаарна; шимтгэлийн бүх зардлыг өөрөө хариуцдаг.",
                lo: "ຜູ້ປະກອບອາຊີບອິດສະຫຼະ/ຜູ້ສະໝັກໃຊ້ປະກັນໄພພາກພື້ນ: ໃຊ້ໄດ້ຖ້າທ່ານໄດ້ພັກເຊົາຢູ່ໃນເກົາຫຼີເປັນເວລາ 6 ເດືອນ ຫຼື ຫຼາຍກວ່ານັ້ນ ແລະ ບໍ່ແມ່ນຜູ້ສະໝັກໃຊ້ປະກັນໄພທີ່ອີງໃສ່ບ່ອນເຮັດວຽກ; ທ່ານຈະຮັບຜິດຊອບຄ່າປະກັນໄພທັງໝົດດ້ວຍຕົນເອງ.",
                tet:
                    "Membru autónomu/rejionál: Aplika se Ita hela iha Koreia ba fulan 6 ka liu no la'ós membru bazeia ba fatin servisu; Ita rasik mak sei selu prémiu tomak.",
                ne: "स्वरोजगार/क्षेत्रीय ग्राहक: यदि तपाईं कोरियामा 6 महिना वा सोभन्दा बढी समय बस्नुभएको छ र कार्यस्थल-आधारित ग्राहक हुनुहुन्न भने लागू हुन्छ; तपाईंले सम्पूर्ण प्रिमियम आफैं तिर्नुहुन्छ।",
                zh: '地区参保人：在韩居留满6个月以上且不属于职场参保对象时参保，保险费全额由本人承担',
                vi: 'Người tham gia theo khu vực: Áp dụng khi lưu trú tại Hàn Quốc từ 6 tháng trở lên và không thuộc đối tượng tham gia theo nơi làm việc, phí bảo hiểm do bản thân chi trả toàn bộ',
                uz: "Oʻz-oʻzini ish bilan taʼminlagan/hududiy obunachi: Agar siz Koreyada 6 oy yoki undan koʻproq vaqt qolgan boʻlsangiz va ish joyiga asoslangan obunachi boʻlmasangiz qoʻllaniladi; siz butun mukofotni oʻzingiz toʻlaysiz.",
              ),
            ],
