                lo: "ອົງການປະກັນສຸຂະພາບແຫ່ງຊາດ ແລະ ສູນສາທາລະນະສຸກ ໄດ້ແຈກຢາຍແຜ່ນພັບຂໍ້ມູນສຸຂະພາບໃນພາສາຫຼັກໆ.",
