                tr: "Hastaneyi ziyaret etmeden önce tercüman müsaitliğini teyit etmek için BBB Kore'yi veya 1345'i önceden aramak bekleme sürenizi azaltmaya yardımcı olabilir.",
                tg: "Пешакӣ ба BBB Korea ё 1345 занг зада, мавҷудияти тарҷумонро пеш аз боздид аз беморхона тасдиқ кардан метавонад вақти интизории шуморо кам кунад.",
