                km: "ការហៅទូរសព្ទទៅ BBB Korea ឬ 1345 ជាមុន ដើម្បីបញ្ជាក់ពីភាពទំនេររបស់អ្នកបកប្រែ មុនពេលទៅមន្ទីរពេទ្យ អាចជួយកាត់បន្ថយពេលវេលារង់ចាំរបស់អ្នក។",
