                bn: "হাসপাতালে যাওয়ার আগে দোভাষীর প্রাপ্যতা নিশ্চিত করতে BBB কোরিয়া বা 1345-কে আগে থেকে কল করলে আপনার অপেক্ষার সময় কমাতে সাহায্য করতে পারে।",
                my: "ဆေးရုံသို့မသွားမီ ဘာသာပြန်ရရှိနိုင်မှုကို အတည်ပြုရန် BBB Korea သို့မဟုတ် 1345 သို့ ကြိုတင်ခေါ်ဆိုခြင်းသည် သင်၏စောင့်ဆိုင်းချိန်ကို လျှော့ချရန် ကူညီပေးနိုင်ပါသည်။",
                mn: "Эмнэлэгт очихоосоо өмнө орчуулагч байгаа эсэхийг баталгаажуулахын тулд BBB Korea эсвэл 1345 руу урьдчилан залгах нь таны хүлээх хугацааг багасгахад тусална.",
                lo: "ການໂທຫາ BBB Korea ຫຼື 1345 ລ່ວງໜ້າ ເພື່ອຢືນຢັນຄວາມພ້ອມຂອງນາຍພາສາ ກ່ອນໄປໂຮງໝໍ ສາມາດຊ່ວຍຫຼຸດຜ່ອນເວລາລໍຖ້າຂອງທ່ານໄດ້.",
                tet:
