                ne: "अस्पताल जानु अघि अनुवादकको उपलब्धता पुष्टि गर्न BBB कोरिया वा 1345 मा अग्रिम कल गर्नाले तपाईंको प्रतीक्षा समय घटाउन मद्दत गर्न सक्छ।",
                zh: '在前往医院之前，先致电BBB Korea或1345确认是否能连接口译，可以减少等待时间。',
                vi: 'Trước khi đến bệnh viện, hãy gọi trước cho BBB Korea hoặc 1345 để xác nhận có thể kết nối phiên dịch hay không, việc này giúp giảm thời gian chờ đợi.',
                uz: "Shifoxonaga tashrif buyurishdan oldin tarjimon mavjudligini tasdiqlash uchun BBB Korea yoki 1345 raqamiga oldindan qoʻngʻiroq qilish kutish vaqtingizni qisqartirishga yordam beradi.",
