        summary: L10nText(
          ko: '외국인근로자가 챙겨야 할 보험은 크게 4대 사회보험과 외국인전용보험 두 갈래이며, 가입 주체와 가입 기한이 각각 다릅니다.',
          en: 'The insurance foreign workers need to be aware of falls into two broad categories — the four major social insurances and insurance exclusively for foreigners — and each differs in who must enroll and by when.',
          tr: "Yabancı işçilerin bilmesi gereken sigorta, iki geniş kategoriye ayrılır — dört ana sosyal sigorta ve sadece yabancılara özel sigorta — ve her biri kimin ne zaman kaydolması gerektiği konusunda farklılık gösterir.",
          tg: "Суғуртае, ки коргарони хориҷӣ бояд донанд, ба ду категорияи калон тақсим мешавад — чор суғуртаи асосии иҷтимоӣ ва суғуртаи танҳо барои хориҷиён — ва ҳар яке дар бораи кӣ ва кай бояд сабти ном шавад, фарқ мекунад.",
          fil:
              "Ang seguro na kailangang malaman ng mga dayuhang manggagawa ay nahahati sa dalawang malawak na kategorya — ang apat na pangunahing social insurance at ang seguro na partikular para sa mga dayuhan — at bawat isa ay may pagkakaiba kung sino ang dapat magparehistro at kailan.",
          ur: "غیر ملکی کارکنوں کو جن انشورنس کے بارے میں جاننے کی ضرورت ہے، وہ دو بڑی اقسام میں تقسیم ہوتی ہیں — چار اہم سماجی انشورنس اور صرف غیر ملکیوں کے لیے مخصوص انشورنس — اور ہر ایک میں یہ فرق ہوتا ہے کہ کس کو کب اندراج کرانا چاہیے۔",
          th: "ประกันภัยที่แรงงานต่างชาติต้องทราบแบ่งออกเป็นสองประเภทใหญ่ ๆ ได้แก่ ประกันสังคมหลักสี่ประเภท และประกันภัยเฉพาะสำหรับชาวต่างชาติ ซึ่งแต่ละประเภทมีข้อกำหนดที่แตกต่างกันว่าใครควรลงทะเบียนเมื่อใด",
          ky: "Чет элдик жумушчулар билиши керек болгон камсыздандыруу эки чоң категорияга бөлүнөт — төрт негизги социалдык камсыздандыруу жана чет элдиктерге гана тиешелүү камсыздандыруу — жана алардын ар бири ким качан катталышы керектиги боюнча айырмаланат.",
          km: "ការធានារ៉ាប់រងដែលកម្មករនិយោជិតបរទេសត្រូវដឹង ត្រូវបានបែងចែកជាពីរប្រភេទធំៗ — ការធានារ៉ាប់រងសង្គមសំខាន់ៗចំនួនបួន និងការធានារ៉ាប់រងសម្រាប់តែជនបរទេសប៉ុណ្ណោះ — ហើយនីមួយៗមានភាពខុសគ្នាអំពីអ្នកណាគួរចុះឈ្មោះ និងពេលណា។",
          id: "Asuransi yang perlu diketahui oleh pekerja asing terbagi menjadi dua kategori besar — empat asuransi sosial utama dan asuransi khusus asing — dan masing-masing berbeda dalam hal siapa yang harus mendaftar dan kapan.",
          si: "විදේශීය සේවකයින් දැනගත යුතු රක්ෂණය පුළුල් කාණ්ඩ දෙකකට බෙදා ඇත - ප්‍රධාන සමාජ රක්ෂණ හතර සහ විදේශිකයන් සඳහා පමණක් වන රක්ෂණය - සහ එක් එක් අය ලියාපදිංචි විය යුත්තේ කවදාද යන්න වෙනස් වේ.",
          bn: "বিদেশী কর্মীদের যে বীমা সম্পর্কে জানতে হবে তা দুটি বিস্তৃত বিভাগে বিভক্ত — চারটি প্রধান সামাজিক বীমা এবং শুধুমাত্র বিদেশীদের জন্য নির্দিষ্ট বীমা — এবং প্রতিটি কখন কাকে নিবন্ধন করতে হবে সে বিষয়ে ভিন্ন।",
          my: "နိုင်ငံခြားသားအလုပ်သမားများ သိထားသင့်သည့် အာမခံကို အဓိကအမျိုးအစားနှစ်မျိုး ခွဲခြားထားသည်- အဓိကလူမှုဖူလုံရေးအာမခံလေးမျိုးနှင့် နိုင်ငံခြားသားများအတွက်သာ သီးသန့်အာမခံတို့ဖြစ်သည်။ တစ်ခုချင်းစီတွင် မည်သူက မည်သည့်အချိန်တွင် စာရင်းသွင်းရမည်ဆိုသည့် ကွဲပြားမှုများရှိသည်။",
          mn: "Гадаад ажилчдын мэдэх ёстой даатгал нь хоёр том ангилалд хуваагддаг — дөрвөн үндсэн нийгмийн даатгал болон зөвхөн гадаадын иргэдэд зориулсан даатгал — бөгөөд тус бүр нь хэн хэзээ бүртгүүлэх ёстойгоороо ялгаатай.",
          lo: "ປະກັນໄພທີ່ແຮງງານຕ່າງປະເທດຄວນຮູ້ ແມ່ນແບ່ງອອກເປັນສອງປະເພດໃຫຍ່ຄື: ປະກັນສັງຄົມຫຼັກສີ່ປະເພດ ແລະ ປະກັນໄພສະເພາະຄົນຕ່າງປະເທດ, ເຊິ່ງແຕ່ລະປະເພດມີຄວາມແຕກຕ່າງກັນໃນເລື່ອງຂອງໃຜຄວນລົງທະບຽນເມື່ອໃດ.",
          tet:
              "Seguru ne'ebé traballadór estranjeiru sira presiza hatene fahe ba kategoria boot rua — seguru sosiál prinsipál haat no seguru espesífiku ba estranjeiru sira de'it — no ida-idak la hanesan kona-ba sé mak presiza rejista no bainhira.",
          ne: "विदेशी कामदारहरूले जान्नुपर्ने बीमा दुई मुख्य वर्गमा विभाजित छ — चार मुख्य सामाजिक बीमा र विदेशीहरूका लागि मात्र विशेष बीमा — र प्रत्येकले कसले कहिले दर्ता गर्नुपर्छ भन्नेमा फरक पार्छ।",
          zh: '外国劳工需要关注的保险大致分为两类：四大社会保险和外国人专用保险，两者的参保主体和参保期限各不相同。',
          vi: 'Bảo hiểm mà lao động nước ngoài cần lưu ý được chia thành hai nhóm lớn: 4 loại bảo hiểm xã hội chính và bảo hiểm dành riêng cho người nước ngoài, mỗi loại có đối tượng tham gia và thời hạn tham gia khác nhau.',
          uz: "Xorijiy ishchilar bilishi kerak boʻlgan sugʻurta ikki keng toifaga boʻlinadi — toʻrtta asosiy ijtimoiy sugʻurta va faqat xorijliklar uchun sugʻurta — va har biri kim va qachon roʻyxatdan oʻtishi kerakligi bilan farq qiladi.",
        ),
