                km: "ការធានារ៉ាប់រងសំណងគ្រោះថ្នាក់ការងារ (ជាកាតព្វកិច្ចសម្រាប់មនុស្សគ្រប់គ្នា) · ការធានារ៉ាប់រងសុខភាព (ជាកាតព្វកិច្ច) · ប្រាក់សោធនជាតិ (ផ្អែកលើគោលការណ៍ទៅវិញទៅមក) · ការធានារ៉ាប់រងការងារ (ប្រែប្រួលទៅតាមប្រភេទទិដ្ឋាការ) — ការចុះឈ្មោះត្រូវបានធ្វើឡើងដោយនិយោជក",
