                si: "කාර්මික අනතුරු වන්දි රක්ෂණය (සියලු දෙනාටම අනිවාර්ය) · සෞඛ්‍ය රක්ෂණය (අනිවාර්ය) · ජාතික විශ්‍රාම වැටුප (අන්‍යෝන්‍ය පදනම මත) · රැකියා රක්ෂණය (වීසා වර්ගය අනුව වෙනස් වේ) — ලියාපදිංචිය සේවායෝජකයා විසින් සිදු කරනු ලැබේ.",
