                lo: "ປະກັນໄພຄ່າຊົດເຊີຍອຸບັດຕິເຫດໃນການເຮັດວຽກ (ບັງຄັບສຳລັບທຸກຄົນ) · ປະກັນສຸຂະພາບ (ບັງຄັບ) · ເງິນບໍານານແຫ່ງຊາດ (ອີງຕາມຫຼັກການຕ່າງຕອບແທນ) · ປະກັນການຈ້າງງານ (ແຕກຕ່າງກັນໄປຕາມປະເພດວີຊາ) — ການລົງທະບຽນແມ່ນເຮັດໂດຍນາຍຈ້າງ.",
