                ky: "Өндүрүштүк кырсыктан компенсациялык камсыздандырууга катталбаган жумуш ордунда кырсык болсо дагы, жумушчу компенсация ала алат (иш берүүчү кийин мамлекетке кайтарып бериши керек).",
