                id: "Bahkan jika terjadi kecelakaan di tempat kerja yang tidak terdaftar dalam asuransi kompensasi kecelakaan kerja, pekerja masih dapat menerima kompensasi (pemberi kerja kemudian harus mengganti rugi negara).",
                si: "කාර්මික අනතුරු වන්දි රක්ෂණය සඳහා ලියාපදිංචි නොවූ සේවා ස්ථානයක අනතුරක් සිදුවුවහොත්, සේවකයාට තවමත් වන්දි ලබා ගත හැකිය (සේවායෝජකයා පසුව රජයට ආපසු ගෙවිය යුතුය).",
                bn: "যদি শিল্প দুর্ঘটনা ক্ষতিপূরণ বীমাতে নিবন্ধিত নয় এমন কর্মস্থলে দুর্ঘটনা ঘটে, তবুও কর্মী ক্ষতিপূরণ পেতে পারেন (নিয়োগকর্তাকে পরে সরকারকে পরিশোধ করতে হবে)।",
                my: "လုပ်ငန်းခွင်ထိခိုက်မှုလျော်ကြေးအာမခံတွင် စာရင်းမသွင်းထားသော လုပ်ငန်းခွင်တစ်ခုတွင် မတော်တဆမှုဖြစ်ပွားခဲ့လျှင်ပင် အလုပ်သမားသည် လျော်ကြေးရရှိနိုင်သေးသည် (အလုပ်ရှင်သည် နောက်ပိုင်းတွင် နိုင်ငံတော်သို့ ပြန်လည်ပေးဆပ်ရမည်)။",
                mn: "Ажлын ослын нөхөн олговрын даатгалд бүртгүүлээгүй ажлын байранд осол гарсан ч ажилчин нөхөн олговор авч болно (ажил олгогч дараа нь улсад буцаан төлөх ёстой).",
                lo: "ເຖິງແມ່ນວ່າຈະເກີດອຸບັດຕິເຫດຢູ່ບ່ອນເຮັດວຽກທີ່ບໍ່ໄດ້ລົງທະບຽນປະກັນໄພຄ່າຊົດເຊີຍອຸບັດຕິເຫດໃນການເຮັດວຽກ, ແຮງງານກໍຍັງສາມາດໄດ້ຮັບຄ່າຊົດເຊີຍ (ນາຍຈ້າງຕ້ອງຈ່າຍຄືນໃຫ້ລັດຖະບານພາຍຫຼັງ).",
                tet:
                    "Maski akontese asidente iha fatin servisu ida ne'ebé la rejista iha seguru kompensasaun asidente servisu, traballadór bele simu nafatin kompensasaun (empregadór tenke selu fali ba estadu depois).",
                ne: "औद्योगिक दुर्घटना क्षतिपूर्ति बीमामा दर्ता नभएको कार्यस्थलमा दुर्घटना भए पनि, कामदारले अझै क्षतिपूर्ति पाउन सक्छ (रोजगारदाताले पछि राज्यलाई फिर्ता गर्नुपर्छ)।",
                zh: '即使工伤保险未参保的单位发生事故，劳动者仍可获得工伤赔偿（用人单位事后需向国家偿还相关费用）。',
                vi: 'Ngay cả khi xảy ra tai nạn tại nơi làm việc chưa tham gia bảo hiểm tai nạn lao động, người lao động vẫn có thể nhận được bồi thường tai nạn lao động (chủ sử dụng lao động sau đó phải hoàn trả chi phí cho nhà nước).',
                uz: "Ishlab chiqarishdagi baxtsiz hodisalarni qoplash sugʻurtasida roʻyxatdan oʻtmagan ish joyida baxtsiz hodisa yuz bersa ham, ishchi kompensatsiya olishi mumkin (ish beruvchi keyinchalik davlatga toʻlashi kerak).",
              ),
              L10nText(
                ko: '건강보험 미가입 상태로 진료받으면 진료비 전액을 본인이 부담하게 됩니다.',
                en: 'If you receive treatment without health insurance, you must bear the full cost of treatment yourself.',
                tr: "Sağlık sigortanız olmadan tedavi görürseniz, tedavi masraflarının tamamını kendiniz karşılamanız gerekir.",
                tg: "Агар шумо бе суғуртаи тандурустӣ табобат гиред, шумо бояд тамоми хароҷоти табобатро худатон пӯшонед.",
                fil:
                    "Kung magpapagamot ka nang walang health insurance, kailangan mong sagutin ang buong halaga ng paggamot.",
                ur: "اگر آپ ہیلتھ انشورنس کے بغیر علاج کرواتے ہیں، تو آپ کو علاج کے تمام اخراجات خود برداشت کرنے ہوں گے۔",
                th: "หากคุณเข้ารับการรักษาโดยไม่มีประกันสุขภาพ คุณจะต้องรับผิดชอบค่ารักษาพยาบาลทั้งหมดด้วยตนเอง",
                ky: "Эгерде сиз саламаттык сактоо камсыздандыруусуз дарылансаңыз, дарылоо чыгымдарынын баарын өзүңүз төлөшүңүз керек.",
                km: "ប្រសិនបើអ្នកទទួលការព្យាបាលដោយគ្មានការធានារ៉ាប់រងសុខភាព អ្នកត្រូវបង់ថ្លៃព្យាបាលទាំងស្រុងដោយខ្លួនឯង។",
                id: "Jika Anda menerima perawatan tanpa asuransi kesehatan, Anda harus menanggung seluruh biaya perawatan sendiri.",
                si: "ඔබ සෞඛ්‍ය රක්ෂණයකින් තොරව ප්‍රතිකාර ලබා ගන්නේ නම්, ප්‍රතිකාර සඳහා වන සම්පූර්ණ පිරිවැය ඔබ විසින්ම දැරිය යුතුය.",
                bn: "আপনার স্বাস্থ্য বীমা ছাড়া চিকিৎসা করালে, আপনাকে চিকিৎসার সম্পূর্ণ খরচ নিজেকে বহন করতে হবে।",
                my: "ကျန်းမာရေးအာမခံမရှိဘဲ ကုသမှုခံယူပါက ကုသမှုစရိတ်အားလုံးကို သင်ကိုယ်တိုင် ကျခံရမည်ဖြစ်သည်။",
                mn: "Хэрэв та эрүүл мэндийн даатгалгүйгээр эмчилгээ хийлгэвэл, эмчилгээний бүх зардлыг өөрөө хариуцах ёстой.",
                lo: "ຖ້າທ່ານໄດ້ຮັບການປິ່ນປົວໂດຍບໍ່ມີປະກັນສຸຂະພາບ, ທ່ານຈະຕ້ອງຮັບຜິດຊອບຄ່າປິ່ນປົວທັງໝົດດ້ວຍຕົນເອງ.",
                tet:
                    "Se Ita simu tratamentu médiku la ho seguru saúde, Ita tenke selu rasik kustu tratamentu tomak.",
                ne: "यदि तपाईंले स्वास्थ्य बीमा बिना उपचार गराउनुभयो भने, उपचार खर्चको सम्पूर्ण रकम आफैंले बेहोर्नुपर्नेछ।",
                zh: '若在未参加健康保险的状态下就诊，需自行承担全部诊疗费用。',
                vi: 'Nếu khám chữa bệnh trong tình trạng chưa tham gia bảo hiểm y tế, bạn sẽ phải tự chi trả toàn bộ chi phí khám chữa bệnh.',
                uz: "Agar siz tibbiy sugʻurtasiz davolansangiz, davolanishning toʻliq xarajatini oʻzingiz qoplashingiz shart.",
              ),
            ],
          ),
          ContentBlock(
            title: L10nText(
              ko: '가입 여부 확인 방법',
              en: 'How to Check Your Enrollment Status',
              tr: "Kayıt Durumunuzu Nasıl Kontrol Edebilirsiniz?",
              tg: "Чӣ тавр ҳолати бақайдгирии худро тафтиш кардан мумкин аст?",
              fil: "Paano Suriin ang Iyong Katayuan sa Pagpaparehistro?",
              ur: "آپ اپنے اندراج کی حیثیت کیسے چیک کر سکتے ہیں؟",
              th: "จะตรวจสอบสถานะการลงทะเบียนของคุณได้อย่างไร?",
              ky: "Каттоо статусуңузду кантип текшерсе болот?",
              km: "តើធ្វើដូចម្តេចដើម្បីពិនិត្យមើលស្ថានភាពចុះឈ្មោះរបស់អ្នក?",
              id: "Bagaimana Cara Memeriksa Status Pendaftaran Anda?",
              si: "ඔබේ ලියාපදිංචි තත්ත්වය පරීක්ෂා කරන්නේ කෙසේද?",
              bn: "আপনার নিবন্ধনের অবস্থা কিভাবে পরীক্ষা করবেন?",
              my: "သင်၏စာရင်းသွင်းမှုအခြေအနေကို မည်သို့စစ်ဆေးမည်နည်း။",
              mn: "Бүртгэлийн статусаа хэрхэн шалгах вэ?",
              lo: "ທ່ານສາມາດກວດສອບສະຖານະການລົງທະບຽນຂອງທ່ານໄດ້ແນວໃດ?",
              tet: "Oinsá atu Kontrola Ita-nia Estatutu Rejistu?",
              ne: "तपाईंको दर्ता स्थिति कसरी जाँच गर्न सक्नुहुन्छ?",
              zh: '参保情况确认方法',
              vi: 'Cách kiểm tra tình trạng tham gia bảo hiểm',
              uz: "Roʻyxatdan oʻtish holatini qanday tekshirish mumkin",
            ),
            bullets: [
              L10nText(
                ko: '국민건강보험공단(1577-1000), 국민연금공단(1355)에서 본인 가입 상태를 확인할 수 있습니다.',
                en: 'You can check your enrollment status by contacting the National Health Insurance Service (1577-1000) or the National Pension Service (1355).',
                tr: "Kayıt durumunuzu Ulusal Sağlık Sigortası Kurumu (1577-1000) veya Ulusal Emeklilik Kurumu (1355) ile iletişime geçerek kontrol edebilirsiniz.",
                tg: "Шумо метавонед ҳолати бақайдгирии худро тавассути тамос бо Корпоратсияи миллии суғуртаи тандурустӣ (1577-1000) ё Хадамоти миллии нафақа (1355) тафтиш кунед.",
                fil:
                    "Maaari mong suriin ang iyong katayuan sa pagpaparehistro sa pamamagitan ng pakikipag-ugnayan sa National Health Insurance Service (1577-1000) o sa National Pension Service (1355).",
                ur: "آپ نیشنل ہیلتھ انشورنس کارپوریشن (1577-1000) یا نیشنل پنشن سروس (1355) سے رابطہ کر کے اپنے اندراج کی حیثیت چیک کر سکتے ہیں۔",
                th: "คุณสามารถตรวจสอบสถานะการลงทะเบียนของคุณได้โดยติดต่อสำนักงานหลักประกันสุขภาพแห่งชาติ (1577-1000) หรือสำนักงานบำนาญแห่งชาติ (1355)",
                ky: "Каттоо статусуңузду Улуттук саламаттык сактоо камсыздандыруу мекемеси (1577-1000) же Улуттук пенсия мекемеси (1355) менен байланышып текшерсеңиз болот.",
                km: "អ្នកអាចពិនិត្យមើលស្ថានភាពចុះឈ្មោះរបស់អ្នកដោយទាក់ទងសាជីវកម្មធានារ៉ាប់រងសុខភាពជាតិ (1577-1000) ឬសាជីវកម្មប្រាក់សោធនជាតិ (1355)។",
                id: "Anda dapat memeriksa status pendaftaran Anda dengan menghubungi National Health Insurance Service (1577-1000) atau National Pension Service (1355).",
                si: "ඔබේ ලියාපදිංචි තත්ත්වය ජාතික සෞඛ්‍ය රක්ෂණ සේවය (1577-1000) හෝ ජාතික විශ්‍රාම වැටුප් සේවය (1355) අමතා පරීක්ෂා කළ හැකිය.",
                bn: "আপনি জাতীয় স্বাস্থ্য বীমা পরিষেবা (1577-1000) বা জাতীয় পেনশন পরিষেবা (1355) এর সাথে যোগাযোগ করে আপনার নিবন্ধনের অবস্থা পরীক্ষা করতে পারেন।",
                my: "သင်၏စာရင်းသွင်းမှုအခြေအနေကို အမျိုးသားကျန်းမာရေးအာမခံကော်ပိုရေးရှင်း (1577-1000) သို့မဟုတ် အမျိုးသားပင်စင်ဝန်ဆောင်မှု (1355) သို့ ဆက်သွယ်၍ စစ်ဆေးနိုင်ပါသည်။",
                mn: "Та бүртгэлийн статусаа Үндэсний Эрүүл мэндийн даатгалын корпораци (1577-1000) эсвэл Үндэсний тэтгэврийн корпораци (1355) -тай холбогдож шалгаж болно.",
                lo: "ທ່ານສາມາດກວດສອບສະຖານະການລົງທະບຽນຂອງທ່ານໄດ້ໂດຍການຕິດຕໍ່ ອົງການປະກັນສຸຂະພາບແຫ່ງຊາດ (1577-1000) ຫຼື ອົງການບໍານານແຫ່ງຊາດ (1355).",
                tet:
                    "Ita bele kontrola ita-nia estatutu rejistu hodi kontaktu Korporasaun Seguru Saúde Nasionál (1577-1000) ka Servisu Pensaun Nasionál (1355).",
                ne: "तपाईं आफ्नो दर्ता स्थिति राष्ट्रिय स्वास्थ्य बीमा निगम (1577-1000) वा राष्ट्रिय पेन्सन सेवा (1355) मा सम्पर्क गरेर जाँच गर्न सक्नुहुन्छ।",
                zh: '可致电国民健康保险公团(1577-1000)或国民年金公团(1355)确认本人的参保状态。',
                vi: 'Bạn có thể kiểm tra tình trạng tham gia bảo hiểm của bản thân tại Cơ quan Bảo hiểm Y tế Quốc dân (1577-1000) hoặc Công đoàn Quỹ hưu trí quốc dân (1355).',
                uz: "Siz roʻyxatdan oʻtish holatingizni Milliy sogʻliqni saqlash sugʻurtasi xizmati (1577-1000) yoki Milliy pensiya xizmati (1355) bilan bogʻlanish orqali tekshirishingiz mumkin.",
              ),
            ],
          ),
