      BookPage(
        title: L10nText(
          ko: '산재보험과 국민연금',
          en: 'Industrial Accident Insurance and the National Pension',
          tr: "İş Kazası Sigortası ve Ulusal Emeklilik",
          tg: "Суғуртаи садамаи меҳнатӣ ва нафақаи миллӣ",
          fil: "Seguro sa Aksidente sa Trabaho at National Pension",
