          km: "ការធានារ៉ាប់រងគ្រោះថ្នាក់ការងារ និងប្រាក់សោធនជាតិ",
          id: "Asuransi Kecelakaan Kerja dan Pensiun Nasional",
          si: "කාර්මික අනතුරු රක්ෂණය සහ ජාතික විශ්‍රාම වැටුප",
