        ),
        summary: L10nText(
          ko: '산재보험은 체류자격과 관계없이 모든 근로자에게 적용되지만, 국민연금은 본국과의 상호주의 여부에 따라 가입 대상에서 제외될 수 있습니다.',
          en: 'Industrial accident insurance applies to all workers regardless of their visa status, but the National Pension may exclude certain nationals depending on whether reciprocity exists with their home country.',
          tr: "İş kazası sigortası, vize durumlarına bakılmaksızın tüm işçiler için geçerlidir, ancak Ulusal Emeklilik, kendi ülkeleriyle mütekabiliyet olup olmadığına bağlı olarak belirli ülke vatandaşlarını hariç tutabilir.",
          tg: "Суғуртаи садамаи меҳнатӣ ба ҳамаи коргарон, новобаста аз ҳолати раводиди онҳо, дахл дорад, аммо Нафақаи миллӣ метавонад шаҳрвандони кишварҳои муайянро вобаста ба мавҷудияти мутақобила бо кишвари онҳо истисно кунад.",
          fil:
              "Ang seguro sa aksidente sa trabaho ay nalalapat sa lahat ng manggagawa anuman ang kanilang katayuan sa visa, ngunit ang National Pension ay maaaring magbukod ng mga mamamayan ng ilang bansa depende kung may resiprosidad sa kanilang sariling bansa.",
          ur: "کام پر حادثے کی انشورنس ویزا کی حیثیت سے قطع نظر تمام کارکنوں پر لاگو ہوتی ہے، لیکن نیشنل پنشن بعض ممالک کے شہریوں کو خارج کر سکتی ہے، اس بات پر منحصر ہے کہ آیا ان کے اپنے ملک کے ساتھ باہمی معاہدہ موجود ہے۔",
          th: "ประกันการบาดเจ็บจากการทำงานครอบคลุมแรงงานทุกคนโดยไม่คำนึงถึงสถานะวีซ่า แต่บำนาญแห่งชาติอาจยกเว้นพลเมืองของบางประเทศ ขึ้นอยู่กับว่ามีหลักการต่างตอบแทนกับประเทศของตนหรือไม่",
          ky: "Өндүрүштүк кырсыктан камсыздандыруу виза статусуна карабастан бардык жумушчуларга тиешелүү, бирок Улуттук пенсия өз өлкөлөрү менен өз ара макулдашуу бар же жок экенине жараша айрым өлкөлөрдүн жарандарын камтыбай калышы мүмкүн.",
          km: "ការធានារ៉ាប់រងគ្រោះថ្នាក់ការងារអនុវត្តចំពោះកម្មករនិយោជិតទាំងអស់ដោយមិនគិតពីស្ថានភាពទិដ្ឋាការរបស់ពួកគេ ប៉ុន្តែប្រាក់សោធនជាតិអាចលើកលែងពលរដ្ឋនៃប្រទេសមួយចំនួន អាស្រ័យលើថាតើមានគោលការណ៍ទៅវិញទៅមកជាមួយប្រទេសកំណើតរបស់ពួកគេដែរឬទេ។",
          id: "Asuransi kecelakaan kerja berlaku untuk semua pekerja tanpa memandang status visa, tetapi Pensiun Nasional dapat mengecualikan warga negara tertentu tergantung pada apakah ada timbal balik dengan negara asal mereka.",
          si: "කාර්මික අනතුරු රක්ෂණය වීසා තත්ත්වය නොසලකා සියලුම සේවකයින්ට අදාළ වේ, නමුත් ජාතික විශ්‍රාම වැටුප ඔවුන්ගේ මව් රට සමඟ අන්‍යෝන්‍ය භාවයක් තිබේද යන්න මත පදනම්ව ඇතැම් රටවල පුරවැසියන් බැහැර කළ හැකිය.",
          bn: "শিল্প দুর্ঘটনা বীমা ভিসার অবস্থা নির্বিশেষে সকল কর্মীদের জন্য প্রযোজ্য, তবে জাতীয় পেনশন তাদের নিজ দেশের সাথে পারস্পরিকতা আছে কিনা তার উপর নির্ভর করে নির্দিষ্ট দেশের নাগরিকদের বাদ দিতে পারে।",
          my: "လုပ်ငန်းခွင်ထိခိုက်မှုအာမခံသည် ဗီဇာအခြေအနေမခွဲခြားဘဲ အလုပ်သမားအားလုံးအတွက် အကျုံးဝင်သော်လည်း အမျိုးသားပင်စင်သည် ၎င်းတို့၏ဇာတိနိုင်ငံနှင့် အပြန်အလှန်သဘောတူညီချက်ရှိမရှိအပေါ် မူတည်၍ သီးခြားနိုင်ငံသားများကို ချန်လှပ်ထားနိုင်သည်။",
          mn: "Ажлын ослын даатгал нь визийн статусаас үл хамааран бүх ажилчдад хамаарна, харин Үндэсний тэтгэвэр нь өөрийн улстайгаа харилцан адилгүй байх зарчимтай эсэхээс хамаарч тодорхой улсын иргэдийг хасч болно.",
          lo: "ປະກັນໄພອຸບັດຕິເຫດໃນການເຮັດວຽກແມ່ນໃຊ້ໄດ້ກັບແຮງງານທຸກຄົນ ໂດຍບໍ່ຄໍານຶງເຖິງສະຖານະວີຊາ, ແຕ່ເງິນບໍານານແຫ່ງຊາດອາດຈະຍົກເວັ້ນພົນລະເມືອງຂອງບາງປະເທດ ໂດຍອີງໃສ່ຫຼັກການຕ່າງຕອບແທນກັບປະເທດຂອງເຂົາເຈົ້າ.",
          tet:
              "Seguru asidente servisu aplika ba traballadór hotu-hotu, la haree ba sira-nia estatutu viza, maibé Pensaun Nasionál bele esklui sidadaun husi nasaun balu, depende ba se iha reziprosidade ho sira-nia nasaun rasik.",
          ne: "औद्योगिक दुर्घटना बीमा भिसाको स्थिति जस्तोसुकै भए पनि सबै कामदारहरूका लागि लागू हुन्छ, तर राष्ट्रिय पेन्सनले उनीहरूको देशसँग पारस्परिकता छ वा छैन भन्ने आधारमा निश्चित देशका नागरिकहरूलाई बहिष्कार गर्न सक्छ।",
          zh: '工伤保险适用于所有劳动者，与居留资格无关；但国民年金是否适用则取决于与本国之间是否存在对等原则，可能会被排除在参保对象之外。',
          vi: 'Bảo hiểm tai nạn lao động áp dụng cho mọi người lao động bất kể tư cách lưu trú, nhưng Quỹ hưu trí quốc dân có thể loại trừ một số quốc tịch khỏi đối tượng tham gia tùy theo việc có áp dụng nguyên tắc có đi có lại với nước sở tại hay không.',
          uz: "Ishdagi baxtsiz hodisalardan sugʻurta barcha ishchilarga viza maqomidan qatʼi nazar qoʻllaniladi, ammo Milliy pensiya ayrim fuqarolarga, ularning vatanlari bilan oʻzaro kelishuv mavjudligiga qarab, qoʻllanilmasligi mumkin.",
        ),
