              L10nText(
                ko: '본국 법이 한국 국민에게 국민연금에 상응하는 연금을 적용하지 않는 국가 출신은 가입 대상에서 제외(상호주의)',
                en: 'Nationals of countries whose laws do not provide Korean citizens with a pension equivalent to the National Pension are excluded from enrollment (reciprocity principle)',
                tr: "Yasaları Kore vatandaşlarına Ulusal Emekliliğe eşdeğer bir emeklilik sağlamayan ülkelerin vatandaşları kayıttan muaftır (mütekabiliyet ilkesi).",
                tg: "Шаҳрвандони кишварҳое, ки қонунҳои онҳо ба шаҳрвандони Корея нафақаи ба Нафақаи миллӣ баробарро таъмин намекунанд, аз бақайдгирӣ озоданд (принсипи мутақобила).",
                fil:
                    "Ang mga mamamayan ng mga bansa na ang mga batas ay hindi nagbibigay ng pensyon na katumbas ng National Pension sa mga mamamayan ng Korea ay exempted sa pagpaparehistro (prinsipyo ng resiprosidad).",
                ur: "جن ممالک کے قوانین کوریائی شہریوں کو نیشنل پنشن کے مساوی پنشن فراہم نہیں کرتے، ان کے شہری اندراج سے مستثنیٰ ہیں (باہمی معاہدے کا اصول)۔",
                th: "พลเมืองของประเทศที่กฎหมายไม่ได้ให้บำนาญเทียบเท่ากับบำนาญแห่งชาติแก่พลเมืองเกาหลีจะได้รับการยกเว้นจากการลงทะเบียน (หลักการต่างตอบแทน)",
                ky: "Мыйзамдары Корея жарандарына Улуттук пенсияга барабар пенсияны камсыз кылбаган өлкөлөрдүн жарандары каттоодон бошотулат (өз ара принцип).",
                km: "ពលរដ្ឋនៃប្រទេសដែលច្បាប់របស់ពួកគេមិនផ្តល់ប្រាក់សោធនសមមូលនឹងប្រាក់សោធនជាតិដល់ពលរដ្ឋកូរ៉េ ត្រូវបានលើកលែងពីការចុះឈ្មោះ (គោលការណ៍ទៅវិញទៅមក)។",
