                bn: "যেসব দেশের আইন কোরিয়ান নাগরিকদের জাতীয় পেনশনের সমতুল্য পেনশন প্রদান করে না, সেসব দেশের নাগরিকরা নিবন্ধন থেকে অব্যাহতিপ্রাপ্ত (পারস্পরিকতার নীতি)।",
                my: "ကိုရီးယားနိုင်ငံသားများအား အမျိုးသားပင်စင်နှင့်ညီမျှသော ပင်စင်ကို မပေးသောနိုင်ငံများမှ နိုင်ငံသားများသည် စာရင်းသွင်းခြင်းမှ ကင်းလွတ်ခွင့်ရှိသည် (အပြန်အလှန်သဘောတူညီချက်နိယာမ)။",
                mn: "Солонгос иргэдэд Үндэсний тэтгэвэртэй тэнцэхүйц тэтгэвэр олгодоггүй улсуудын иргэд бүртгэлээс чөлөөлөгдөнө (харилцан адилгүй байх зарчим).",
                lo: "ພົນລະເມືອງຂອງປະເທດທີ່ກົດໝາຍບໍ່ໄດ້ໃຫ້ເງິນບໍານານທີ່ທຽບເທົ່າກັບເງິນບໍານານແຫ່ງຊາດແກ່ພົນລະເມືອງເກົາຫຼີ ແມ່ນໄດ້ຮັບການຍົກເວັ້ນຈາກການລົງທະບຽນ (ຫຼັກການຕ່າງຕອບແທນ).",
                tet:
                    "Sidadaun husi nasaun sira ne'ebé sira-nia lei la fó pensaun ida ne'ebé hanesan ho Pensaun Nasionál ba sidadaun Koreia sira, hetan esensaun husi rejistu (prinsípiu reziprosidade).",
                ne: "जसको कानूनले कोरियाली नागरिकहरूलाई राष्ट्रिय पेन्सन बराबरको पेन्सन प्रदान गर्दैन, ती देशका नागरिकहरू दर्ताबाट छुट छन् (पारस्परिकताको सिद्धान्त)।",
                zh: '若本国法律未对韩国国民适用相当于国民年金的养老金制度，则该国国民不属于参保对象（对等原则）',
                vi: 'Công dân của quốc gia mà pháp luật nước đó không áp dụng chế độ hưu trí tương đương cho công dân Hàn Quốc sẽ bị loại khỏi đối tượng tham gia (nguyên tắc có đi có lại)',
                uz: "Qonunlari Koreya fuqarolariga Milliy pensiyaga teng pensiya bermaydigan mamlakatlar fuqarolari roʻyxatdan oʻtishdan chiqariladi (oʻzaro kelishuv prinsipi)",
              ),
