            bullets: [
              L10nText(
                ko: '상호주의로 가입 대상이었거나 가입 후 출국하는 경우, 요건을 충족하면 반환일시금을 청구할 수 있습니다.',
                en: 'If you were enrolled under the reciprocity principle or are leaving Korea after enrollment, you can claim a lump-sum refund if you meet the requirements.',
                tr: "Mütekabiliyet ilkesi kapsamında kayıtlıysanız veya kayıt olduktan sonra Kore'den ayrılıyorsanız, şartları karşılamanız halinde toplu geri ödeme talep edebilirsiniz.",
                tg: "Агар шумо дар доираи принсипи мутақобила ба қайд гирифта шуда бошед ё пас аз бақайдгирӣ Кореяро тарк кунед, шумо метавонед дар сурати мувофиқат ба шартҳо, пардохти яквақтаро талаб кунед.",
                fil:
                    "Kung ikaw ay nakarehistro sa ilalim ng prinsipyo ng resiprosidad o umalis sa Korea pagkatapos magparehistro, maaari kang mag-claim ng lump-sum refund kung matugunan mo ang mga kondisyon.",
                ur: "اگر آپ باہمی معاہدے کے اصول کے تحت اندراج شدہ ہیں یا اندراج کے بعد کوریا چھوڑ رہے ہیں، تو شرائط پوری ہونے پر آپ یکمشت واپسی کا دعویٰ کر سکتے ہیں۔",
                th: "หากคุณลงทะเบียนภายใต้หลักการต่างตอบแทน หรือหากคุณเดินทางออกจากเกาหลีหลังจากลงทะเบียน คุณสามารถขอรับเงินคืนแบบเหมาจ่ายได้หากคุณมีคุณสมบัติตรงตามเงื่อนไข",
                ky: "Эгерде сиз өз ара принциптин негизинде катталган болсоңуз же катталгандан кийин Кореядан кетип жатсаңыз, шарттарды аткарган учурда жапырт кайтарымды талап кыла аласыз.",
                km: "ប្រសិនបើអ្នកបានចុះឈ្មោះក្រោមគោលការណ៍ទៅវិញទៅមក ឬកំពុងចាកចេញពីប្រទេសកូរ៉េបន្ទាប់ពីចុះឈ្មោះ អ្នកអាចទាមទារការសងប្រាក់វិញជាដុំ ប្រសិនបើអ្នកបំពេញលក្ខខណ្ឌ។",
                id: "Jika Anda terdaftar berdasarkan prinsip timbal balik atau meninggalkan Korea setelah mendaftar, Anda dapat mengajukan pengembalian dana sekaligus jika Anda memenuhi syarat.",
                si: "ඔබ අන්‍යෝන්‍යත්ව මූලධර්මය යටතේ ලියාපදිංචි වී ඇත්නම් හෝ ලියාපදිංචි වීමෙන් පසු කොරියාවෙන් පිටව යන්නේ නම්, ඔබ කොන්දේසි සපුරාලන්නේ නම් ඔබට සමුච්චිත ආපසු ගෙවීමක් ඉල්ලා සිටිය හැකිය.",
                bn: "যদি আপনি পারস্পরিকতার নীতির অধীনে নিবন্ধিত হন বা নিবন্ধনের পরে কোরিয়া ত্যাগ করেন, তাহলে আপনি শর্ত পূরণ করলে এককালীন পরিশোধের দাবি করতে পারেন।",
                my: "အပြန်အလှန်သဘောတူညီချက်နိယာမအောက်တွင် စာရင်းသွင်းထားပါက သို့မဟုတ် စာရင်းသွင်းပြီးနောက် ကိုရီးယားမှ ထွက်ခွာပါက သင်သည် သတ်မှတ်ချက်များနှင့် ကိုက်ညီပါက တစ်လုံးတစ်ခဲတည်း ပြန်အမ်းငွေကို တောင်းဆိုနိုင်ပါသည်။",
                mn: "Хэрэв та харилцан адилгүй байх зарчмын дагуу бүртгүүлсэн эсвэл бүртгүүлсний дараа Солонгосоос гарч байгаа бол, шаардлагыг хангасан тохиолдолд нэгдсэн буцаан олголт нэхэмжилж болно.",
                lo: "ຖ້າທ່ານໄດ້ລົງທະບຽນພາຍໃຕ້ຫຼັກການຕ່າງຕອບແທນ ຫຼື ຖ້າທ່ານອອກຈາກເກົາຫຼີຫຼັງຈາກລົງທະບຽນແລ້ວ, ທ່ານສາມາດຮ້ອງຂໍການຈ່າຍຄືນແບບລວມໄດ້ ຖ້າທ່ານປະຕິບັດຕາມເງື່ອນໄຂ.",
                tet:
                    "Se Ita rejista ona tuir prinsípiu reziprosidade ka se Ita sai husi Koreia depois de rejistu, Ita bele husu selu fali hamutuk se Ita kumpre kritériu sira.",
                ne: "यदि तपाईं पारस्परिकताको सिद्धान्त अन्तर्गत दर्ता हुनुहुन्छ वा दर्ता गरेपछि कोरिया छोड्दै हुनुहुन्छ भने, सर्तहरू पूरा गरेमा एकमुष्ट फिर्ताको लागि दाबी गर्न सक्नुहुन्छ।",
                zh: '若因对等原则曾参保，或参保后出国，只要符合条件即可申请退还一次性给付金。',
                vi: 'Nếu đã tham gia theo nguyên tắc có đi có lại hoặc xuất cảnh sau khi tham gia, bạn có thể yêu cầu khoản hoàn trả một lần nếu đáp ứng đủ điều kiện.',
                uz: "Agar siz oʻzaro kelishuv prinsipi boʻyicha roʻyxatdan oʻtgan boʻlsangiz yoki roʻyxatdan oʻtgandan keyin Koreyani tark etayotgan boʻlsangiz, talablarga javob bersangiz, bir martalik qaytarishni talab qilishingiz mumkin.",
              ),
              L10nText(
                ko: '청구 방법은 출국 전후 국민연금공단에서 안내받을 수 있습니다.',
                en: 'You can get guidance on how to claim it from the National Pension Service before or after departure.',
                tr: "Ayrılmadan önce veya sonra Ulusal Emeklilik Kurumu'ndan nasıl talep edeceğinize dair rehberlik alabilirsiniz.",
                tg: "Шумо метавонед пеш аз рафтан ё баъд аз он аз Хадамоти миллии нафақа дастур оид ба чӣ гуна талаб кардан гиред.",
                fil:
                    "Maaari kang makakuha ng gabay kung paano mag-claim mula sa National Pension Service bago o pagkatapos ng iyong pag-alis.",
                ur: "آپ نیشنل پنشن سروس سے روانگی سے پہلے یا بعد میں دعویٰ کرنے کے بارے میں رہنمائی حاصل کر سکتے ہیں۔",
                th: "คุณสามารถขอคำแนะนำเกี่ยวกับวิธีการขอรับเงินคืนจากสำนักงานบำนาญแห่งชาติได้ก่อนหรือหลังการเดินทางออก",
                ky: "Кетээрден мурун же кийин Улуттук пенсия мекемесинен кантип талап кылуу керектиги боюнча көрсөтмө ала аласыз.",
                km: "អ្នកអាចទទួលបានការណែនាំអំពីរបៀបទាមទារពីសាជីវកម្មប្រាក់សោធនជាតិ មុនពេល ឬបន្ទាប់ពីការចាកចេញ។",
                id: "Anda dapat menerima panduan tentang cara mengajukan klaim dari National Pension Service sebelum atau setelah keberangkatan Anda.",
                si: "පිටත්ව යාමට පෙර හෝ පසුව ජාතික විශ්‍රාම වැටුප් සේවයෙන් ඉල්ලීමක් කරන්නේ කෙසේද යන්න පිළිබඳ මග පෙන්වීම් ලබා ගත හැකිය.",
                bn: "দেশত্যাগের আগে বা পরে জাতীয় পেনশন পরিষেবা থেকে কিভাবে দাবি করবেন সে সম্পর্কে নির্দেশনা পেতে পারেন।",
                my: "ထွက်ခွာခြင်းမပြုမီ သို့မဟုတ် ထွက်ခွာပြီးနောက် အမျိုးသားပင်စင်ဝန်ဆောင်မှုမှ မည်သို့တောင်းဆိုရမည်ကို လမ်းညွှန်မှုရယူနိုင်ပါသည်။",
                mn: "Та явахаасаа өмнө эсвэл дараа Үндэсний тэтгэврийн корпораци -аас хэрхэн нэхэмжлэх талаар заавар авч болно.",
                lo: "ທ່ານສາມາດຂໍຄໍາແນະນໍາຈາກອົງການບໍານານແຫ່ງຊາດ ກ່ຽວກັບວິທີການຮ້ອງຂໍ ກ່ອນ ຫຼື ຫຼັງຈາກອອກຈາກປະເທດ.",
                tet:
                    "Ita bele hetan orientasaun husi Servisu Pensaun Nasionál kona-ba oinsá atu halo pedidu antes ka depois de Ita sai.",
                ne: "छोड्नु अघि वा पछि राष्ट्रिय पेन्सन सेवाबाट कसरी दाबी गर्ने भन्ने बारे मार्गदर्शन प्राप्त गर्न सक्नुहुन्छ।",
                zh: '出国前后均可向国民年金公团咨询申请方法。',
                vi: 'Bạn có thể được hướng dẫn về cách yêu cầu tại Công đoàn Quỹ hưu trí quốc dân trước hoặc sau khi xuất cảnh.',
                uz: "Ketishdan oldin yoki keyin Milliy pensiya xizmatidan uni qanday talab qilish boʻyicha yoʻl-yoʻriq olishingiz mumkin.",
              ),
            ],
          ),
