          km: "ការធានារ៉ាប់រងសុខភាព និងការធានារ៉ាប់រងការងារ",
          id: "Asuransi Kesehatan dan Asuransi Ketenagakerjaan",
          si: "සෞඛ්‍ය රක්ෂණය සහ රැකියා රක්ෂණය",
