        summary: L10nText(
          ko: '건강보험은 의무가입이지만, 고용보험은 체류자격에 따라 의무와 임의가입으로 나뉩니다.',
          en: 'Health insurance is mandatory, but employment insurance is either mandatory or optional depending on your visa status.',
          tr: "Sağlık sigortası zorunludur, ancak istihdam sigortası vize durumunuza bağlı olarak zorunlu veya isteğe bağlıdır.",
          tg: "Суғуртаи тандурустӣ ҳатмӣ аст, аммо суғуртаи шуғл вобаста ба ҳолати раводиди шумо ҳатмӣ ё ихтиёрӣ аст.",
          fil:
              "Ang seguro sa kalusugan ay sapilitan, ngunit ang seguro sa trabaho ay sapilitan o opsyonal depende sa iyong katayuan sa visa.",
          ur: "ہیلتھ انشورنس لازمی ہے، لیکن ایمپلائمنٹ انشورنس آپ کی ویزا کی حیثیت کے لحاظ سے لازمی یا اختیاری ہے۔",
          th: "ประกันสุขภาพเป็นภาคบังคับ แต่ประกันการจ้างงานเป็นภาคบังคับหรือเป็นทางเลือกขึ้นอยู่กับสถานะวีซ่าของคุณ",
          ky: "Саламаттык сактоо камсыздандыруусу милдеттүү, бирок иш менен камсыз кылуу камсыздандыруусу виза статусуңузга жараша милдеттүү же ыктыярдуу.",
          km: "ការធានារ៉ាប់រងសុខភាពគឺជាកាតព្វកិច្ច ប៉ុន្តែការធានារ៉ាប់រងការងារគឺជាកាតព្វកិច្ច ឬជាជម្រើស អាស្រ័យលើស្ថានភាពទិដ្ឋាការរបស់អ្នក។",
          id: "Asuransi kesehatan wajib, tetapi asuransi ketenagakerjaan wajib atau opsional tergantung pada status visa Anda.",
          si: "සෞඛ්‍ය රක්ෂණය අනිවාර්ය වේ, නමුත් රැකියා රක්ෂණය ඔබේ වීසා තත්ත්වය අනුව අනිවාර්ය හෝ ස්වේච්ඡා වේ.",
          bn: "স্বাস্থ্য বীমা বাধ্যতামূলক, তবে কর্মসংস্থান বীমা আপনার ভিসার অবস্থার উপর নির্ভর করে বাধ্যতামূলক বা ঐচ্ছিক।",
          my: "ကျန်းမာရေးအာမခံသည် မဖြစ်မနေဖြစ်သော်လည်း အလုပ်အကိုင်အာမခံသည် သင်၏ဗီဇာအခြေအနေပေါ်မူတည်၍ မဖြစ်မနေ သို့မဟုတ် ရွေးချယ်နိုင်သည်။",
          mn: "Эрүүл мэндийн даатгал нь заавал байх ёстой, харин ажил эрхлэлтийн даатгал нь таны визийн статусаас хамаарч заавал эсвэл сайн дурынх байж болно.",
          lo: "ປະກັນສຸຂະພາບແມ່ນບັງຄັບ, ແຕ່ປະກັນການຈ້າງງານແມ່ນບັງຄັບ ຫຼື ເປັນທາງເລືອກ ຂຶ້ນຢູ່ກັບສະຖານະວີຊາຂອງທ່ານ.",
