                ko: '직장가입: 고용과 동시 가입, 보험료 근로자·사업주 절반씩 부담',
                en: 'Workplace-based enrollment: You are enrolled as soon as you are employed; the premium is split equally between worker and employer',
                tr: "İşyeri bazlı kayıt: İşe başlar başlamaz kaydınız yapılır; prim işçi ve işveren arasında eşit olarak bölünür",
                tg: "Бақайдгирии дар асоси ҷои кор: Шумо баробари оғози кор ба қайд гирифта мешавед; мукофотпулӣ байни коргар ва корфармо баробар тақсим карда мешавад",
                fil:
                    "Pagpaparehistro batay sa lugar ng trabaho: Ikaw ay nakarehistro sa sandaling magsimula ka sa trabaho; ang premium ay pantay na hinahati sa pagitan ng manggagawa at employer.",
                ur: "کام کی جگہ پر مبنی اندراج: جیسے ہی آپ کام شروع کرتے ہیں، آپ کا اندراج ہو جاتا ہے؛ پریمیم کارکن اور آجر کے درمیان برابر تقسیم ہوتا ہے۔",
                th: "การลงทะเบียนตามสถานที่ทำงาน: คุณจะได้รับการลงทะเบียนทันทีที่เริ่มทำงาน; เบี้ยประกันจะถูกแบ่งเท่า ๆ กันระหว่างลูกจ้างและนายจ้าง",
                ky: "Иш ордуна негизделген каттоо: Жумушка кирериңиз менен катталасыз; төгүм жумушчу менен иш берүүчүнүн ортосунда тең бөлүнөт",
                km: "ការចុះឈ្មោះផ្អែកលើកន្លែងធ្វើការ៖ អ្នកត្រូវបានចុះឈ្មោះភ្លាមៗនៅពេលអ្នកចាប់ផ្តើមធ្វើការ; បុព្វលាភត្រូវបានបែងចែកស្មើៗគ្នារវាងកម្មករនិយោជិត និងនិយោជក",
                id: "Pendaftaran berbasis tempat kerja: Anda terdaftar segera setelah Anda mulai bekerja; premi dibagi rata antara pekerja dan pemberi kerja",
                si: "සේවා ස්ථානය පදනම් කරගත් ලියාපදිංචිය: ඔබ රැකියාවක් ආරම්භ කළ වහාම ඔබ ලියාපදිංචි වේ; වාරිකය සේවකයා සහ සේවායෝජකයා අතර සමානව බෙදී යයි.",
                bn: "কর্মস্থল-ভিত্তিক নিবন্ধন: কর্মস্থলে যোগদানের সাথে সাথে আপনার নিবন্ধন করা হয়; প্রিমিয়াম কর্মী এবং নিয়োগকর্তার মধ্যে সমানভাবে ভাগ করা হয়।",
                my: "လုပ်ငန်းခွင်အခြေပြု စာရင်းသွင်းခြင်း- အလုပ်စတင်သည်နှင့်တစ်ပြိုင်နက် သင့်အား စာရင်းသွင်းပြီး ပရီမီယံကြေးကို အလုပ်သမားနှင့် အလုပ်ရှင်အကြား တူညီစွာ ခွဲဝေပေးသည်။",
                mn: "Ажлын байранд суурилсан бүртгэл: Та ажилд ормогц бүртгэгдэнэ; шимтгэлийг ажилчин болон ажил олгогч тэнцүү хувааж төлнө.",
                lo: "ການລົງທະບຽນຕາມສະຖານທີ່ເຮັດວຽກ: ທ່ານຈະຖືກລົງທະບຽນທັນທີທີ່ທ່ານເລີ່ມເຮັດວຽກ; ຄ່ານິຍົມຈະຖືກແບ່ງປັນເທົ່າທຽມກັນລະຫວ່າງແຮງງານ ແລະ ນາຍຈ້າງ.",
                tet:
                    "Rejistu bazeia ba fatin servisu: Ita-nia rejistu halo kedas bainhira Ita hahú servisu; prémiu fahe hanesan entre traballadór no empregadór.",
                ne: "कार्यस्थलमा आधारित दर्ता: काम सुरु गर्ने बित्तिकै तपाईंको दर्ता गरिन्छ; प्रिमियम कामदार र रोजगारदाता बीच समान रूपमा विभाजित हुन्छ",
                zh: '职场参保：受雇的同时即自动参保，保险费由劳动者和用人单位各承担一半',
                vi: 'Tham gia theo nơi làm việc: Được tham gia ngay khi được tuyển dụng, phí bảo hiểm do người lao động và chủ sử dụng lao động chia đều mỗi bên một nửa',
                uz: "Ish joyida roʻyxatdan oʻtish: Siz ishga qabul qilinishingiz bilanoq roʻyxatdan oʻtasiz; mukofot ishchi va ish beruvchi oʻrtasida teng taqsimlanadi",
              ),
              L10nText(
                ko: '지역가입: 체류 6개월 이상이면서 직장가입 대상이 아닌 경우, 보험료 전액 본인 부담',
                en: 'Regional enrollment: If you have stayed 6 months or more and are not eligible for workplace-based enrollment, you bear the entire premium yourself',
                tr: "Bölgesel kayıt: 6 ay veya daha uzun süre kaldıysanız ve işyeri bazlı kayda uygun değilseniz, primin tamamını kendiniz karşılarsınız",
                tg: "Бақайдгирии минтақавӣ: Агар шумо 6 моҳ ё бештар аз он монда бошед ва барои бақайдгирии дар асоси ҷои кор мувофиқ набошед, шумо тамоми мукофотпулиро худатон мепӯшонед",
                fil:
                    "Pagpaparehistro sa rehiyon: Kung nanatili ka nang 6 buwan o higit pa at hindi ka kwalipikado para sa pagpaparehistro batay sa lugar ng trabaho, ikaw mismo ang sasagot sa buong premium.",
                ur: "علاقائی اندراج: اگر آپ 6 ماہ یا اس سے زیادہ عرصے سے مقیم ہیں اور کام کی جگہ پر مبنی اندراج کے اہل نہیں ہیں، تو آپ پریمیم کی پوری رقم خود ادا کرتے ہیں۔",
                th: "การลงทะเบียนตามภูมิภาค: หากคุณพำนักอยู่เป็นเวลา 6 เดือนหรือนานกว่านั้น และไม่มีคุณสมบัติสำหรับการลงทะเบียนตามสถานที่ทำงาน คุณจะต้องรับผิดชอบค่าเบี้ยประกันทั้งหมดด้วยตนเอง",
                ky: "Аймактык каттоо: Эгерде сиз 6 ай же андан көп убакыт калган болсоңуз жана иш ордуна негизделген каттоо үчүн ылайыктуу болбосоңуз, төгүмдүн баарын өзүңүз төлөйсүз",
                km: "ការចុះឈ្មោះតាមតំបន់៖ ប្រសិនបើអ្នកស្នាក់នៅរយៈពេល 6 ខែ ឬយូរជាងនេះ ហើយមិនមានលក្ខណៈគ្រប់គ្រាន់សម្រាប់ការចុះឈ្មោះផ្អែកលើកន្លែងធ្វើការទេ អ្នកនឹងរ៉ាប់រងបុព្វលាភទាំងមូលដោយខ្លួនឯង",
                id: "Pendaftaran regional: Jika Anda telah tinggal selama 6 bulan atau lebih dan tidak memenuhi syarat untuk pendaftaran berbasis tempat kerja, Anda menanggung seluruh premi sendiri",
                si: "ප්‍රාදේශීය ලියාපදිංචිය: ඔබ මාස 6ක් හෝ ඊට වැඩි කාලයක් රැඳී සිටියේ නම් සහ සේවා ස්ථානය පදනම් කරගත් ලියාපදිංචියට සුදුසුකම් නොලබන්නේ නම්, ඔබ සම්පූර්ණ වාරිකය ඔබ විසින්ම දරයි.",
                bn: "আঞ্চলিক নিবন্ধন: যদি আপনি 6 মাস বা তার বেশি সময় ধরে থাকেন এবং কর্মস্থল-ভিত্তিক নিবন্ধনের জন্য যোগ্য না হন, তাহলে আপনি সম্পূর্ণ প্রিমিয়াম নিজেই বহন করবেন।",
                my: "ဒေသအခြေပြု စာရင်းသွင်းခြင်း- 6 လ သို့မဟုတ် ထို့ထက်ပို၍ နေထိုင်ပြီး လုပ်ငန်းခွင်အခြေပြု စာရင်းသွင်းခြင်းအတွက် အရည်အချင်းမပြည့်မီပါက ပရီမီယံကြေးအားလုံးကို သင်ကိုယ်တိုင် ကျခံရမည်ဖြစ်သည်။",
                mn: "Бүс нутгийн бүртгэл: Хэрэв та 6 сар ба түүнээс дээш хугацаагаар оршин суусан бөгөөд ажлын байранд суурилсан бүртгэлд хамрагдахгүй бол, шимтгэлийг бүхэлд нь өөрөө хариуцна.",
                lo: "ການລົງທະບຽນພາກພື້ນ: ຖ້າທ່ານໄດ້ພັກເຊົາເປັນເວລາ 6 ເດືອນ ຫຼື ດົນກວ່ານັ້ນ ແລະ ບໍ່ມີສິດລົງທະບຽນຕາມສະຖານທີ່ເຮັດວຽກ, ທ່ານຈະຕ້ອງຮັບຜິດຊອບຄ່ານິຍົມທັງໝົດດ້ວຍຕົນເອງ.",
                tet:
                    "Rejistu rejionál: Se Ita hela ona ba fulan 6 ka liu no la kualifika ba rejistu bazeia ba fatin servisu, Ita rasik mak selu prémiu tomak.",
                ne: "क्षेत्रीय दर्ता: यदि तपाईं 6 महिना वा सोभन्दा बढी समय बस्नुभएको छ र कार्यस्थलमा आधारित दर्ताका लागि योग्य हुनुहुन्न भने, सम्पूर्ण प्रिमियम आफैंले बेहोर्नुपर्छ",
                zh: '地区参保：居留满6个月以上且不属于职场参保对象时，保险费全额由本人承担',
                vi: 'Tham gia theo khu vực: Khi lưu trú từ 6 tháng trở lên và không thuộc đối tượng tham gia theo nơi làm việc, phí bảo hiểm do bản thân chi trả toàn bộ',
                uz: "Hududiy roʻyxatdan oʻtish: Agar siz 6 oy yoki undan koʻproq vaqt qolgan boʻlsangiz va ish joyida roʻyxatdan oʻtish huquqiga ega boʻlmasangiz, butun mukofotni oʻzingiz toʻlaysiz",
              ),
            ],
          ),
          ContentBlock(
            title: L10nText(
              ko: '고용보험',
              en: 'Employment Insurance',
              tr: "İşsizlik Sigortası",
