              km: "ការធានារ៉ាប់រងភាពអត់ការងារធ្វើ",
              id: "Asuransi Pengangguran",
              si: "රැකියා විරහිත රක්ෂණය",
              bn: "বেকারত্ব বীমা",
              my: "အလုပ်လက်မဲ့ အာမခံ",
              mn: "Ажилгүйдлийн даатгал",
              lo: "ປະກັນໄພການຫວ່າງງານ",
              tet: "Seguru Dezempregu",
              ne: "बेरोजगारी बीमा",
