            bullets: [
              L10nText(
                ko: 'E-9·H-2 체류자격: 고용보험 당연 피보험자이나, 실업급여·육아휴직급여는 별도 가입신청이 있어야 적용',
                en: 'E-9/H-2 visa holders: Automatically insured under employment insurance, but unemployment benefits and childcare leave benefits require a separate enrollment application',
                tr: "E-9/H-2 vizesi sahipleri: İstihdam sigortası kapsamında otomatik olarak sigortalıdır, ancak işsizlik ödeneği ve çocuk bakım izni ödeneği ayrı bir kayıt başvurusu gerektirir",
                tg: "Дорандагони раводиди E-9/H-2: Онҳо ба таври худкор таҳти суғуртаи шуғл қарор доранд, аммо кӯмакпулии бекорӣ ва кӯмакпулӣ барои рухсатии нигоҳубини кӯдак аризаи алоҳидаи бақайдгириро талаб мекунанд.",
                fil:
                    "Mga may hawak ng E-9/H-2 visa: Awtomatikong sakop ng seguro sa trabaho, ngunit ang benepisyo sa kawalan ng trabaho at benepisyo sa leave para sa pangangalaga ng bata ay nangangailangan ng hiwalay na aplikasyon para sa pagpaparehistro.",
                ur: "E-9/H-2 ویزا رکھنے والے: ملازمت کے بیمہ کے تحت خود بخود بیمہ شدہ ہوتے ہیں، لیکن بے روزگاری الاؤنس اور بچوں کی دیکھ بھال کی چھٹی کے الاؤنس کے لیے علیحدہ رجسٹریشن درخواست کی ضرورت ہوتی ہے۔",
                th: "ผู้ถือวีซ่า E-9/H-2: ได้รับการประกันโดยอัตโนมัติภายใต้ประกันการจ้างงาน แต่เงินช่วยเหลือการว่างงานและเงินช่วยเหลือการลาเพื่อดูแลบุตรต้องยื่นคำขอลงทะเบียนแยกต่างหาก",
                ky: "E-9/H-2 визасынын ээлери: Иш менен камсыз кылуу камсыздандыруусунун алкагында автоматтык түрдө камсыздандырылат, бирок жумушсуздук боюнча жөлөкпул жана баланы багуу өргүүсү боюнча жөлөкпул өзүнчө каттоо арызын талап кылат",
                km: "ម្ចាស់ទិដ្ឋាការ E-9/H-2: ត្រូវបានធានារ៉ាប់រងដោយស្វ័យប្រវត្តិក្រោមការធានារ៉ាប់រងការងារ ប៉ុន្តែប្រាក់ឧបត្ថម្ភភាពអត់ការងារធ្វើ និងប្រាក់ឧបត្ថម្ភឈប់សម្រាកថែទាំកុមារ តម្រូវឱ្យមានការដាក់ពាក្យសុំចុះឈ្មោះដាច់ដោយឡែក",
                id: "Pemegang visa E-9/H-2: Secara otomatis diasuransikan dalam asuransi ketenagakerjaan, tetapi tunjangan pengangguran dan tunjangan cuti pengasuhan anak memerlukan aplikasi pendaftaran terpisah",
                si: "E-9/H-2 වීසා හිමියන්: ස්වයංක්‍රීයව රැකියා රක්ෂණය යටතේ ආවරණය වේ, නමුත් රැකියා විරහිත ප්‍රතිලාභ සහ ළමා රැකවරණ නිවාඩු ප්‍රතිලාභ සඳහා වෙනම ලියාපදිංචි අයදුම්පතක් අවශ්‍ය වේ.",
                bn: "E-9/H-2 ভিসা ধারকগণ: স্বয়ংক্রিয়ভাবে কর্মসংস্থান বীমার আওতাভুক্ত, তবে বেকারত্ব ভাতা এবং শিশু যত্ন ছুটির ভাতার জন্য আলাদাভাবে আবেদন করতে হবে।",
                my: "E-9/H-2 ဗီဇာ ကိုင်ဆောင်သူများ- အလုပ်အကိုင် အာမခံ အောက်တွင် အလိုအလျောက် အာမခံထားပြီး ဖြစ်သော်လည်း အလုပ်လက်မဲ့ ထောက်ပံ့ကြေးနှင့် ကလေးထိန်းခွင့် ထောက်ပံ့ကြေးများအတွက် သီးခြား စာရင်းသွင်း လျှောက်ထားရန် လိုအပ်ပါသည်။",
                mn: "E-9/H-2 виз эзэмшигчид: Ажил эрхлэлтийн даатгалд автоматаар хамрагддаг боловч ажилгүйдлийн тэтгэмж болон хүүхэд асрах чөлөөний тэтгэмж нь тусдаа бүртгүүлэх шаардлагатай",
                lo: "ຜູ້ຖືວີຊາ E-9/H-2: ໄດ້ຮັບການປະກັນໄພໂດຍອັດຕະໂນມັດພາຍໃຕ້ການປະກັນໄພການຈ້າງງານ, ແຕ່ເງິນອຸດໜູນການຫວ່າງງານ ແລະ ເງິນອຸດໜູນການລາພັກລ້ຽງດູລູກ ຕ້ອງໄດ້ສະໝັກລົງທະບຽນຕ່າງຫາກ.",
                tet:
                    "Na'in ba viza E-9/H-2: Otomatikmente seguradu iha seguru empregu, maibé subsídiu dezempregu no subsídiu lisensa kuidadu labarik presiza rejistu separadu.",
                ne: "E-9/H-2 भिसा धारकहरू: रोजगार बीमा अन्तर्गत स्वतः बीमा गरिएका हुन्छन्, तर बेरोजगारी भत्ता र बाल हेरचाह बिदा भत्ताका लागि छुट्टै दर्ता आवेदन आवश्यक पर्छ।",
                zh: 'E-9、H-2签证：自动成为雇佣保险的被保险人，但失业补助金、育儿休职补助金需另行申请参保后方可适用',
                vi: 'Diện lưu trú E-9, H-2: Đương nhiên là đối tượng được bảo hiểm việc làm bảo vệ, nhưng trợ cấp thất nghiệp và trợ cấp nghỉ chăm con cần đăng ký tham gia riêng mới được áp dụng',
                uz: "E-9/H-2 viza egalari: Bandlik sugʻurtasi boʻyicha avtomatik sugʻurtalangan, ammo ishsizlik nafaqalari va bolalar parvarishi taʼtillari nafaqalari alohida roʻyxatdan oʻtish arizasini talab qiladi",
              ),
              L10nText(
                ko: 'D-1~D-6, D-10 체류자격: 고용보험 가입 불가',
                en: 'D-1 through D-6 and D-10 visa holders: Not eligible to enroll in employment insurance',
                tr: "D-1'den D-6'ya ve D-10 vizesi sahipleri: İstihdam sigortasına kayıt olmaya uygun değildir",
                tg: "Дорандагони раводиди D-1 то D-6 ва D-10: Барои бақайдгирӣ дар суғуртаи шуғл мувофиқ нестанд.",
                fil:
                    "Mga may hawak ng D-1 hanggang D-6 at D-10 visa: Hindi karapat-dapat magparehistro para sa seguro sa trabaho.",
                ur: "D-1 سے D-6 اور D-10 ویزا رکھنے والے: ملازمت کے بیمہ میں رجسٹر ہونے کے اہل نہیں ہیں۔",
                th: "ผู้ถือวีซ่า D-1 ถึง D-6 และ D-10: ไม่มีสิทธิ์ลงทะเบียนประกันการจ้างงาน",
                ky: "D-1'ден D-6'га жана D-10 визасынын ээлери: Иш менен камсыз кылуу камсыздандыруусуна катталууга укугу жок",
                km: "ម្ចាស់ទិដ្ឋាការ D-1 ដល់ D-6 និង D-10: មិនមានសិទ្ធិចុះឈ្មោះក្នុងការធានារ៉ាប់រងការងារទេ",
                id: "Pemegang visa D-1 hingga D-6 dan D-10: Tidak memenuhi syarat untuk mendaftar asuransi ketenagakerjaan",
                si: "D-1 සිට D-6 සහ D-10 වීසා හිමියන්: රැකියා රක්ෂණය සඳහා ලියාපදිංචි වීමට සුදුසුකම් නොලබයි.",
                bn: "D-1 থেকে D-6 এবং D-10 ভিসা ধারকগণ: কর্মসংস্থান বীমার জন্য নিবন্ধন করার যোগ্য নন।",
                my: "D-1 မှ D-6 နှင့် D-10 ဗီဇာ ကိုင်ဆောင်သူများ- အလုပ်အကိုင် အာမခံတွင် စာရင်းသွင်းရန် အရည်အချင်း မပြည့်မီပါ။",
                mn: "D-1-ээс D-6 болон D-10 виз эзэмшигчид: Ажил эрхлэлтийн даатгалд бүртгүүлэх боломжгүй",
                lo: "ຜູ້ຖືວີຊາ D-1 ຫາ D-6 ແລະ D-10: ບໍ່ມີສິດລົງທະບຽນປະກັນໄພການຈ້າງງານ.",
                tet:
                    "Na'in ba viza D-1 to'o D-6 no D-10: La elegível atu rejista ba seguru empregu.",
                ne: "D-1 देखि D-6 र D-10 भिसा धारकहरू: रोजगार बीमामा दर्ता हुन योग्य छैनन्।",
                zh: 'D-1~D-6、D-10签证：不可参加雇佣保险',
                vi: 'Diện lưu trú D-1~D-6, D-10: Không thể tham gia bảo hiểm việc làm',
                uz: "D-1 dan D-6 gacha va D-10 viza egalari: Bandlik sugʻurtasida roʻyxatdan oʻtish huquqiga ega emas",
              ),
            ],
