                en: 'Workers enrolled in employment insurance who leave their job involuntarily can apply for unemployment benefits.',
                tr: "İstihdam sigortasına kayıtlı olup işinden istemsizce ayrılan işçiler işsizlik maaşına başvurabilirler.",
                tg: "Кормандоне, ки дар суғуртаи шуғл ба қайд гирифта шудаанд ва беихтиёр аз кор рафтаанд, метавонанд барои кӯмакпулии бекорӣ муроҷиат кунанд.",
                fil:
