                th: "ลูกจ้างที่ลงทะเบียนประกันการจ้างงานและออกจากงานโดยไม่สมัครใจสามารถยื่นขอเงินช่วยเหลือการว่างงานได้",
                ky: "Иш менен камсыз кылуу камсыздандыруусуна катталып, жумушунан өз эркинен тышкары кеткен жумушчулар жумушсуздук боюнча жөлөкпулга кайрыла алышат.",
                km: "កម្មករដែលបានចុះឈ្មោះក្នុងការធានារ៉ាប់រងការងារ ហើយបានចាកចេញពីការងារដោយអចេតនា អាចដាក់ពាក្យសុំប្រាក់ឧបត្ថម្ភភាពអត់ការងារធ្វើបាន។",
