                bn: "যেসব কর্মী কর্মসংস্থান বীমার আওতাভুক্ত এবং অনিচ্ছাকৃতভাবে চাকরি ছেড়েছেন, তারা বেকারত্ব ভাতার জন্য আবেদন করতে পারবেন।",
                my: "အလုပ်အကိုင် အာမခံတွင် စာရင်းသွင်းထားပြီး အလုပ်မှ မလိုလားဘဲ ထွက်ခွာခဲ့ရသော အလုပ်သမားများသည် အလုပ်လက်မဲ့ ထောက်ပံ့ကြေး လျှောက်ထားနိုင်ပါသည်။",
                mn: "Ажил эрхлэлтийн даатгалд хамрагдсан бөгөөд ажлаасаа өөрийн хүсэлтээр бус гарсан ажилчид ажилгүйдлийн тэтгэмж авах хүсэлт гаргаж болно.",
                lo: "ແຮງງານທີ່ໄດ້ລົງທະບຽນປະກັນໄພການຈ້າງງານ ແລະ ຖືກເລີກຈ້າງໂດຍບໍ່ໄດ້ຕັ້ງໃຈ ສາມາດສະໝັກຂໍເງິນອຸດໜູນການຫວ່າງງານໄດ້.",
