                zh: '已参加雇佣保险的劳动者若非自愿离职，可申请领取失业补助金。',
                vi: 'Người lao động đã tham gia bảo hiểm việc làm nếu nghỉ việc không tự nguyện có thể xin trợ cấp thất nghiệp.',
                uz: "Bandlik sugʻurtasida roʻyxatdan oʻtgan va ishdan ixtiyorsiz ravishda ketgan ishchilar ishsizlik nafaqalarini olish uchun ariza berishlari mumkin.",
              ),
              L10nText(
                ko: '자진 퇴사는 원칙적으로 대상에서 제외되나, 정당한 이직 사유가 인정되면 예외가 있습니다.',
                en: 'Voluntary resignation is generally excluded, but exceptions apply if a legitimate reason for leaving is recognized.',
                tr: "Gönüllü istifa genellikle kapsam dışıdır, ancak ayrılmak için meşru bir nedenin kabul edilmesi durumunda istisnalar uygulanır.",
                tg: "Истеъфои ихтиёрӣ одатан фаро гирифта намешавад, аммо истисноҳо дар сурати қабул шудани сабаби қонунӣ барои тарк кардан татбиқ мешаванд.",
