                th: "การลาออกโดยสมัครใจโดยทั่วไปจะไม่อยู่ในขอบเขต แต่มีข้อยกเว้นหากได้รับการยอมรับว่ามีเหตุผลอันสมควรในการลาออก",
                ky: "Ыктыярдуу түрдө жумуштан кетүү, адатта, камтылбайт, бирок кетүүгө мыйзамдуу себеп катары кабыл алынган учурларда өзгөчөлүктөр колдонулат.",
                km: "ការលាលែងពីតំណែងដោយស្ម័គ្រចិត្តជាទូទៅមិនត្រូវបានរាប់បញ្ចូលទេ ប៉ុន្តែករណីលើកលែងត្រូវបានអនុវត្ត ប្រសិនបើហេតុផលស្របច្បាប់សម្រាប់ការចាកចេញត្រូវបានទទួលស្គាល់។",
                id: "Pengunduran diri secara sukarela umumnya tidak termasuk, tetapi pengecualian berlaku jika alasan yang sah untuk berhenti diakui.",
                si: "ස්වේච්ඡාවෙන් ඉල්ලා අස්වීම සාමාන්‍යයෙන් ආවරණය නොවේ, නමුත් ඉවත්වීමට නීත්‍යානුකූල හේතුවක් පිළිගනු ලැබුවහොත් ව්‍යතිරේක අදාළ වේ.",
                bn: "স্বেচ্ছায় পদত্যাগ সাধারণত এর আওতার বাইরে, তবে যদি ছাড়ার জন্য একটি বৈধ কারণ গ্রহণযোগ্য হয় তবে ব্যতিক্রম প্রযোজ্য।",
                my: "ဆန္ဒအလျောက် နုတ်ထွက်ခြင်းသည် ယေဘုယျအားဖြင့် အကျုံးမဝင်သော်လည်း ထွက်ခွာရန် တရားဝင် အကြောင်းပြချက်ကို လက်ခံပါက ချွင်းချက်များ သက်ရောက်ပါသည်။",
                mn: "Сайн дураараа ажлаас гарах нь ихэвчлэн хамрагдахгүй боловч ажлаас гарах үндэслэлтэй шалтгаан гэж үзвэл үл хамаарах зүйлс үйлчилнэ.",
                lo: "ການລາອອກດ້ວຍຄວາມສະໝັກໃຈໂດຍທົ່ວໄປແມ່ນບໍ່ໄດ້ຮັບການຄຸ້ມຄອງ, ແຕ່ມີຂໍ້ຍົກເວັ້ນຖ້າຫາກມີເຫດຜົນທີ່ຖືກຕ້ອງຕາມກົດໝາຍໃນການລາອອກ.",
                tet:
                    "Demisaun voluntária jeralmente la inklui, maibé ezsesaun sira aplika se karik iha razaun lejítima ida atu husik servisu ne'e.",
                ne: "स्वेच्छिक राजीनामा सामान्यतया कभर गरिँदैन, तर अलग हुनका लागि वैध कारण स्वीकार गरिएमा अपवादहरू लागू हुन्छन्।",
                zh: '原则上自愿离职不属于申请对象，但如认定存在正当离职理由，则可有例外。',
