        summary: L10nText(
          ko: '두 보험 모두 사업주가 가입하는 보험이지만, 근로자의 퇴직금과 체불 임금을 보장한다는 점에서 근로자가 반드시 알아야 합니다.',
          en: 'Both of these insurances are enrolled in by the employer, but since they guarantee the worker\'s severance pay and unpaid wages, workers must understand them as well.',
          tr: "Bu sigortaların her ikisi de işveren tarafından yaptırılır, ancak işçinin kıdem tazminatını ve ödenmemiş ücretlerini garanti ettikleri için işçilerin de bunları anlaması gerekir.",
          tg: "Ҳардуи ин суғуртаҳо аз ҷониби корфармо гирифта мешаванд, аммо кормандон низ бояд онҳоро фаҳманд, зеро онҳо ҷуброни хидмат ва музди меҳнати пардохтнашудаи кормандро кафолат медиҳанд.",
          fil:
              "Ang dalawang segurong ito ay kinukuha ng employer, ngunit kailangan din itong maunawaan ng mga manggagawa dahil ginagarantiya nito ang kanilang severance pay at hindi nabayarang sahod.",
          ur: "یہ دونوں بیمے آجر کی طرف سے کروائے جاتے ہیں، لیکن کارکنان کو بھی انہیں سمجھنا چاہیے کیونکہ یہ کارکن کے سروس بینیفٹس اور غیر ادا شدہ اجرتوں کی ضمانت دیتے ہیں۔",
          th: "ประกันทั้งสองประเภทนี้ดำเนินการโดยนายจ้าง แต่ลูกจ้างก็จำเป็นต้องทำความเข้าใจด้วย เนื่องจากประกันเหล่านี้รับประกันเงินชดเชยการออกจากงานและค่าจ้างที่ค้างจ่ายของลูกจ้าง",
          ky: "Бул камсыздандыруулардын экөө тең жумуш берүүчү тарабынан жүргүзүлөт, бирок алар жумушчунун эмгек акысын жана төлөнбөгөн эмгек акысын кепилдегендиктен, жумушчулар да аларды түшүнүшү керек.",
          km: "ការធានារ៉ាប់រងទាំងពីរនេះត្រូវបានចុះឈ្មោះដោយនិយោជក ប៉ុន្តែកម្មករក៏ត្រូវយល់អំពីវាដែរ ព្រោះវាធានាប្រាក់បំណាច់បញ្ចប់ការងារ និងប្រាក់ឈ្នួលដែលមិនទាន់បានបង់របស់កម្មករ។",
          id: "Kedua asuransi ini didaftarkan oleh pemberi kerja, tetapi pekerja juga perlu memahaminya karena asuransi ini menjamin pesangon dan upah yang belum dibayar kepada pekerja.",
          si: "මෙම රක්ෂණ දෙකම සේවායෝජකයා විසින් ලබා ගනු ලැබේ, නමුත් සේවකයාගේ සේවා කාලය අවසානයේ ගෙවීම් සහ නොගෙවූ වැටුප් සහතික කරන බැවින් සේවකයින් ද ඒවා තේරුම් ගත යුතුය.",
          bn: "এই দুটি বীমাই নিয়োগকর্তা দ্বারা করা হয়, তবে কর্মীদেরও এগুলি বোঝা দরকার কারণ তারা শ্রমিকের সেভারেন্স পে এবং বকেয়া মজুরি নিশ্চিত করে।",
          my: "ဤအာမခံ နှစ်ခုလုံးကို အလုပ်ရှင်မှ ဆောင်ရွက်ပေးသော်လည်း အလုပ်သမား၏ လုပ်သက်ဆုကြေးနှင့် မပေးရသေးသော လုပ်ခများကို အာမခံပေးထားသောကြောင့် အလုပ်သမားများအနေဖြင့်လည်း နားလည်ထားရန် လိုအပ်ပါသည်။",
          mn: "Эдгээр даатгалыг хоёуланг нь ажил олгогч хийдэг боловч ажилчдын тэтгэмж болон төлөгдөөгүй цалинг баталгаажуулдаг тул ажилчид ч мөн ойлгох шаардлагатай.",
          lo: "ປະກັນໄພທັງສອງປະເພດນີ້ແມ່ນນາຍຈ້າງເປັນຜູ້ຈັດການ, ແຕ່ແຮງງານກໍຄວນເຂົ້າໃຈເຊັ່ນກັນ ເພາະມັນຮັບປະກັນເງິນອຸດໜູນການອອກຈາກວຽກ ແລະ ຄ່າຈ້າງທີ່ຍັງຄ້າງຈ່າຍຂອງແຮງງານ.",
          tet:
              "Seguru rua ne'e empregadór mak halo, maibé traballadór sira mós presiza komprende tanba sira garante traballadór nia kompensasaun retiradu no saláriu ne'ebé seidauk selu.",
          ne: "यी दुवै बीमा नियोक्ताद्वारा गराइन्छ, तर यिनीहरूले कामदारको सेवा समाप्ति भत्ता र भुक्तानी नगरिएको ज्यालाको ग्यारेन्टी गर्ने भएकाले कामदारहरूले पनि यिनीहरूलाई बुझ्नुपर्छ।",
          zh: '这两种保险均由用人单位参保，但由于它们保障的是劳动者的退职金和拖欠工资，劳动者本人也必须了解相关内容。',
          vi: 'Cả hai loại bảo hiểm này đều do chủ sử dụng lao động tham gia, nhưng vì chúng bảo đảm tiền trợ cấp thôi việc và tiền lương bị nợ của người lao động nên người lao động nhất định phải nắm rõ.',
          uz: "Bu sugʻurtalarning ikkalasi ham ish beruvchi tomonidan roʻyxatdan oʻtkaziladi, ammo ular ishchining ishdan boʻshatish nafaqasi va toʻlanmagan ish haqini kafolatlagani uchun ishchilar ularni ham tushunishlari kerak.",
        ),
