          km: "កិច្ចសន្យាជួលត្រូវតែបញ្ជាក់យ៉ាងត្រឹមត្រូវអំពីប្រាក់កក់ រយៈពេលជួល និងលក្ខខណ្ឌពិសេស ហើយកិច្ចព្រមព្រៀងផ្ទាល់មាត់គួរតែត្រូវបានកត់ត្រាជានិច្ចជាលក្ខខណ្ឌពិសេស។",
