          bn: "ভাড়ার চুক্তিতে অবশ্যই আমানত, ভাড়ার সময়কাল এবং বিশেষ বিধানগুলি সঠিকভাবে উল্লেখ করতে হবে এবং মৌখিক চুক্তিগুলি সর্বদা বিশেষ বিধান হিসাবে রেকর্ড করা উচিত।",
          my: "အိမ်ငှားစာချုပ်တွင် အပ်ငွေ၊ ငှားရမ်းမှုကာလနှင့် အထူးပြဋ္ဌာန်းချက်များကို တိကျစွာဖော်ပြရမည်ဖြစ်ပြီး နှုတ်ဖြင့်သဘောတူညီချက်များကို အထူးပြဋ္ဌာန်းချက်များအဖြစ် အမြဲမှတ်တမ်းတင်ထားရပါမည်။",
          mn: "Түрээсийн гэрээнд барьцаа, түрээсийн хугацаа, тусгай заалтуудыг үнэн зөв зааж өгөх ёстой бөгөөд амаар хийсэн тохиролцоог үргэлж тусгай заалт болгон тэмдэглэх ёстой.",
          lo: "ສັນຍາເຊົ່າຕ້ອງລະບຸເງິນຄໍ້າປະກັນ, ໄລຍະເວລາເຊົ່າ ແລະ ຂໍ້ກໍານົດພິເສດຢ່າງຖືກຕ້ອງ, ແລະ ຂໍ້ຕົກລົງດ້ວຍວາຈາຄວນຖືກບັນທຶກໄວ້ເປັນຂໍ້ກໍານົດພິເສດສະເໝີ.",
