            bullets: [
              L10nText(
                ko: '"입주 전 발견된 하자는 임대인이 수리한다"처럼 구두 약속은 반드시 특약으로 남겨야 합니다.',
                en: 'Verbal agreements — such as "the landlord will repair any defects found before move-in" — must always be recorded as a special provision.',
                tr: "Sözlü anlaşmalar — örneğin \"ev sahibi taşınmadan önce bulunan tüm kusurları onaracaktır\" gibi — her zaman özel bir hüküm olarak kaydedilmelidir.",
                tg: "Созишномаҳои шифоҳӣ — масалан, «соҳибхона ҳамаи камбудиҳоеро, ки пеш аз кӯчидан пайдо шудаанд, таъмир мекунад» — бояд ҳамеша ҳамчун муқаррароти махсус сабт карда шаванд.",
