                th: "ข้อตกลงด้วยวาจา เช่น “เจ้าของบ้านจะซ่อมแซมข้อบกพร่องทั้งหมดที่พบก่อนการย้ายเข้า” ควรถูกบันทึกเป็นข้อกำหนดพิเศษเสมอ",
                ky: "Оозеки макулдашуулар — мисалы, \"үй ээси көчүп кирүүдөн мурун бардык кемчиликтерди оңдойт\" сыяктуу — ар дайым атайын жобо катары жазылышы керек.",
