                bn: "মৌখিক চুক্তি — যেমন “বাড়িওয়ালা স্থানান্তরের আগে বিদ্যমান সমস্ত ত্রুটি মেরামত করবে” — সর্বদা একটি বিশেষ বিধান হিসাবে রেকর্ড করা উচিত।",
