                lo: "ຂໍ້ຕົກລົງດ້ວຍວາຈາ — ຕົວຢ່າງເຊັ່ນ \"ເຈົ້າຂອງເຮືອນຈະສ້ອມແປງຂໍ້ບົກພ່ອງທັງໝົດທີ່ພົບເຫັນກ່ອນຍ້າຍເຂົ້າ\" — ຄວນຖືກບັນທຶກໄວ້ເປັນຂໍ້ກໍານົດພິເສດສະເໝີ.",
