                uz: "Ogʻzaki kelishuvlar — masalan, “uy egasi koʻchib oʻtishdan oldin aniqlangan har qanday nuqsonlarni tuzatadi” — har doim maxsus qoida sifatida qayd etilishi kerak.",
              ),
              L10nText(
