                bn: "রক্ষণাবেক্ষণ ফি-এর আইটেমগুলি (বিদ্যুৎ, জল এবং ইন্টারনেট অন্তর্ভুক্ত কিনা) এবং পরিমাণ বিস্তারিতভাবে উল্লেখ করুন।",
                my: "ပြုပြင်ထိန်းသိမ်းခ ကုန်ကျစရိတ်များ (လျှပ်စစ်၊ ရေနှင့် အင်တာနက် ပါဝင်ခြင်း ရှိ၊ မရှိ) နှင့် ပမာဏကို အသေးစိတ်ဖော်ပြပါ။",
