          fil:
              "Pagprotekta sa Iyong Deposito: Pag-uulat ng Pagbabago ng Tirahan at Pagkuha ng Nakapirming Petsa",
          ur: "اپنے ڈپازٹ کا تحفظ: رہائش کی تبدیلی کا نوٹس اور مقررہ تاریخ حاصل کرنا",
          th: "การปกป้องเงินมัดจำของคุณ: การแจ้งเปลี่ยนที่อยู่และการรับวันที่แน่นอน",
          ky: "Депозитиңизди коргоо: Жашаган жерин өзгөртүү жөнүндө билдирүү жана туруктуу датаны алуу",
          km: "ការការពារប្រាក់កក់របស់អ្នក៖ ការជូនដំណឹងអំពីការផ្លាស់ប្តូរទីលំនៅ និងការទទួលបានកាលបរិច្ឆេទកំណត់",
          id: "Melindungi Deposit Anda: Pemberitahuan Perubahan Tempat Tinggal dan Mendapatkan Tanggal Tetap",
          si: "ඔබේ තැන්පතුව ආරක්ෂා කිරීම: පදිංචිය වෙනස් කිරීමේ දැනුම්දීම සහ ස්ථාවර දිනයක් ලබා ගැනීම",
          bn: "আপনার আমানত রক্ষা করা: বাসস্থান পরিবর্তনের বিজ্ঞপ্তি এবং একটি নিশ্চিত তারিখ প্রাপ্তি",
          my: "သင်၏ အပ်ငွေကို ကာကွယ်ခြင်း- နေထိုင်မှုပြောင်းလဲခြင်း အကြောင်းကြားစာနှင့် သတ်မှတ်ရက်စွဲ ရယူခြင်း",
          mn: "Барьцаагаа хамгаалах: Оршин суух хаягийн өөрчлөлтийг мэдэгдэх, тогтсон огноо авах",
          lo: "ການປົກປ້ອງເງິນຄໍ້າປະກັນຂອງທ່ານ: ການແຈ້ງການປ່ຽນແປງທີ່ຢູ່ອາໄສ ແລະ ການໄດ້ຮັບວັນທີກໍານົດ",
          tet:
              "Protesaun ba Ó-nia Depózitu: Notifikasaun Mudansa Rezidénsia no Simu Data Fiksa",
          ne: "तपाईंको धरौटीको सुरक्षा: निवास परिवर्तनको सूचना र निश्चित मिति प्राप्त गर्ने",
          zh: '押金保护：居留地变更申报与确定日期',
          vi: 'Bảo vệ tiền đặt cọc: Khai báo thay đổi nơi cư trú và xin ngày xác định',
          uz: "Depozitingizni himoya qilish: Yashash joyini oʻzgartirish haqida xabar berish va belgilangan sanani olish",
        ),
        summary: L10nText(
          ko: '외국인은 주민등록 전입신고 대신 체류지변경신고를 하고, 임대차계약서에 확정일자를 받아야 보증금에 대한 법적 보호(대항력·우선변제권)를 얻습니다.',
          en: 'Foreigners must file a report of change of residence (instead of a resident registration move-in report) and obtain a fixed date on the lease agreement in order to gain legal protection for their deposit — the right of opposability and the priority repayment right.',
          tr: "Yabancılar, depozitoları için yasal koruma — karşı çıkma hakkı ve öncelikli geri ödeme hakkı — elde etmek amacıyla ikamet değişikliği bildirimi (ikamet kaydı taşınma bildirimi yerine) yapmalı ve kira sözleşmesinde sabit bir tarih almalıdır.",
          tg: "Хориҷиён бояд барои ба даст овардани ҳифзи ҳуқуқӣ барои пасандозҳои худ — ҳуқуқи эътироз ва ҳуқуқи баргардонидани афзалиятнок — огоҳинома дар бораи тағйири истиқомат (ба ҷои огоҳинома дар бораи кӯчидани бақайдгирии истиқомат) пешниҳод кунанд ва дар шартномаи иҷора санаи муқарраршударо гиранд.",
          fil:
              "Upang makakuha ng legal na proteksyon — karapatan sa pagtutol at karapatan sa prayoridad na pagbabayad — para sa kanilang deposito, ang mga dayuhan ay dapat mag-ulat ng pagbabago ng tirahan (sa halip na pag-uulat ng paglipat ng rehistro ng tirahan) at kumuha ng nakapirming petsa sa kontrata sa pag-upa.",
          ur: "غیر ملکیوں کو اپنے ڈپازٹ کے لیے قانونی تحفظ — اعتراض کا حق اور ترجیحی واپسی کا حق — حاصل کرنے کے لیے رہائش کی تبدیلی کا نوٹس (رہائش کی رجسٹریشن کی منتقلی کے نوٹس کے بجائے) دینا چاہیے اور کرایہ کے معاہدے پر ایک مقررہ تاریخ حاصل کرنی چاہیے۔",
          th: "ชาวต่างชาติควรแจ้งเปลี่ยนที่อยู่ (แทนการแจ้งย้ายที่อยู่) และรับวันที่แน่นอนในสัญญาเช่า เพื่อให้ได้รับความคุ้มครองทางกฎหมายสำหรับเงินมัดจำของตน — สิทธิในการคัดค้านและสิทธิในการได้รับคืนก่อน",
          ky: "Чет элдиктер депозиттери үчүн мыйзамдуу коргоону — каршы чыгуу укугун жана артыкчылыктуу кайтарып алуу укугун — алуу максатында жашаган жерин өзгөртүү жөнүндө билдирүү (жашаган жерин каттоо көчүрүү билдирүүсүнүн ордуна) жасашы жана ижара келишиминде туруктуу датаны алышы керек.",
          km: "ជនបរទេសត្រូវតែធ្វើការជូនដំណឹងអំពីការផ្លាស់ប្តូរទីលំនៅ (ជំនួសឱ្យការជូនដំណឹងអំពីការផ្លាស់ប្តូរការចុះឈ្មោះទីលំនៅ) និងទទួលបានកាលបរិច្ឆេទកំណត់លើកិច្ចសន្យាជួល ដើម្បីទទួលបានការការពារផ្លូវច្បាប់សម្រាប់ប្រាក់កក់របស់ពួកគេ — សិទ្ធិជំទាស់ និងសិទ្ធិទទួលបានការសងប្រាក់វិញជាអាទិភាព។",
          id: "Warga asing harus mengajukan pemberitahuan perubahan tempat tinggal (bukan pemberitahuan pindah registrasi tempat tinggal) dan mendapatkan tanggal tetap pada kontrak sewa untuk mendapatkan perlindungan hukum — hak untuk menentang dan hak pembayaran prioritas — untuk deposit mereka.",
          si: "විදේශිකයන් තම තැන්පතු සඳහා නීතිමය ආරක්ෂාව — විරෝධතා දැක්වීමේ අයිතිය සහ ප්‍රමුඛතා ප්‍රතිපූරණය කිරීමේ අයිතිය — ලබා ගැනීම සඳහා පදිංචිය වෙනස් කිරීමේ දැනුම්දීමක් (පදිංචි ලියාපදිංචි මාරු කිරීමේ දැනුම්දීම වෙනුවට) කළ යුතු අතර බදු ගිවිසුමේ ස්ථාවර දිනයක් ලබා ගත යුතුය.",
          bn: "বিদেশীদের তাদের আমানতের জন্য আইনি সুরক্ষা — প্রতিবাদের অধিকার এবং অগ্রাধিকারমূলক পরিশোধের অধিকার — পেতে বাসস্থান পরিবর্তনের বিজ্ঞপ্তি (বাসস্থান নিবন্ধনের স্থানান্তরের বিজ্ঞপ্তির পরিবর্তে) ফাইল করতে হবে এবং ভাড়ার চুক্তিতে একটি নিশ্চিত তারিখ পেতে হবে।",
          my: "နိုင်ငံခြားသားများသည် ၎င်းတို့၏ အပ်ငွေများအတွက် တရားဝင်အကာအကွယ် — ကန့်ကွက်ပိုင်ခွင့်နှင့် ဦးစားပေးပြန်အမ်းငွေရပိုင်ခွင့် — ရရှိရန်အတွက် နေထိုင်မှုပြောင်းလဲခြင်း အကြောင်းကြားစာ (နေထိုင်မှုမှတ်ပုံတင် ပြောင်းရွှေ့ခြင်း အကြောင်းကြားစာအစား) ကို ပြုလုပ်ပြီး အိမ်ငှားစာချုပ်တွင် သတ်မှတ်ရက်စွဲကို ရယူရပါမည်။",
          mn: "Гадаадын иргэд барьцаагаа хууль ёсны хамгаалалтад авахын тулд — эсэргүүцэх эрх, тэргүүн ээлжинд буцаан авах эрх — оршин суух хаягийн өөрчлөлтийг мэдэгдэж (оршин суух бүртгэлийн шилжилтийн мэдэгдлийн оронд) түрээсийн гэрээнд тогтсон огноо авах ёстой.",
          lo: "ຄົນຕ່າງປະເທດຕ້ອງແຈ້ງການປ່ຽນແປງທີ່ຢູ່ອາໄສ (ແທນທີ່ຈະເປັນການລາຍງານການຍ້າຍເຂົ້າສໍາລັບການລົງທະບຽນທີ່ຢູ່ອາໄສ) ແລະ ໄດ້ຮັບວັນທີກໍານົດໃນສັນຍາເຊົ່າ ເພື່ອໃຫ້ໄດ້ຮັບການປົກປ້ອງທາງກົດໝາຍສໍາລັບເງິນຄໍ້າປະກັນຂອງພວກເຂົາ — ສິດທິໃນການຄັດຄ້ານ ແລະ ສິດທິໃນການໄດ້ຮັບເງິນຄືນກ່ອນ.",
          tet:
              "Estranjeiru sira, atu hetan protesaun legál ba sira-nia depózitu — direitu atu opozisaun no direitu ba pagamentu uluk — tenke halo notifikasaun mudansa rezidénsia (duke notifikasaun mudansa rejistu rezidénsia) no simu data fiksa ida iha kontratu arrendamentu.",
          ne: "विदेशीहरूले आफ्नो धरौटीको लागि कानूनी सुरक्षा — आपत्ति गर्ने अधिकार र प्राथमिकताका साथ फिर्ता पाउने अधिकार — प्राप्त गर्न निवास परिवर्तनको सूचना (निवास दर्ताको लागि सर्ने सूचनाको सट्टा) दिनुपर्छ र भाडा सम्झौतामा निश्चित मिति प्राप्त गर्नुपर्छ।",
          zh: '外国人应办理居留地变更申报（而非韩国国民的居民登记迁入申报），并在租赁合同上取得确定日期，才能获得对押金的法律保护（对抗力、优先受偿权）。',
          vi: 'Người nước ngoài cần khai báo thay đổi nơi cư trú (thay vì khai báo chuyển đến cư trú theo đăng ký thường trú) và xin ngày xác định trên hợp đồng thuê nhà thì mới được bảo vệ pháp lý đối với tiền đặt cọc (hiệu lực đối kháng, quyền được ưu tiên hoàn trả).',
          uz: "Chet elliklar oʻz depozitlari uchun huquqiy himoya — qarshi qoʻyish huquqi va ustuvor toʻlov huquqini olish uchun yashash joyini oʻzgartirish toʻgʻrisida hisobot (rezident roʻyxatga olish koʻchib oʻtish hisoboti oʻrniga) topshirishlari va ijara shartnomasida belgilangan sanani olishlari shart.",
        ),
