                th: "สิทธิในการคัดค้าน: มีผลบังคับใช้ในวันถัดไปหลังจากย้ายเข้าและแจ้งเปลี่ยนที่อยู่เรียบร้อยแล้ว",
                ky: "Каршы чыгуу укугу: Көчүп киргенден жана жашаган жерин өзгөртүү жөнүндө билдирүүнү аяктагандан кийинки күнү күчүнө кирет",
                km: "សិទ្ធិជំទាស់៖ មានប្រសិទ្ធភាពនៅថ្ងៃបន្ទាប់ពីអ្នកបានផ្លាស់ប្តូរទីលំនៅ និងបានបញ្ចប់ការជូនដំណឹងអំពីការផ្លាស់ប្តូរទីលំនៅ។",
                id: "Hak untuk menentang: Berlaku pada hari setelah Anda pindah dan menyelesaikan pemberitahuan perubahan tempat tinggal.",
                si: "විරෝධතා දැක්වීමේ අයිතිය: ඔබ පදිංචියට ගොස් පදිංචිය වෙනස් කිරීමේ දැනුම්දීම සම්පූර්ණ කළ පසු දින සිට බලාත්මක වේ.",
                bn: "প্রতিবাদের অধিকার: স্থানান্তরের পরের দিন এবং বাসস্থান পরিবর্তনের বিজ্ঞপ্তি সম্পন্ন হওয়ার পরের দিন থেকে কার্যকর হয়।",
                my: "ကန့်ကွက်ပိုင်ခွင့်- ပြောင်းရွှေ့ပြီး နေထိုင်မှုပြောင်းလဲခြင်း အကြောင်းကြားစာကို ပြီးစီးသည့် နောက်တစ်နေ့တွင် အသက်ဝင်ပါသည်။",
                mn: "Эсэргүүцэх эрх: Нүүж, оршин суух хаягийн өөрчлөлтийг мэдэгдсэнээс хойш дараагийн өдөр хүчин төгөлдөр болно.",
                lo: "ສິດທິໃນການຄັດຄ້ານ: ມີຜົນບັງຄັບໃຊ້ໃນມື້ຕໍ່ມາຫຼັງຈາກຍ້າຍເຂົ້າ ແລະ ສໍາເລັດການແຈ້ງການປ່ຽນແປງທີ່ຢູ່ອາໄສ.",
                tet:
                    "Direitu atu opozisaun: Tama iha vigor iha loron tuirmai depois muda no kompleta notifikasaun mudansa rezidénsia.",
                ne: "आपत्ति गर्ने अधिकार: सरेको र निवास परिवर्तनको सूचना पूरा गरेको भोलिपल्टदेखि लागू हुन्छ।",
                zh: '对抗力：自搬入并完成居留地变更申报的次日起生效',
                vi: 'Hiệu lực đối kháng: Phát sinh từ ngày hôm sau khi hoàn tất việc chuyển đến ở và khai báo thay đổi nơi cư trú',
                uz: "Qarshi qoʻyish huquqi: Siz koʻchib oʻtganingizdan va yashash joyini oʻzgartirish hisobotini tugatganingizdan keyingi kun kuchga kiradi",
              ),
              L10nText(
                ko: '우선변제권: 대항력 + 확정일자를 모두 갖춰야 발생, 경매·매매 시 순위대로 보증금을 우선 돌려받을 수 있습니다.',
                en: 'Priority repayment right: Arises only when you have both the right of opposability and a fixed date; in the event of an auction or sale, it allows you to recover your deposit ahead of other creditors according to your priority ranking.',
                tr: "Öncelikli geri ödeme hakkı: Sadece hem itiraz hakkına hem de sabit bir tarihe sahip olduğunuzda ortaya çıkar; bir açık artırma veya satış durumunda, öncelik sıralamanıza göre depozitonuzu diğer alacaklılardan önce geri almanızı sağlar.",
                tg: "Ҳуқуқи баргардонидани афзалиятнок: Танҳо вақте пайдо мешавад, ки шумо ҳам ҳуқуқи эътироз ва ҳам санаи муқарраршуда доред; дар ҳолати музояда ё фурӯш, он ба шумо имкон медиҳад, ки пасандози худро пеш аз дигар қарздиҳандагон мувофиқи тартиби афзалияти худ баргардонед.",
                fil:
                    "Karapatan sa prayoridad na pagbabayad: Lumilitaw lamang kapag mayroon kang parehong karapatan sa pagtutol at isang nakapirming petsa; sa kaso ng subasta o pagbebenta, pinapayagan ka nitong mabawi ang iyong deposito bago ang ibang mga nagpapautang, ayon sa iyong ranggo ng prayoridad.",
                ur: "ترجیحی واپسی کا حق: یہ صرف اس صورت میں پیدا ہوتا ہے جب آپ کے پاس اعتراض کا حق اور ایک مقررہ تاریخ دونوں ہوں؛ نیلامی یا فروخت کی صورت میں، یہ آپ کو اپنی ترجیحی درجہ بندی کے مطابق دوسرے قرض دہندگان سے پہلے اپنا ڈپازٹ واپس حاصل کرنے کی اجازت دیتا ہے۔",
                th: "สิทธิในการได้รับคืนก่อน: เกิดขึ้นเมื่อคุณมีทั้งสิทธิในการคัดค้านและวันที่แน่นอนเท่านั้น ในกรณีที่มีการประมูลหรือการขาย จะช่วยให้คุณได้รับเงินมัดจำคืนก่อนเจ้าหนี้รายอื่นตามลำดับความสำคัญของคุณ",
                ky: "Артыкчылыктуу кайтарып алуу укугу: Бул каршы чыгуу укугуна жана туруктуу датага ээ болгондо гана пайда болот; аукцион же сатуу болгон учурда, ал сиздин артыкчылыктуу тартибиңизге ылайык, депозитиңизди башка кредиторлордон мурун кайтарып алууга мүмкүндүк берет.",
                km: "សិទ្ធិទទួលបានការសងប្រាក់វិញជាអាទិភាព៖ កើតឡើងលុះត្រាតែអ្នកមានទាំងសិទ្ធិជំទាស់ និងកាលបរិច្ឆេទកំណត់។ ក្នុងករណីមានការដេញថ្លៃ ឬការលក់ វាអនុញ្ញាតឱ្យអ្នកទទួលបានប្រាក់កក់របស់អ្នកមកវិញមុនម្ចាស់បំណុលផ្សេងទៀត យោងតាមលំដាប់អាទិភាពរបស់អ្នក។",
                id: "Hak pembayaran prioritas: Hanya muncul ketika Anda memiliki hak untuk menentang dan tanggal tetap; dalam kasus lelang atau penjualan, ini memungkinkan Anda untuk mendapatkan kembali deposit Anda sebelum kreditor lain sesuai dengan urutan prioritas Anda.",
                si: "ප්‍රමුඛතා ප්‍රතිපූරණය කිරීමේ අයිතිය: ඔබට විරෝධතා දැක්වීමේ අයිතිය සහ ස්ථාවර දිනයක් යන දෙකම ඇති විට පමණක් පැන නගී; වෙන්දේසියක් හෝ විකිණීමක් සිදු වුවහොත්, ඔබේ ප්‍රමුඛතා අනුපිළිවෙල අනුව අනෙකුත් ණය හිමියන්ට පෙර ඔබේ තැන්පතුව ආපසු ලබා ගැනීමට එය ඔබට ඉඩ සලසයි.",
                bn: "অগ্রাধিকারমূলক পরিশোধের অধিকার: এটি তখনই উদ্ভূত হয় যখন আপনার প্রতিবাদের অধিকার এবং একটি নিশ্চিত তারিখ উভয়ই থাকে; একটি নিলাম বা বিক্রয়ের ক্ষেত্রে, এটি আপনাকে অন্যান্য পাওনাদারদের আগে আপনার অগ্রাধিকারের ক্রম অনুসারে আপনার আমানত ফেরত পেতে দেয়।",
                my: "ဦးစားပေးပြန်အမ်းငွေရပိုင်ခွင့်- ကန့်ကွက်ပိုင်ခွင့်နှင့် သတ်မှတ်ရက်စွဲ နှစ်ခုလုံးရှိမှသာ ပေါ်ပေါက်လာပြီး လေလံတင်ရောင်းချခြင်း သို့မဟုတ် ရောင်းချခြင်းကိစ္စတွင် အခြားသော ကြွေးရှင်များထက် သင့်ဦးစားပေးအဆင့်အတန်းအရ သင့်အပ်ငွေကို ပြန်လည်ရရှိစေပါသည်။",
                mn: "Тэргүүн ээлжинд буцаан авах эрх: Зөвхөн эсэргүүцэх эрх болон тогтсон огноо хоёулаа байх үед үүсдэг; дуудлага худалдаа эсвэл худалдааны үед таны барьцааг бусад зээлдүүлэгчдээс өмнө таны тэргүүн ээлжийн дарааллын дагуу буцаан авахад тусална.",
                lo: "ສິດທິໃນການໄດ້ຮັບເງິນຄືນກ່ອນ: ເກີດຂຶ້ນເມື່ອທ່ານມີທັງສິດທິໃນການຄັດຄ້ານ ແລະ ວັນທີກໍານົດເທົ່ານັ້ນ; ໃນກໍລະນີທີ່ມີການປະມູນ ຫຼື ການຂາຍ, ມັນຊ່ວຍໃຫ້ທ່ານສາມາດໄດ້ຮັບເງິນຄໍ້າປະກັນຄືນກ່ອນເຈົ້າໜີ້ອື່ນໆ, ຕາມລໍາດັບຄວາມສໍາຄັນຂອງທ່ານ.",
                tet:
                    "Direitu ba pagamentu uluk: Mosu de'it bainhira ó iha direitu atu opozisaun no data fiksa ida; iha kazu leilaun ka fa'an, ne'e permite ó atu simu fali ó-nia depózitu antes kreditor sira seluk, tuir ó-nia orden prioridade.",
                ne: "प्राथमिकताका साथ फिर्ता पाउने अधिकार: यो तब मात्र उत्पन्न हुन्छ जब तपाईंसँग आपत्ति गर्ने अधिकार र निश्चित मिति दुवै हुन्छ; लिलामी वा बिक्रीको अवस्थामा, यसले तपाईंको प्राथमिकता क्रम अनुसार अन्य ऋणदाताहरू भन्दा पहिले तपाईंको धरौटी फिर्ता पाउन सक्षम बनाउँछ।",
                zh: '优先受偿权：须同时具备对抗力和确定日期才能生效，在拍卖或买卖时可按顺位优先领回押金。',
                vi: 'Quyền được ưu tiên hoàn trả: Chỉ phát sinh khi có đủ cả hiệu lực đối kháng và ngày xác định, khi đấu giá hoặc mua bán tài sản, bạn có thể được ưu tiên nhận lại tiền đặt cọc theo thứ tự.',
                uz: "Ustuvor toʻlov huquqi: Faqat sizda ham qarshi qoʻyish huquqi, ham belgilangan sana boʻlganda yuzaga keladi; kim oshdi savdosi yoki sotish holatida, u sizga depozitingizni boshqa kreditorlardan oldin ustuvorlik darajangizga koʻra qaytarib olish imkonini beradi.",
              ),
