                ur: "طریقہ A: اپنے نئے پتے کے کمیونٹی سروسز سینٹر کا اصل کرایہ کے معاہدے کے ساتھ دورہ کریں (یہ آپ کے رہائش کی تبدیلی کے نوٹس کے ساتھ کرنے کی سفارش کی جاتی ہے)",
                th: "วิธี A: เยี่ยมชมศูนย์บริการชุมชนของที่อยู่ใหม่ของคุณพร้อมสัญญาเช่าฉบับจริง (แนะนำให้ทำพร้อมกับการแจ้งเปลี่ยนที่อยู่ของคุณ)",
                ky: "А ыкмасы: Жаңы дарегиңиздеги коомдук тейлөө борборуна түп нуска ижара келишими менен барыңыз (муну жашаган жериңизди өзгөртүү жөнүндө билдирүүңүз менен бирге жасоо сунушталат)",
                km: "វិធីសាស្ត្រ A៖ ទៅកាន់មជ្ឈមណ្ឌលសេវាសហគមន៍នៃអាសយដ្ឋានថ្មីរបស់អ្នកជាមួយនឹងកិច្ចសន្យាជួលដើម (វាត្រូវបានណែនាំឱ្យធ្វើបែបនេះរួមជាមួយនឹងការជូនដំណឹងអំពីការផ្លាស់ប្តូរទីលំនៅរបស់អ្នក)",
                id: "Metode A: Kunjungi pusat layanan komunitas di alamat baru Anda dengan kontrak sewa asli (disarankan untuk melakukan ini bersamaan dengan pemberitahuan perubahan tempat tinggal Anda).",
