                bn: "পদ্ধতি A: আপনার নতুন ঠিকানার কমিউনিটি সার্ভিস সেন্টারে আসল ভাড়ার চুক্তি নিয়ে যান (আপনার বাসস্থান পরিবর্তনের বিজ্ঞপ্তির সাথে এটি করার পরামর্শ দেওয়া হয়)।",
                my: "နည်းလမ်း A: သင်၏နေရပ်လိပ်စာအသစ်ရှိ ရပ်ရွာဝန်ဆောင်မှုစင်တာသို့ မူရင်းအိမ်ငှားစာချုပ်နှင့်အတူ သွားရောက်ပါ (သင်၏နေထိုင်မှုပြောင်းလဲခြင်း အကြောင်းကြားစာနှင့်အတူ ပြုလုပ်ရန် အကြံပြုပါသည်)",
                mn: "Арга А: Шинэ хаягийнхаа олон нийтийн үйлчилгээний төвд түрээсийн гэрээний эх хувьтайгаа очих (үүнийг оршин суух хаягийн өөрчлөлтийн мэдэгдэлтэй хамт хийхийг зөвлөж байна)",
                lo: "ວິທີ A: ໄປຢ້ຽມຢາມສູນບໍລິການຊຸມຊົນຂອງທີ່ຢູ່ໃໝ່ຂອງທ່ານພ້ອມກັບສັນຍາເຊົ່າຕົ້ນສະບັບ (ແນະນໍາໃຫ້ເຮັດພ້ອມກັບການແຈ້ງການປ່ຽນແປງທີ່ຢູ່ອາໄສຂອງທ່ານ).",
                tet:
