                ne: "विधि A: आफ्नो नयाँ ठेगानाको सामुदायिक सेवा केन्द्रमा मौलिक भाडा सम्झौता लिएर जानुहोस् (यो तपाईंको निवास परिवर्तनको सूचनासँगै गर्न सिफारिस गरिन्छ)।",
