                km: "រយៈពេលសម្រាប់ការជូនដំណឹងអំពីការផ្លាស់ប្តូរទីលំនៅគឺក្នុងរយៈពេល 15 ថ្ងៃបន្ទាប់ពីការផ្លាស់ប្តូរទីលំនៅ — សូមមើល ④ ការជូនដំណឹងអំពីទីលំនៅ",
