                bn: "বাসস্থান পরিবর্তনের বিজ্ঞপ্তি দেওয়ার সময়সীমা স্থানান্তরের 15 দিনের মধ্যে — দেখুন ④ বাসস্থান বিজ্ঞপ্তি।",
                my: "နေထိုင်မှုပြောင်းလဲခြင်းကို အကြောင်းကြားရမည့်ကာလသည် ပြောင်းရွှေ့ပြီးနောက် 15 ရက်အတွင်း ဖြစ်သည် — ④ နေထိုင်မှု အကြောင်းကြားစာကို ကြည့်ပါ။",
                mn: "Оршин суух хаягийн өөрчлөлтийг мэдэгдэх хугацаа нь нүүснээс хойшхи 15 хоногийн дотор байна — ④ Оршин суух хаягийн мэдэгдлийг үзнэ үү.",
