                vi: 'Thời hạn khai báo thay đổi nơi cư trú là trong vòng 15 ngày kể từ khi chuyển đến — tham khảo mục ④ Khai báo cư trú',
                uz: "Yashash joyini oʻzgartirish haqida xabar berish muddati koʻchib oʻtgan kundan boshlab 15 kun ichida — ④ Yashash joyi haqida hisobotga qarang",
