            bullets: [
              L10nText(
                ko: '주택도시보증공사(HUG) 등의 전세보증금 반환보증에 가입하면 임대인이 반환하지 못해도 보증기관이 대신 지급합니다.',
                en: 'If you enroll in a Jeonse deposit return guarantee, such as one offered by the Korea Housing & Urban Guarantee Corporation (HUG), the guarantee institution will pay you even if the landlord is unable to return your deposit.',
                tr: "Kore Konut ve Kentsel Garanti Kurumu (HUG) tarafından sunulan gibi bir Jeonse depozito iade garantisine kaydolursanız, ev sahibi depozitonuzu iade edemese bile garanti kurumu size ödeme yapacaktır.",
                tg: "Агар шумо дар кафолати баргардонидани пасандози Ҷонсе, ки аз ҷониби Корпоратсияи кафолати манзил ва шаҳрсозии Корея (HUG) пешниҳод шудааст, ба қайд гиред, ҳатто агар соҳибхона натавонад пасандози шуморо баргардонад, корпоратсияи кафолат ба шумо пардохт мекунад.",
                fil:
                    "Kung magparehistro ka para sa isang garantiya sa pagbabalik ng deposito ng Jeonse, tulad ng inaalok ng Korea Housing & Urban Guarantee Corporation (HUG), babayaran ka ng institusyon ng garantiya kahit na hindi maibalik ng may-ari ang iyong deposito.",
                ur: "اگر آپ جیونسی ڈپازٹ ریفنڈ گارنٹی کے لیے سائن اپ کرتے ہیں، جیسا کہ کوریا ہاؤسنگ اینڈ اربن گارنٹی کارپوریشن (HUG) کی طرف سے پیش کیا جاتا ہے، تو گارنٹی کارپوریشن آپ کو ادائیگی کرے گی چاہے مالک مکان آپ کا ڈپازٹ واپس نہ کر سکے۔",
                th: "หากคุณลงทะเบียนประกันการคืนเงินมัดจำ Jeonse เช่นที่เสนอโดย Korea Housing & Urban Guarantee Corporation (HUG) แม้ว่าเจ้าของบ้านจะไม่สามารถคืนเงินมัดจำของคุณได้ หน่วยงานประกันจะจ่ายเงินให้คุณ",
                ky: "Эгерде сиз Кореянын Турак жай жана шаардык кепилдик корпорациясы (HUG) тарабынан сунушталган чонсе депозитин кайтаруу кепилдигине катталсаңыз, үй ээси депозитиңизди кайтара албаса дагы, кепилдик корпорациясы сизге төлөп берет.",
                km: "ប្រសិនបើអ្នកចុះឈ្មោះសម្រាប់ធានារ៉ាប់រងការសងប្រាក់កក់ Jeonse ដូចដែលផ្តល់ដោយសាជីវកម្មធានាលំនៅឋាន និងទីក្រុងកូរ៉េ (HUG) នោះស្ថាប័នធានានឹងបង់ប្រាក់ឱ្យអ្នក ទោះបីជាម្ចាស់ផ្ទះមិនអាចសងប្រាក់កក់របស់អ្នកវិញក៏ដោយ។",
                id: "Jika Anda mendaftar untuk jaminan pengembalian deposit Jeonse, seperti yang ditawarkan oleh Korea Housing & Urban Guarantee Corporation (HUG), lembaga penjamin akan membayar Anda bahkan jika pemilik tidak dapat mengembalikan deposit Anda.",
                si: "කොරියානු නිවාස හා නාගරික සහතික කිරීමේ සංස්ථාව (HUG) විසින් පිරිනමනු ලබන ජියොන්සේ තැන්පතු ආපසු ගෙවීමේ සහතිකයක් සඳහා ඔබ ලියාපදිංචි වුවහොත්, නිවාස හිමියාට ඔබේ තැන්පතුව ආපසු ගෙවීමට නොහැකි වුවද, සහතික කිරීමේ ආයතනය ඔබට ගෙවීම සිදු කරනු ඇත.",
                bn: "যদি আপনি কোরিয়া হাউজিং অ্যান্ড আরবান গ্যারান্টি কর্পোরেশন (HUG) দ্বারা প্রদত্ত জিয়নসে ডিপোজিট রিটার্ন গ্যারান্টিতে সাইন আপ করেন, তাহলে বাড়িওয়ালা আপনার ডিপোজিট ফেরত দিতে না পারলেও গ্যারান্টি কর্পোরেশন আপনাকে অর্থ প্রদান করবে।",
                my: "ကိုရီးယား အိမ်ရာနှင့် မြို့ပြအာမခံကော်ပိုရေးရှင်း (HUG) မှ ပေးအပ်သည့် Jeonse အပ်ငွေ ပြန်အမ်းအာမခံကို သင်စာရင်းသွင်းပါက အိမ်ပိုင်ရှင်က သင့်အပ်ငွေကို ပြန်မပေးနိုင်လျှင်ပင် အာမခံကော်ပိုရေးရှင်းက သင့်အား ပေးချေပါမည်။",
                mn: "Хэрэв та Солонгосын Орон сууц, хот байгуулалтын баталгааны корпораци (HUG)-аас санал болгодог Жонсэ барьцаа буцаан олгох баталгаанд бүртгүүлбэл, эзэмшигч таны барьцааг буцаан төлж чадахгүй байсан ч баталгааны корпораци танд төлбөр хийнэ.",
                lo: "ຖ້າທ່ານລົງທະບຽນສໍາລັບການຄໍ້າປະກັນການສົ່ງຄືນເງິນຄໍ້າປະກັນ Jeonse, ເຊັ່ນທີ່ສະເໜີໂດຍບໍລິສັດຄໍ້າປະກັນທີ່ຢູ່ອາໄສ ແລະ ຕົວເມືອງເກົາຫຼີ (HUG), ສະຖາບັນຄໍ້າປະກັນຈະຈ່າຍເງິນໃຫ້ທ່ານເຖິງແມ່ນວ່າເຈົ້າຂອງເຮືອນບໍ່ສາມາດສົ່ງຄືນເງິນຄໍ້າປະກັນຂອງທ່ານໄດ້.",
                tet:
                    "Se ó rejista ba garantia devolusaun depózitu Jeonse ida, hanesan ne'ebé Korea Housing & Urban Guarantee Corporation (HUG) oferese, maski na'in-ba-uma la konsege devolve ó-nia depózitu, instituisaun garantia sei halo pagamentu ba ó.",
                ne: "यदि तपाईंले कोरिया हाउसिङ एण्ड अर्बन ग्यारेन्टी कर्पोरेशन (HUG) द्वारा प्रदान गरिएको जस्तै Jeonse धरौटी फिर्ता ग्यारेन्टीमा दर्ता गर्नुभयो भने, घरधनीले तपाईंको धरौटी फिर्ता गर्न नसके पनि ग्यारेन्टी संस्थाले तपाईंलाई भुक्तानी गर्नेछ।",
                zh: '如果投保住宅都市保证公社(HUG)等机构提供的全税押金返还保证，即使房东无法退还押金，也会由担保机构代为支付。',
                vi: 'Nếu tham gia bảo lãnh hoàn trả tiền đặt cọc Jeonse của Tổng công ty Bảo lãnh Nhà ở và Đô thị Hàn Quốc (HUG) và các tổ chức khác, ngay cả khi chủ nhà không thể hoàn trả, tổ chức bảo lãnh sẽ chi trả thay.',
                uz: "Agar siz Korea Housing & Urban Guarantee Corporation (HUG) tomonidan taklif qilingan kabi Jeonse depozitini qaytarish kafolatiga yozilsangiz, uy egasi depozitingizni qaytara olmasa ham, kafolat muassasasi sizga toʻlaydi.",
              ),
              L10nText(
                ko: '가입은 계약 초기에 가능하므로 계약과 동시에 알아보는 것이 안전합니다.',
                en: 'Enrollment is only possible early in the lease term, so it is safest to look into it as soon as you sign the contract.',
                tr: "Kayıt sadece kira süresinin başında mümkündür, bu nedenle sözleşmeyi imzaladıktan hemen sonra araştırmanız en güvenlisidir.",
                tg: "Бақайдгирӣ танҳо дар оғози мӯҳлати иҷора имконпазир аст, аз ин рӯ бехатартарин аст, ки фавран пас аз имзои шартнома таҳқиқ кунед.",
                fil:
                    "Ang pagpaparehistro ay posible lamang sa simula ng panahon ng pag-upa, kaya pinakaligtas na magsaliksik kaagad pagkatapos pumirma sa kontrata.",
                ur: "رجسٹریشن صرف کرایہ کی مدت کے آغاز میں ممکن ہے، لہذا معاہدے پر دستخط کرنے کے فوراً بعد تحقیق کرنا سب سے محفوظ ہے۔",
                th: "การลงทะเบียนสามารถทำได้เฉพาะในช่วงเริ่มต้นของระยะเวลาเช่าเท่านั้น ดังนั้นจึงปลอดภัยที่สุดที่จะตรวจสอบทันทีหลังจากลงนามในสัญญา",
                ky: "Каттоо ижара мөөнөтүнүн башында гана мүмкүн, андыктан келишимге кол койгондон кийин дароо изилдөө жүргүзүү эң коопсуз.",
                km: "ការចុះឈ្មោះអាចធ្វើទៅបានតែនៅដើមរយៈពេលជួលប៉ុណ្ណោះ ដូច្នេះវាមានសុវត្ថិភាពបំផុតក្នុងការស្រាវជ្រាវភ្លាមៗបន្ទាប់ពីចុះហត្ថលេខាលើកិច្ចសន្យា។",
                id: "Pendaftaran hanya dimungkinkan pada awal masa sewa, jadi yang paling aman adalah menanyakannya segera setelah Anda menandatangani kontrak.",
                si: "ලියාපදිංචිය කළ හැක්කේ බදු කාලය ආරම්භයේදී පමණි, එබැවින් ගිවිසුම අත්සන් කළ වහාම විමර්ශනය කිරීම වඩාත් ආරක්ෂිත වේ.",
                bn: "রেজিস্ট্রেশন শুধুমাত্র ভাড়ার সময়কালের শুরুতে সম্ভব, তাই চুক্তি স্বাক্ষর করার পরপরই এটি নিয়ে গবেষণা করা সবচেয়ে নিরাপদ।",
                my: "စာရင်းသွင်းခြင်းကို ငှားရမ်းမှုကာလအစတွင်သာ ပြုလုပ်နိုင်သောကြောင့် စာချုပ်ချုပ်ဆိုပြီးသည်နှင့် ချက်ချင်းစုံစမ်းခြင်းသည် အလုံခြုံဆုံးဖြစ်သည်။",
                mn: "Бүртгэл нь зөвхөн түрээсийн хугацааны эхэнд боломжтой тул гэрээнд гарын үсэг зурмагц шууд судлах нь хамгийн аюулгүй юм.",
                lo: "ການລົງທະບຽນແມ່ນສາມາດເຮັດໄດ້ພຽງແຕ່ໃນຕອນຕົ້ນຂອງໄລຍະເວລາເຊົ່າເທົ່ານັ້ນ, ດັ່ງນັ້ນ, ມັນປອດໄພທີ່ສຸດທີ່ຈະສອບຖາມທັນທີຫຼັງຈາກເຊັນສັນຍາ.",
                tet:
                    "Rejistu posivel de'it iha inísiu períodu arrendamentu nian, tanba ne'e, seguru liu atu halo investigasaun kedas depois asina kontratu.",
                ne: "दर्ता भाडा अवधिको सुरुमा मात्र सम्भव छ, त्यसैले सम्झौतामा हस्ताक्षर गरेपछि तुरुन्तै अनुसन्धान गर्नु सबैभन्दा सुरक्षित हुन्छ।",
                zh: '由于只能在合同初期投保，建议在签约的同时立即咨询办理，以确保安全。',
                vi: 'Việc tham gia chỉ có thể thực hiện vào giai đoạn đầu hợp đồng, vì vậy nên tìm hiểu ngay khi ký hợp đồng để đảm bảo an toàn.',
                uz: "Roʻyxatdan oʻtish faqat ijara muddatining boshida mumkin, shuning uchun shartnomani imzolashingiz bilanoq uni oʻrganib chiqish eng xavfsizdir.",
              ),
            ],
