      BookPage(
        title: L10nText(
          ko: '계약 종료와 보증금 미반환 대응',
          en: 'Lease Termination and Responding to an Unreturned Deposit',
          tr: "Kira Sözleşmesinin Feshi ve İade Edilmeyen Depozitoya Yanıt Verme",
          tg: "Қатъи шартномаи иҷора ва вокуниш ба пасандози баргардониданашуда",
          fil:
              "Pagtatapos ng Kontrata sa Pag-upa at Pagtugon sa Hindi Naibalik na Deposito",
          ur: "کرایہ کے معاہدے کی منسوخی اور ناقابل واپسی ڈپازٹ کا جواب دینا",
          th: "การยกเลิกสัญญาเช่าและการตอบสนองต่อเงินมัดจำที่ไม่ได้รับคืน",
