          km: "ការបញ្ចប់កិច្ចសន្យាជួល និងការឆ្លើយតបទៅនឹងប្រាក់កក់ដែលមិនបានសងវិញ",
          id: "Pengakhiran Kontrak Sewa dan Menanggapi Deposit yang Tidak Dikembalikan",
          si: "බදු ගිවිසුම අවසන් කිරීම සහ ආපසු නොගෙවූ තැන්පතු සඳහා ප්‍රතිචාර දැක්වීම",
          bn: "ভাড়ার চুক্তি বাতিল এবং ফেরত না পাওয়া আমানতের প্রতিক্রিয়া",
          my: "အိမ်ငှားစာချုပ် ဖျက်သိမ်းခြင်းနှင့် ပြန်မအမ်းသော အပ်ငွေကို တုံ့ပြန်ခြင်း",
          mn: "Түрээсийн гэрээг цуцлах, буцаан олгогдоогүй барьцаанд хариу өгөх",
          lo: "ການຍົກເລີກສັນຍາເຊົ່າ ແລະ ການຕອບສະໜອງຕໍ່ເງິນຄໍ້າປະກັນທີ່ບໍ່ໄດ້ຮັບຄືນ",
          tet:
              "Terminasaun Kontratu Arrendamentu no Responde ba Depózitu Ne'ebé La Devolve",
          ne: "भाडा सम्झौताको समाप्ति र फिर्ता नगरिएको धरौटीमा प्रतिक्रिया दिने",
          zh: '合同终止与押金未返还的应对措施',
          vi: 'Kết thúc hợp đồng và cách xử lý khi không được hoàn trả tiền đặt cọc',
          uz: "Ijara shartnomasini bekor qilish va qaytarilmagan depozitga javob berish",
        ),
        summary: L10nText(
          ko: '계약이 끝났는데 보증금을 돌려받지 못하면 임차권등기명령을 먼저 검토하고, 전세사기 피해라면 전담 지원기관에 문의합니다.',
          en: 'If your lease has ended but you have not gotten your deposit back, first consider an order for registration of the lease right, and if you have been a victim of Jeonse fraud, contact the dedicated support agency.',
          tr: "Kiralama süreniz sona erdi ancak depozitonuzu geri alamadıysanız, öncelikle kira hakkının tescili için bir talimatı düşünün ve eğer Jeonse dolandırıcılığının kurbanı olduysanız, özel destek ajansıyla iletişime geçin.",
          tg: "Агар мӯҳлати иҷораи шумо ба охир расида бошад, аммо шумо пасандози худро нагирифта бошед, аввал фармоишро барои бақайдгирии ҳуқуқи иҷора баррасӣ кунед ва агар шумо қурбонии қаллобии Ҷонсе шуда бошед, бо агентии дастгирии махсус тамос гиред.",
          fil:
              "Kung natapos na ang iyong panahon ng pag-upa ngunit hindi mo pa nakukuha ang iyong deposito, isaalang-alang muna ang isang utos para sa pagpaparehistro ng karapatan sa pag-upa, at kung ikaw ay biktima ng pandaraya sa Jeonse, makipag-ugnayan sa ahensya ng espesyal na suporta.",
          ur: "اگر آپ کی کرایہ داری کی مدت ختم ہو گئی ہے لیکن آپ کو اپنا ڈپازٹ واپس نہیں ملا ہے، تو پہلے کرایہ کے حق کی رجسٹریشن کے لیے ہدایت پر غور کریں، اور اگر آپ جیونسی فراڈ کا شکار ہوئے ہیں، تو خصوصی معاونت ایجنسی سے رابطہ کریں۔",
          th: "หากระยะเวลาเช่าของคุณสิ้นสุดลงแต่คุณยังไม่ได้รับเงินมัดจำคืน ให้พิจารณาคำสั่งให้จดทะเบียนสิทธิการเช่าก่อน และหากคุณตกเป็นเหยื่อของการฉ้อโกง Jeonse ให้ติดต่อหน่วยงานสนับสนุนพิเศษ",
          ky: "Ижара мөөнөтүңүз аяктап, бирок депозитиңизди кайтарып ала албасаңыз, адегенде ижара укугун каттоо боюнча көрсөтмөнү карап чыгыңыз, эгерде сиз чонсе алдамчылыгынын курмандыгы болсоңуз, атайын колдоо агенттигине кайрылыңыз.",
          km: "ប្រសិនបើរយៈពេលជួលរបស់អ្នកបានបញ្ចប់ ប៉ុន្តែអ្នកមិនទាន់ទទួលបានប្រាក់កក់របស់អ្នកមកវិញទេ សូមពិចារណាដំបូងអំពីបទបញ្ជាសម្រាប់ការចុះបញ្ជីសិទ្ធិជួល ហើយប្រសិនបើអ្នកជាជនរងគ្រោះនៃការបោកប្រាស់ Jeonse សូមទាក់ទងភ្នាក់ងារគាំទ្រពិសេស។",
          id: "Jika masa sewa Anda telah berakhir tetapi Anda belum menerima kembali deposit Anda, pertimbangkan terlebih dahulu perintah pendaftaran hak sewa, dan jika Anda menjadi korban penipuan Jeonse, hubungi agen dukungan khusus.",
          si: "ඔබේ බදු කාලය අවසන් වී ඇතත් ඔබට ඔබේ තැන්පතුව ආපසු ලබා ගැනීමට නොහැකි වී ඇත්නම්, පළමුව බදු අයිතිය ලියාපදිංචි කිරීම සඳහා නියෝගයක් සලකා බලන්න, ඔබ ජියොන්සේ වංචාවක ගොදුරක් වී ඇත්නම්, විශේෂ සහාය නියෝජිතායතනය අමතන්න.",
          bn: "যদি আপনার ভাড়ার সময়কাল শেষ হয়ে যায় কিন্তু আপনি আপনার আমানত ফেরত না পান, তাহলে প্রথমে ভাড়ার অধিকার নিবন্ধনের জন্য একটি আদেশ বিবেচনা করুন এবং যদি আপনি জিয়নসে জালিয়াতির শিকার হন, তাহলে বিশেষ সহায়তা সংস্থার সাথে যোগাযোগ করুন।",
          my: "သင်၏ ငှားရမ်းမှုကာလ ကုန်ဆုံးသွားသော်လည်း သင့်အပ်ငွေကို ပြန်မရသေးပါက ဦးစွာ အိမ်ငှားပိုင်ခွင့် မှတ်ပုံတင်ရန် ညွှန်ကြားချက်ကို စဉ်းစားပြီး Jeonse လိမ်လည်မှု၏ သားကောင်ဖြစ်ပါက အထူးပံ့ပိုးကူညီရေးအေဂျင်စီကို ဆက်သွယ်ပါ။",
          mn: "Хэрэв таны түрээсийн хугацаа дууссан боловч барьцаагаа буцаан авч чадаагүй бол эхлээд түрээсийн эрхийг бүртгүүлэх тухай зааврыг авч үзээд, хэрэв та Жонсэ луйврын хохирогч болсон бол тусгай дэмжлэгийн агентлагтай холбогдоорой.",
          lo: "ຖ້າໄລຍະເວລາເຊົ່າຂອງທ່ານສິ້ນສຸດລົງແລ້ວ ແຕ່ທ່ານຍັງບໍ່ໄດ້ຮັບເງິນຄໍ້າປະກັນຄືນ, ໃຫ້ພິຈາລະນາຄໍາສັ່ງລົງທະບຽນສິດທິການເຊົ່າກ່ອນ, ແລະ ຖ້າທ່ານຕົກເປັນເຫຍື່ອຂອງການສໍ້ໂກງ Jeonse, ໃຫ້ຕິດຕໍ່ອົງການຊ່ວຍເຫຼືອພິເສດ.",
          tet:
              "Se ó-nia períodu arrendamentu hotu ona maibé ó seidauk simu fali ó-nia depózitu, primeiru, konsidera orden ida ba rejistu direitu arrendamentu, no se ó sai vítima ba fraude Jeonse, kontaktu ajénsia apoiu espesiál.",
          ne: "यदि तपाईंको भाडा अवधि समाप्त भयो तर तपाईंले आफ्नो धरौटी फिर्ता पाउनुभएको छैन भने, पहिले भाडा अधिकारको दर्ताको लागि आदेश विचार गर्नुहोस्, र यदि तपाईं Jeonse ठगीको शिकार हुनुभएको छ भने, विशेष सहयोग एजेन्सीसँग सम्पर्क गर्नुहोस्।",
          zh: '如果合同已到期但押金尚未退还，请先考虑申请租赁权登记命令；如果是全税诈骗受害者，请联系专门的支援机构。',
          vi: 'Nếu hợp đồng đã kết thúc nhưng chưa nhận lại được tiền đặt cọc, trước tiên hãy xem xét lệnh đăng ký quyền thuê nhà; nếu là nạn nhân lừa đảo Jeonse, hãy liên hệ cơ quan hỗ trợ chuyên trách.',
          uz: "Agar ijara shartnomangiz tugagan boʻlsa, lekin depozitingizni qaytarib olmagan boʻlsangiz, avval ijara huquqini roʻyxatdan oʻtkazish buyrugʻini koʻrib chiqing va agar siz Jeonse firibgarligining qurboni boʻlgan boʻlsangiz, maxsus yordam agentligiga murojaat qiling.",
        ),
        blocks: [
          ContentBlock(
            title: L10nText(
              ko: '임차권등기명령',
              en: 'Order for Registration of the Lease Right',
              tr: "Kira Hakkının Tescili Emri",
              tg: "Фармоиш барои бақайдгирии ҳуқуқи иҷора",
              fil: "Utos para sa Pagpaparehistro ng Karapatan sa Pag-upa",
              ur: "کرایہ کے حق کی رجسٹریشن کا حکم",
              th: "คำสั่งให้จดทะเบียนสิทธิการเช่า",
              ky: "Ижара укугун каттоо буйругу",
              km: "បទបញ្ជាចុះបញ្ជីសិទ្ធិជួល",
              id: "Perintah Pendaftaran Hak Sewa",
              si: "බදු අයිතිය ලියාපදිංචි කිරීමේ නියෝගය",
              bn: "ভাড়ার অধিকার নিবন্ধনের আদেশ",
              my: "အိမ်ငှားပိုင်ခွင့် မှတ်ပုံတင်ရန် အမိန့်",
              mn: "Түрээсийн эрхийг бүртгүүлэх тушаал",
              lo: "ຄໍາສັ່ງລົງທະບຽນສິດທິການເຊົ່າ",
              tet: "Orden Rejistu Direitu Arrendamentu",
              ne: "भाडा अधिकारको दर्ताको आदेश",
              zh: '租赁权登记命令',
              vi: 'Lệnh đăng ký quyền thuê nhà',
              uz: "Ijara huquqini roʻyxatdan oʻtkazish buyrugʻi",
            ),
            bullets: [
              L10nText(
                ko: '이사를 나가야 하는데 보증금을 못 받았다면, 이사 전에 임차권등기명령을 신청해 대항력·우선변제권을 유지한 채 이사할 수 있습니다.',
                en: 'If you need to move out but have not received your deposit, you can apply for an order for registration of the lease right before moving, allowing you to move out while retaining your right of opposability and priority repayment right.',
                tr: "Taşınmanız gerekiyorsa ancak depozitonuzu almadıysanız, taşınmadan önce kira hakkının tescili için başvuruda bulunabilirsiniz; bu, itiraz hakkınızı ve öncelikli geri ödeme hakkınızı koruyarak taşınmanıza olanak tanır.",
                tg: "Агар шумо бояд кӯчед, аммо пасандози худро нагирифта бошед, шумо метавонед пеш аз кӯчидан барои бақайдгирии ҳуқуқи иҷора муроҷиат кунед; ин ба шумо имкон медиҳад, ки бо ҳифзи ҳуқуқи эътироз ва ҳуқуқи баргардонидани афзалиятноки худ кӯчед.",
                fil:
                    "Kung kailangan mong lumipat ngunit hindi mo pa natatanggap ang iyong deposito, maaari kang mag-apply para sa pagpaparehistro ng karapatan sa pag-upa bago lumipat; pinapayagan ka nitong lumipat habang pinapanatili ang iyong karapatan sa pagtutol at karapatan sa prayoridad na pagbabayad.",
                ur: "اگر آپ کو منتقل ہونے کی ضرورت ہے لیکن آپ کو اپنا ڈپازٹ نہیں ملا ہے، تو آپ منتقل ہونے سے پہلے کرایہ کے حق کی رجسٹریشن کے لیے درخواست دے سکتے ہیں؛ یہ آپ کو اپنے اعتراض کے حق اور ترجیحی واپسی کے حق کو برقرار رکھتے ہوئے منتقل ہونے کی اجازت دیتا ہے۔",
                th: "หากคุณจำเป็นต้องย้ายออกแต่ยังไม่ได้รับเงินมัดจำ คุณสามารถยื่นคำขอจดทะเบียนสิทธิการเช่าก่อนย้ายออก ซึ่งจะช่วยให้คุณย้ายออกได้โดยยังคงรักษาสิทธิในการคัดค้านและสิทธิในการได้รับคืนก่อน",
                ky: "Эгерде сиз көчүп кетишиңиз керек болсо, бирок депозитиңизди ала элек болсоңуз, көчүп кетүүдөн мурун ижара укугун каттоо үчүн кайрылсаңыз болот; бул сиздин каршы чыгуу укугуңузду жана артыкчылыктуу кайтарып алуу укугуңузду сактап калуу менен көчүп кетүүгө мүмкүндүк берет.",
                km: "ប្រសិនបើអ្នកត្រូវផ្លាស់ប្តូរទីលំនៅ ប៉ុន្តែមិនទាន់ទទួលបានប្រាក់កក់របស់អ្នកទេ អ្នកអាចដាក់ពាក្យសុំចុះបញ្ជីសិទ្ធិជួលមុនពេលផ្លាស់ប្តូរទីលំនៅ។ នេះអនុញ្ញាតឱ្យអ្នកផ្លាស់ប្តូរទីលំនៅដោយរក្សាសិទ្ធិជំទាស់ និងសិទ្ធិទទួលបានការសងប្រាក់វិញជាអាទិភាពរបស់អ្នក។",
                id: "Jika Anda perlu pindah tetapi belum menerima deposit Anda, Anda dapat mengajukan pendaftaran hak sewa sebelum pindah; ini memungkinkan Anda untuk pindah sambil mempertahankan hak untuk menentang dan hak pembayaran prioritas Anda.",
                si: "ඔබට පදිංචිය වෙනස් කිරීමට අවශ්‍ය නමුත් ඔබේ තැන්පතුව ලැබී නොමැති නම්, ඔබට පදිංචිය වෙනස් කිරීමට පෙර බදු අයිතිය ලියාපදිංචි කිරීම සඳහා අයදුම් කළ හැකිය; මෙය ඔබේ විරෝධතා දැක්වීමේ අයිතිය සහ ප්‍රමුඛතා ප්‍රතිපූරණය කිරීමේ අයිතිය පවත්වා ගනිමින් පදිංචිය වෙනස් කිරීමට ඔබට ඉඩ සලසයි.",
                bn: "যদি আপনাকে স্থানান্তরিত হতে হয় কিন্তু আপনার আমানত না পেয়ে থাকেন, তাহলে আপনি স্থানান্তরের আগে ভাড়ার অধিকার নিবন্ধনের জন্য আবেদন করতে পারেন; এটি আপনাকে আপনার প্রতিবাদের অধিকার এবং অগ্রাধিকারমূলক পরিশোধের অধিকার বজায় রেখে স্থানান্তরিত হতে দেয়।",
                my: "သင်ပြောင်းရွှေ့ရန် လိုအပ်သော်လည်း သင့်အပ်ငွေကို မရရှိသေးပါက ပြောင်းရွှေ့မလာမီ အိမ်ငှားပိုင်ခွင့် မှတ်ပုံတင်ရန် လျှောက်ထားနိုင်ပြီး ၎င်းသည် သင့်ကန့်ကွက်ပိုင်ခွင့်နှင့် ဦးစားပေးပြန်အမ်းငွေရပိုင်ခွင့်ကို ထိန်းသိမ်းထားစဉ် ပြောင်းရွှေ့ရန် ခွင့်ပြုပါသည်။",
                mn: "Хэрэв та нүүх шаардлагатай боловч барьцаагаа аваагүй бол нүүхээсээ өмнө түрээсийн эрхийг бүртгүүлэх хүсэлт гаргаж болно; энэ нь таны эсэргүүцэх эрх болон тэргүүн ээлжинд буцаан авах эрхийг хадгалан нүүх боломжийг олгоно.",
                lo: "ຖ້າທ່ານຈໍາເປັນຕ້ອງຍ້າຍອອກ ແຕ່ຍັງບໍ່ໄດ້ຮັບເງິນຄໍ້າປະກັນຄືນ, ທ່ານສາມາດສະໝັກຂໍລົງທະບຽນສິດທິການເຊົ່າກ່ອນຍ້າຍອອກ; ນີ້ຈະຊ່ວຍໃຫ້ທ່ານສາມາດຍ້າຍອອກໄດ້ໃນຂະນະທີ່ຍັງຮັກສາສິດທິໃນການຄັດຄ້ານ ແລະ ສິດທິໃນການໄດ້ຮັບເງິນຄືນກ່ອນ.",
                tet:
                    "Se ó presiza muda maibé seidauk simu ó-nia depózitu, ó bele aplika ba rejistu direitu arrendamentu antes muda; ida ne'e permite ó atu muda, hodi proteje ó-nia direitu atu opozisaun no direitu ba pagamentu uluk.",
                ne: "यदि तपाईंलाई सर्नु आवश्यक छ तर तपाईंले आफ्नो धरौटी प्राप्त गर्नुभएको छैन भने, तपाईं सर्नु अघि भाडा अधिकारको दर्ताको लागि आवेदन दिन सक्नुहुन्छ; यसले तपाईंलाई आपत्ति गर्ने अधिकार र प्राथमिकताका साथ फिर्ता पाउने अधिकार सुरक्षित राख्दै सर्न अनुमति दिन्छ।",
                zh: '如果需要搬走但尚未收到押金，可以在搬家前申请租赁权登记命令，从而在保留对抗力和优先受偿权的前提下搬离。',
                vi: 'Nếu phải chuyển đi nhưng chưa nhận được tiền đặt cọc, bạn có thể đăng ký lệnh đăng ký quyền thuê nhà trước khi chuyển đi để chuyển nhà trong khi vẫn duy trì hiệu lực đối kháng và quyền được ưu tiên hoàn trả.',
                uz: "Agar siz koʻchib ketishingiz kerak boʻlsa, lekin depozitingizni olmagan boʻlsangiz, koʻchib oʻtishdan oldin ijara huquqini roʻyxatdan oʻtkazish buyrugʻini soʻrashingiz mumkin, bu sizga qarshi qoʻyish huquqi va ustuvor toʻlov huquqini saqlab qolgan holda koʻchib ketish imkonini beradi.",
              ),
            ],
