                uz: "Infratuzilma nuqsonlari (sizib chiqish, isitish tizimining buzilishi va h.k.) boʻlsa, yozma ravishda (SMS yoki KakaoTalk) darhol uy egasiga xabar bering, bu yozuvni saqlashga yordam beradi.",
