                my: "အချို့သော အငှားစာချုပ်များတွင် မီးအာမခံ မှတ်ပုံတင်ခြင်းကို မဖြစ်မနေ လိုက်နာရမည့် အထူးပြဋ္ဌာန်းချက်အဖြစ် ထည့်သွင်းထားသောကြောင့် သင်၏စာချုပ်ကို စစ်ဆေးပါ။",
