          ContentBlock(
            title: L10nText(
              ko: '공동주택 생활수칙',
              en: 'Rules for Living in Multi-Unit Housing',
              tr: "Çok Katlı Konutlarda Yaşam Kuralları",
              tg: "Қоидаҳои зиндагӣ дар манзилҳои бисёрошёна",
              fil: "Mga Panuntunan sa Pamumuhay sa Multi-Story Residences",
