              km: "ច្បាប់នៃការរស់នៅក្នុងលំនៅដ្ឋានពហុជាន់",
              id: "Aturan Hidup di Perumahan Bertingkat",
              si: "බහු මහල් නිවාසවල ජීවත් වීමේ නීති",
              bn: "বহুতল আবাসনে বসবাসের নিয়মাবলী",
              my: "အထပ်မြင့် အဆောက်အအုံများတွင် နေထိုင်ခြင်းဆိုင်ရာ စည်းမျဉ်းများ",
              mn: "Олон Давхар Орон Сууцанд Амьдрах Дүрэм",
