              tet: "Regra moris nian iha Rezidénsia Andar Barak",
              ne: "बहुमंजिला आवासमा बस्ने नियमहरू",
              zh: '集体住宅生活守则',
              vi: 'Quy tắc sinh hoạt tại nhà chung cư',
              uz: "Koʻp qavatli uylarda yashash qoidalari",
            ),
            bullets: [
              L10nText(
                ko: '소음·쓰레기 배출 요일 등 공동주택 관리규약을 입주 초기에 확인해두면 이웃 갈등을 줄일 수 있습니다.',
                en: 'Checking the management rules of your multi-unit building — such as noise policies and designated trash disposal days — early on can help reduce conflicts with neighbors.',
                tr: "Çok katlı binanızın yönetim kurallarını — gürültü politikaları ve belirlenmiş çöp atma günleri gibi — önceden kontrol etmek, komşularla yaşanabilecek anlaşmazlıkları azaltmaya yardımcı olabilir.",
                tg: "Пешакӣ тафтиш кардани қоидаҳои идоракунии бинои бисёрошёнаи шумо — ба монанди сиёсатҳои садо ва рӯзҳои муайяншудаи партов — метавонад ба кам кардани ихтилофот бо ҳамсоягон мусоидат кунад.",
                fil:
                    "Ang pagsusuri nang maaga sa mga panuntunan sa pamamahala ng iyong multi-story building — tulad ng mga patakaran sa ingay at itinakdang araw ng pagtatapon ng basura — ay makakatulong na mabawasan ang mga hindi pagkakaunawaan sa mga kapitbahay.",
                ur: "اپنی کثیر المنزلہ عمارت کے انتظامی قواعد — جیسے شور کی پالیسیاں اور کچرا پھینکنے کے مقررہ دن — کو پہلے سے جانچنا پڑوسیوں کے ساتھ تنازعات کو کم کرنے میں مدد کر سکتا ہے۔",
                th: "การตรวจสอบกฎการจัดการอาคารหลายชั้นของคุณล่วงหน้า เช่น นโยบายเรื่องเสียงดังและวันทิ้งขยะที่กำหนด สามารถช่วยลดความขัดแย้งกับเพื่อนบ้านได้",
                ky: "Көп кабаттуу имаратыңыздын башкаруу эрежелерин — ызы-чуу саясаты жана таштанды таштоо күндөрү сыяктуу — алдын ала текшерүү кошуналар менен болгон пикир келишпестиктерди азайтууга жардам берет.",
                km: "ការពិនិត្យមើលច្បាប់គ្រប់គ្រងអគារពហុជាន់របស់អ្នកជាមុន — ដូចជានយោបាយសំឡេងរំខាន និងថ្ងៃកំណត់ចោលសំរាម — អាចជួយកាត់បន្ថយជម្លោះជាមួយអ្នកជិតខាង។",
                id: "Memeriksa aturan manajemen gedung bertingkat Anda — seperti kebijakan kebisingan dan hari pembuangan sampah yang ditentukan — sebelumnya dapat membantu mengurangi perselisihan dengan tetangga.",
                si: "ඔබේ බහු මහල් ගොඩනැගිල්ලේ කළමනාකරණ නීති — ශබ්ද ප්‍රතිපත්ති සහ නියමිත කුණු බැහැර කිරීමේ දින වැනි — කල්තියා පරීක්ෂා කිරීමෙන් අසල්වැසියන් සමඟ ඇති විය හැකි ආරවුල් අඩු කර ගත හැක.",
                bn: "আপনার বহুতল ভবনের ব্যবস্থাপনা নিয়মাবলী — যেমন শব্দ নীতি এবং নির্দিষ্ট আবর্জনা ফেলার দিন — আগে থেকে পরীক্ষা করা প্রতিবেশীদের সাথে সম্ভাব্য বিরোধ কমাতে সাহায্য করতে পারে।",
                my: "ဆူညံသံဆိုင်ရာ မူဝါဒများနှင့် သတ်မှတ်ထားသော အမှိုက်စွန့်ပစ်သည့်နေ့များကဲ့သို့သော သင်၏ အထပ်မြင့်အဆောက်အအုံ၏ စီမံခန့်ခွဲမှုစည်းမျဉ်းများကို ကြိုတင်စစ်ဆေးခြင်းသည် အိမ်နီးချင်းများနှင့် ဖြစ်ပေါ်လာနိုင်သည့် ပဋိပက္ခများကို လျှော့ချရန် ကူညီပေးနိုင်ပါသည်။",
                mn: "Олон давхар барилгынхаа удирдлагын дүрмийг — дуу чимээний бодлого, хог хаях тогтоосон өдрүүд гэх мэт — урьдчилан шалгах нь хөршүүдтэй үүсэх маргааныг багасгахад тусална.",
                lo: "ການກວດສອບກົດລະບຽບການຄຸ້ມຄອງຂອງອາຄານຫຼາຍຊັ້ນຂອງທ່ານລ່ວງໜ້າ—ເຊັ່ນ: ນະໂຍບາຍສຽງດັງ ແລະ ວັນກຳນົດຖິ້ມຂີ້ເຫຍື້ອ—ສາມາດຊ່ວຍຫຼຸດຜ່ອນຂໍ້ຂັດແຍ່ງທີ່ອາດຈະເກີີດຂຶ້ນກັບເພື່ອນບ້ານໄດ້.",
                tet:
                    "Verifika uluk regra jestaun ba ó-nia edifísiu andar barak nian (hanesan polítika barullu no loron sira ne'ebé determina ona ba soe lixu) bele ajuda atu hamenus konflitu ho viziñu sira.",
                ne: "आफ्नो बहुमंजिला भवनको व्यवस्थापन नियमहरू — जस्तै आवाज सम्बन्धी नीतिहरू र तोकिएको फोहोर फाल्ने दिनहरू — अग्रिम जाँच गर्दा छिमेकीहरूसँग हुन सक्ने विवादहरू कम गर्न मद्दत गर्न सक्छ।",
                zh: '入住初期了解集体住宅的管理规约（如噪音规定、垃圾投放日等），有助于减少邻里矛盾。',
                vi: 'Nếu tìm hiểu quy định quản lý chung cư (như tiếng ồn, ngày đổ rác quy định) ngay từ đầu, bạn có thể giảm bớt xung đột với hàng xóm.',
                uz: "Koʻp qavatli binoning boshqaruv qoidalarini — masalan, shovqin siyosati va chiqindilarni tashlash kunlarini — oldindan tekshirish qoʻshnilar bilan mojarolarni kamaytirishga yordam beradi.",
