        summary: L10nText(
          ko: '티머니·캐시비 등 선불 교통카드는 편의점에서 바로 구매할 수 있고, 외국인등록번호가 있으면 K-패스 같은 환급형 카드도 만들 수 있습니다.',
          en: 'Prepaid transit cards such as T-money and Cashbee can be bought directly at convenience stores, and if you have an Alien Registration Number, you can also get a refund-type card like K-Pass.',
          tr: "T-money ve Cashbee gibi ön ödemeli toplu taşıma kartları doğrudan marketlerden satın alınabilir ve Yabancı Kayıt Numaranız varsa, K-Pass gibi iade özellikli bir kart da edinebilirsiniz.",
          tg: "Кортҳои нақлиёти ҷамъиятии пешпардохт, ба монанди T-money ва Cashbee, метавонанд мустақиман аз мағозаҳои хӯрокворӣ харидорӣ шаванд ва агар шумо рақами бақайдгирии хориҷӣ дошта бошед, шумо метавонед корти дорои хусусияти баргардонидани маблағ, ба монанди K-Pass, низ гиред.",
          fil:
              "Ang mga prepaid public transportation card tulad ng T-money at Cashbee ay maaaring bilhin nang direkta sa mga convenience store, at kung mayroon kang Foreigner Registration Number, maaari ka ring kumuha ng card na may feature na refund tulad ng K-Pass.",
          ur: "پری پیڈ پبلک ٹرانسپورٹ کارڈز جیسے T-money اور Cashbee براہ راست سہولت اسٹورز سے خریدے جا سکتے ہیں، اور اگر آپ کے پاس غیر ملکی رجسٹریشن نمبر ہے، تو آپ K-Pass جیسا ریفنڈ فیچر والا کارڈ بھی حاصل کر سکتے ہیں۔",
          th: "บัตรโดยสารสาธารณะแบบเติมเงิน เช่น T-money และ Cashbee สามารถซื้อได้โดยตรงจากร้านสะดวกซื้อ และหากคุณมีหมายเลขทะเบียนคนต่างด้าว คุณยังสามารถขอรับบัตรที่มีคุณสมบัติคืนเงินได้ เช่น K-Pass",
          ky: "T-money жана Cashbee сыяктуу алдын ала төлөнүүчү коомдук транспорт карталарын дүкөндөрдөн түз сатып алса болот, эгерде сизде Чет элдик каттоо номериңиз болсо, K-Pass сыяктуу кайтаруу функциясы бар картаны да ала аласыз.",
          km: "ប័ណ្ណដឹកជញ្ជូនសាធារណៈបង់ប្រាក់ជាមុន ដូចជា T-money និង Cashbee អាចទិញបានដោយផ្ទាល់ពីហាងងាយស្រួល ហើយប្រសិនបើអ្នកមានលេខចុះឈ្មោះជនបរទេស អ្នកក៏អាចទទួលបានប័ណ្ណដែលមានមុខងារសងប្រាក់វិញ ដូចជា K-Pass ផងដែរ។",
          id: "Kartu transportasi umum prabayar seperti T-money dan Cashbee dapat dibeli langsung di toko serba ada, dan jika Anda memiliki Nomor Pendaftaran Asing, Anda juga bisa mendapatkan kartu dengan fitur pengembalian dana seperti K-Pass.",
          si: "T-money සහ Cashbee වැනි පෙරගෙවුම් පොදු ප්‍රවාහන කාඩ්පත් පහසුවෙන් වෙළඳසැල් වලින් මිලදී ගත හැකි අතර, ඔබට විදේශික ලියාපදිංචි අංකයක් තිබේ නම්, K-Pass වැනි මුදල් ආපසු ගෙවීමේ විශේෂාංගයක් සහිත කාඩ්පතක් ද ලබා ගත හැක.",
          bn: "T-money এবং Cashbee-এর মতো প্রিপেইড পাবলিক ট্রান্সপোর্ট কার্ড সরাসরি সুবিধার দোকান থেকে কেনা যায় এবং আপনার যদি বিদেশী নিবন্ধন নম্বর থাকে, তাহলে আপনি K-Pass-এর মতো রিফান্ড ফাংশন সহ একটি কার্ডও পেতে পারেন।",
          my: "T-money နှင့် Cashbee ကဲ့သို့သော ကြိုတင်ငွေဖြည့် အများပြည်သူ သယ်ယူပို့ဆောင်ရေးကတ်များကို အဆင်ပြေစတိုးဆိုင်များမှ တိုက်ရိုက်ဝယ်ယူနိုင်ပြီး သင်၏ နိုင်ငံခြားသား မှတ်ပုံတင်နံပါတ်ရှိပါက K-Pass ကဲ့သို့သော ပြန်အမ်းငွေပါရှိသည့် ကတ်ကိုလည်း ရယူနိုင်ပါသည်။",
          mn: "T-money болон Cashbee зэрэг урьдчилсан төлбөрт нийтийн тээврийн картыг дэлгүүрүүдээс шууд худалдан авах боломжтой бөгөөд хэрэв та Гадаад Иргэний Бүртгэлийн Дугаартай бол K-Pass зэрэг буцаан олголттой картыг авах боломжтой.",
          lo: "ບັດໂດຍສານສາທາລະນະແບບເຕີມເງິນເຊັ່ນ T-money ແລະ Cashbee ສາມາດຊື້ໄດ້ໂດຍກົງຈາກຮ້ານສະດວກຊື້, ແລະ ຖ້າທ່ານມີເລກທະບຽນຄົນຕ່າງດ້າວ, ທ່ານຍັງສາມາດໄດ້ຮັບບັດທີ່ມີຄຸນສົມບັດຄືນເງິນເຊັ່ນ K-Pass.",
          tet:
              "Karta transporte públiku pré-pagu hanesan T-money no Cashbee bele sosa diretamente iha supermerkadu sira, no se ó iha Númeru Rejistu Estranjeiru, ó bele hetan mós karta ida ho funsaun reemborsu hanesan K-Pass.",
          ne: "T-money र Cashbee जस्ता प्रिपेड सार्वजनिक यातायात कार्डहरू सिधै सुविधा स्टोरहरूबाट किन्न सकिन्छ, र यदि तपाईंसँग विदेशी दर्ता नम्बर छ भने, तपाईंले K-Pass जस्तो फिर्ता सुविधा भएको कार्ड पनि प्राप्त गर्न सक्नुहुन्छ।",
          zh: '像T-money、Cashbee这样的预付交通卡可以直接在便利店购买；若持有外国人登录号码，还可以办理K-Pass等返还型交通卡。',
          vi: 'Thẻ giao thông trả trước như T-money, Cashbee có thể mua trực tiếp tại cửa hàng tiện lợi, và nếu có số đăng ký người nước ngoài, bạn cũng có thể làm thẻ hoàn tiền như K-Pass.',
          uz: "T-money va Cashbee kabi oldindan toʻlangan tranzit kartalarini doʻkonlardan toʻgʻridan-toʻgʻri sotib olish mumkin, agar sizda chet el fuqarosi roʻyxatga olish raqami boʻlsa, K-Pass kabi qaytariladigan kartani ham olishingiz mumkin.",
        ),
