            bullets: [
              L10nText(
                ko: '일부 지자체는 K-패스를 기반으로 추가 환급 혜택을 주는 자체 카드를 운영합니다(예: 경기패스, 인천 I-패스 등).',
                en: 'Some local governments operate their own cards, built on top of K-Pass, that offer additional refund benefits (e.g., Gyeonggi Pass, Incheon I-Pass).',
                tr: "Bazı yerel yönetimler, K-Pass üzerine inşa edilmiş, ek iade avantajları sunan kendi kartlarını işletmektedir (örn. Gyeonggi Pass, Incheon I-Pass).",
                tg: "Баъзе ҳукуматҳои маҳаллӣ кортҳои худро, ки дар асоси K-Pass сохта шудаанд, бо имтиёзҳои иловагии баргардонидани маблағ идора мекунанд (масалан, Gyeonggi Pass, Incheon I-Pass).",
                fil:
                    "Ang ilang lokal na pamahalaan ay nagpapatakbo ng sarili nilang mga card na binuo sa K-Pass, na nag-aalok ng karagdagang benepisyo sa refund (hal. Gyeonggi Pass, Incheon I-Pass).",
                ur: "کچھ مقامی حکومتیں K-Pass پر مبنی اپنے کارڈز چلاتی ہیں جو اضافی ریفنڈ فوائد پیش کرتے ہیں (مثلاً Gyeonggi Pass, Incheon I-Pass)۔",
                th: "รัฐบาลท้องถิ่นบางแห่งดำเนินการบัตรของตนเองที่สร้างขึ้นบน K-Pass ซึ่งให้สิทธิประโยชน์คืนเงินเพิ่มเติม (เช่น Gyeonggi Pass, Incheon I-Pass)",
                ky: "Кээ бир жергиликтүү бийликтер K-Pass негизинде курулган, кошумча кайтаруу артыкчылыктарын сунуш кылган өздөрүнүн карталарын иштетишет (мис., Gyeonggi Pass, Incheon I-Pass).",
                km: "រដ្ឋាភិបាលមូលដ្ឋានមួយចំនួនដំណើរការប័ណ្ណផ្ទាល់ខ្លួនរបស់ពួកគេ ដែលបង្កើតឡើងនៅលើ K-Pass ដោយផ្តល់អត្ថប្រយោជន៍សងប្រាក់បន្ថែម (ឧទាហរណ៍ Gyeonggi Pass, Incheon I-Pass)។",
                id: "Beberapa pemerintah daerah mengoperasikan kartu mereka sendiri yang dibangun di atas K-Pass, menawarkan manfaat pengembalian dana tambahan (misalnya, Gyeonggi Pass, Incheon I-Pass).",
                si: "සමහර පළාත් පාලන ආයතන K-Pass මත පදනම් වූ, අමතර මුදල් ආපසු ගෙවීමේ ප්‍රතිලාභ ලබා දෙන තමන්ගේම කාඩ්පත් ක්‍රියාත්මක කරයි (උදා: Gyeonggi Pass, Incheon I-Pass).",
                bn: "কিছু স্থানীয় সরকার K-Pass-এর উপর ভিত্তি করে তাদের নিজস্ব কার্ড পরিচালনা করে, যা অতিরিক্ত রিফান্ড সুবিধা প্রদান করে (যেমন Gyeonggi Pass, Incheon I-Pass)।",
                my: "အချို့သော ဒေသန္တရအစိုးရများသည် K-Pass ပေါ်တွင် အခြေခံ၍ အပိုဆောင်း ပြန်အမ်းငွေ အကျိုးခံစားခွင့်များ ပေးဆောင်သည့် ၎င်းတို့၏ကိုယ်ပိုင်ကတ်များကို လုပ်ဆောင်နေသည် (ဥပမာ- Gyeonggi Pass, Incheon I-Pass)။",
                mn: "Зарим орон нутгийн засаг захиргаа K-Pass дээр суурилсан, нэмэлт буцаан олголтын давуу талтай өөрийн картуудыг ажиллуулдаг (жишээ нь, Gyeonggi Pass, Incheon I-Pass).",
                lo: "ລັດຖະບານທ້ອງຖິ່ນບາງແຫ່ງດໍາເນີນການບັດຂອງຕົນເອງທີ່ສ້າງຂຶ້ນບົນພື້ນຖານ K-Pass, ສະເໜີຜົນປະໂຫຍດການຄືນເງິນເພີ່ມເຕີມ (ຕົວຢ່າງ: Gyeonggi Pass, Incheon I-Pass).",
                tet:
                    "Governu lokál balu opera sira-nia karta rasik ne'ebé harii iha K-Pass, oferese benefísiu reemborsu adisionál (ezemplu: Gyeonggi Pass, Incheon I-Pass).",
                ne: "केही स्थानीय सरकारहरूले K-Pass मा आधारित आफ्नै कार्डहरू सञ्चालन गर्छन्, जसले अतिरिक्त फिर्ता लाभहरू प्रदान गर्दछ (उदाहरणका लागि Gyeonggi Pass, Incheon I-Pass)।",
                zh: '部分地方政府在K-Pass的基础上运营自有卡片，提供额外的返还优惠（如京畿Pass、仁川I-Pass等）。',
