          ko: '월 15회 이상 대중교통을 이용하면 지출액의 일부를 다음 달에 환급받는 제도로, 매달 자동 정산됩니다.',
          en: 'If you use public transportation 15 or more times a month, you get part of your spending refunded the following month; the amount is automatically calculated each month.',
          tr: "Ayda 15 veya daha fazla kez toplu taşıma kullanırsanız, harcamanızın bir kısmı bir sonraki ay iade edilir; miktar her ay otomatik olarak hesaplanır.",
          tg: "Агар шумо дар як моҳ 15 ё бештар аз он маротиба аз нақлиёти ҷамъиятӣ истифода баред, як қисми хароҷоти шумо дар моҳи оянда баргардонида мешавад; маблағ ҳар моҳ ба таври худкор ҳисоб карда мешавад.",
