          ur: "اگر آپ مہینے میں 15 یا اس سے زیادہ بار پبلک ٹرانسپورٹ استعمال کرتے ہیں، تو آپ کے خرچ کا ایک حصہ اگلے مہینے واپس کر دیا جائے گا؛ رقم ہر مہینے خود بخود شمار کی جاتی ہے۔",
          th: "หากคุณใช้บริการขนส่งสาธารณะ 15 ครั้งขึ้นไปต่อเดือน ส่วนหนึ่งของค่าใช้จ่ายของคุณจะถูกคืนเงินในเดือนถัดไป โดยจำนวนเงินจะถูกคำนวณโดยอัตโนมัติทุกเดือน",
