          si: "ඔබ මසකට 15 වතාවක් හෝ ඊට වැඩි වාර ගණනක් පොදු ප්‍රවාහනය භාවිතා කරන්නේ නම්, ඔබේ වියදම්වලින් කොටසක් ඊළඟ මාසයේ ආපසු ගෙවනු ලැබේ; මුදල ස්වයංක්‍රීයව සෑම මසකම ගණනය කෙරේ.",
