          mn: "Хэрэв та сард 15 ба түүнээс дээш удаа нийтийн тээвэр ашиглавал, таны зарцуулсан мөнгөний тодорхой хэсгийг дараа сард буцаан олгоно; энэ хэмжээг сар бүр автоматаар тооцно.",
          lo: "ຖ້າທ່ານໃຊ້ການຂົນສົ່ງສາທາລະນະ 15 ຄັ້ງ ຫຼື ຫຼາຍກວ່ານັ້ນຕໍ່ເດືອນ, ສ່ວນໜຶ່ງຂອງຄ່າໃຊ້ຈ່າຍຂອງທ່ານຈະຖືກຄືນເງິນໃນເດືອນຕໍ່ໄປ; ຈໍານວນເງິນຈະຖືກຄິດໄລ່ໂດຍອັດຕະໂນມັດໃນແຕ່ລະເດືອນ.",
          tet:
