          uz: "Agar siz oyiga 15 yoki undan koʻproq marta jamoat transportidan foydalansangiz, keyingi oyda xarajatlaringizning bir qismi qaytariladi; miqdor har oy avtomatik ravishda hisoblanadi.",
        ),
