                bn: "আপনি যখন মাসে 15 বা তার বেশি বার পাবলিক ট্রান্সপোর্ট ব্যবহার করেন, তখন রিফান্ড থ্রেশহোল্ডের উপরের অংশের জন্য প্রযোজ্য হয়।",
                my: "တစ်လလျှင် အများပြည်သူ သယ်ယူပို့ဆောင်ရေးကို အကြိမ် 15 သို့မဟုတ် ထို့ထက်ပို၍ အသုံးပြုပါက ပြန်အမ်းငွေသည် သတ်မှတ်ချက်အထက် ပိုလျှံသည့် ပမာဏအတွက် အကျုံးဝင်ပါသည်။",
                mn: "Сард 15 ба түүнээс дээш удаа нийтийн тээвэр ашигласан тохиолдолд буцаан олголтын босгоос дээш хэсэгт хамаарна.",
                lo: "ເມື່ອທ່ານໃຊ້ການຂົນສົ່ງສາທາລະນະ 15 ຄັ້ງ ຫຼື ຫຼາຍກວ່ານັ້ນຕໍ່ເດືອນ, ການຄືນເງິນຈະນໍາໃຊ້ກັບສ່ວນທີ່ເກີນຂອບເຂດ.",
                tet:
                    "Bainhira ó uza transporte públiku 15 ka liu kada fulan, ne'e aplika ba parte ne'ebé liu limite reemborsu nian.",
                ne: "जब तपाईंले महिनामा 15 वा सोभन्दा बढी पटक सार्वजनिक यातायात प्रयोग गर्नुहुन्छ, फिर्ता थ्रेसहोल्डभन्दा माथिको भागमा लागू हुन्छ।",
                zh: '每月使用公共交通达15次以上时，超出部分将享受返还',
                vi: 'Khi sử dụng phương tiện công cộng từ 15 lần trở lên trong tháng, phần vượt quá sẽ được áp dụng hoàn tiền',
                uz: "Bir oyda 15 yoki undan koʻproq marta jamoat transportidan foydalansangiz, qaytarish chegara ustidagi qismga nisbatan qoʻllaniladi",
              ),
            ],
          ),
