                mn: "Ерөнхий (19 ба түүнээс дээш нас): %20; Залуу (19–34 нас, Gyeonggi болон Incheon-д 39 нас хүртэл): %30; Бага Орлоготой (амьжиргааны үндсэн тусламж авдаг болон ядуурлын шугамд ойр өрхүүд): %53",
                lo: "ທົ່ວໄປ (19 ປີຂຶ້ນໄປ): 20%; ຊາວໜຸ່ມ (19–34 ປີ, ສູງສຸດ 39 ປີໃນ Gyeonggi ແລະ Incheon): 30%; ລາຍໄດ້ຕໍ່າ (ຜູ້ໄດ້ຮັບການຊ່ວຍເຫຼືອຊີບພື້ນຖານ ແລະ ຄົວເຮືອນທີ່ໃກ້ກັບເສັ້ນຄວາມທຸກຍາກ): 53%",
                tet:
