                ne: "सामान्य (19 वर्ष र माथि): %20; युवा (19–34 वर्ष, Gyeonggi र Incheon मा 39 वर्षसम्म): %30; न्यून आय भएका (आधारभूत जीविकोपार्जन सहायता प्राप्त गर्नेहरू र गरिबीको रेखा नजिकका घरपरिवारहरू): %53",
                zh: '一般人群（满19周岁以上）：20%；青年（满19~34周岁，京畿道、仁川市可至满39周岁）：30%；低收入群体（基础生活保障对象、次贫困阶层）：53%',
                vi: 'Đối tượng thông thường (từ 19 tuổi trở lên): 20%; Thanh niên (19-34 tuổi, riêng Gyeonggi, Incheon áp dụng đến 39 tuổi): 30%; Hộ thu nhập thấp (đối tượng hưởng trợ cấp sinh hoạt cơ bản, hộ cận nghèo): 53%',
                uz: "Umumiy (19 yosh va undan katta): 20%; Yoshlar (19–34 yosh, Gyeonggi va Incheonda 39 yoshgacha): 30%; Kam taʼminlangan (asosiy turmush sharoiti oluvchilar va qashshoqlikka yaqin oilalar): 53%",
