        summary: L10nText(
          ko: '버스·지하철 모두 교통카드 태그로 환승 할인이 자동 적용되며, 하차 시에도 반드시 태그해야 정확한 요금이 계산됩니다.',
          en: 'On both buses and the subway, transfer discounts are applied automatically when you tag your transit card, and you must also tag when getting off to ensure the correct fare is calculated.',
          tr: "Hem otobüslerde hem de metroda, ulaşım kartınızı okuttuğunuzda aktarma indirimleri otomatik olarak uygulanır ve doğru ücretin hesaplanması için inerken de kartınızı okutmanız gerekir.",
          tg: "Ҳам дар автобусҳо ва ҳам дар метро, вақте ки шумо корти нақлиётии худро скан мекунед, тахфифҳои интиқол ба таври худкор татбиқ мешаванд ва барои ҳисоб кардани тарифи дуруст, шумо бояд ҳангоми фаромадан низ корти худро скан кунед.",
          fil:
              "Sa mga bus at subway, awtomatikong inilalapat ang mga diskwento sa transfer kapag ini-scan mo ang iyong transportation card, at kailangan mo ring i-scan ang iyong card kapag bumaba upang makalkula ang tamang pamasahe.",
          ur: "بسوں اور میٹرو دونوں میں، جب آپ اپنا ٹرانسپورٹ کارڈ اسکین کرتے ہیں تو ٹرانسفر ڈسکاؤنٹ خود بخود لاگو ہو جاتے ہیں، اور درست کرایہ کے حساب کے لیے اترتے وقت بھی آپ کو اپنا کارڈ اسکین کرنا ہوگا۔",
          th: "ทั้งบนรถบัสและรถไฟใต้ดิน ส่วนลดการเปลี่ยนถ่ายจะถูกนำไปใช้โดยอัตโนมัติเมื่อคุณแตะบัตรโดยสาร และคุณต้องแตะบัตรอีกครั้งเมื่อลงจากรถเพื่อคำนวณค่าโดยสารที่ถูกต้อง",
          ky: "Автобустарда да, метродо да, транспорт картаңызды окутканыңызда которуу арзандатуулары автоматтык түрдө колдонулат жана туура төлөмдү эсептөө үчүн түшүп жатканда да картаңызды окутушуңуз керек.",
          km: "ទាំងនៅលើឡានក្រុង និងរថភ្លើងក្រោមដី ការបញ្ចុះតម្លៃសម្រាប់ការផ្ទេរនឹងត្រូវបានអនុវត្តដោយស្វ័យប្រវត្តិនៅពេលអ្នកស្កេនប័ណ្ណដឹកជញ្ជូនរបស់អ្នក ហើយអ្នកក៏ត្រូវស្កេនប័ណ្ណរបស់អ្នកនៅពេលចុះផងដែរ ដើម្បីគណនាថ្លៃឈ្នួលត្រឹមត្រូវ។",
          id: "Baik di bus maupun kereta bawah tanah, diskon transfer otomatis diterapkan saat Anda memindai kartu transportasi Anda, dan Anda juga perlu memindai kartu Anda saat turun untuk menghitung tarif yang benar.",
          si: "බස් රථවල සහ උමං මාර්ගවල යන දෙකෙහිම, ඔබ ඔබේ ප්‍රවාහන කාඩ්පත ස්කෑන් කරන විට මාරු කිරීමේ වට්ටම් ස්වයංක්‍රීයව අදාළ වන අතර, නිවැරදි ගාස්තුව ගණනය කිරීම සඳහා බැස යන විට ද ඔබේ කාඩ්පත ස්කෑන් කළ යුතුය.",
          bn: "বাস এবং সাবওয়ে উভয় ক্ষেত্রেই, আপনি যখন আপনার পরিবহন কার্ড স্ক্যান করেন তখন স্থানান্তর ছাড় স্বয়ংক্রিয়ভাবে প্রয়োগ করা হয় এবং সঠিক ভাড়া গণনার জন্য নামার সময়ও আপনাকে আপনার কার্ড স্ক্যান করতে হবে।",
          my: "ဘတ်စ်ကားနှင့် မြေအောက်ရထား နှစ်ခုလုံးတွင် သင်၏ သယ်ယူပို့ဆောင်ရေးကတ်ကို ပွတ်ဆွဲလိုက်သောအခါ လွှဲပြောင်းလျှော့စျေးများကို အလိုအလျောက် အသုံးပြုပေးမည်ဖြစ်ပြီး မှန်ကန်သော ခရီးစရိတ်ကို တွက်ချက်နိုင်ရန် ဆင်းသည့်အခါတွင်လည်း သင်၏ကတ်ကို ပွတ်ဆွဲရန် လိုအပ်ပါသည်။",
          mn: "Автобус болон метронд хоёуланд нь таны тээврийн картыг уншуулахад шилжүүлгийн хөнгөлөлт автоматаар хэрэгжиж, зөв төлбөрийг тооцоолохын тулд буухдаа ч мөн картаа уншуулах шаардлагатай.",
          lo: "ທັງໃນລົດເມ ແລະ ລົດໄຟໃຕ້ດິນ, ສ່ວນຫຼຸດການໂອນຈະຖືກນໍາໃຊ້ໂດຍອັດຕະໂນມັດເມື່ອທ່ານແຕະບັດໂດຍສານຂອງທ່ານ, ແລະ ທ່ານຍັງຈໍາເປັນຕ້ອງແຕະບັດຂອງທ່ານເມື່ອລົງຈາກລົດເພື່ອໃຫ້ຄ່າໂດຍສານທີ່ຖືກຕ້ອງຖືກຄິດໄລ່.",
          tet:
              "Iha bus no mós iha metro, deskontu transferénsia sei aplika automaticamente bainhira ó skan ó-nia karta transporte, no ó presiza mós skan ó-nia karta bainhira tun atu kalkula tarifa loos.",
          ne: "बस र मेट्रो दुवैमा, तपाईंले आफ्नो यातायात कार्ड स्क्यान गर्दा स्थानान्तरण छुटहरू स्वचालित रूपमा लागू हुन्छन्, र सही भाडा गणना गर्नको लागि ओर्लँदा पनि तपाईंले आफ्नो कार्ड स्क्यान गर्नुपर्छ।",
          zh: '无论是公交车还是地铁，刷交通卡都会自动享受换乘优惠，下车时也必须刷卡，才能准确计算车费。',
          vi: 'Cả xe buýt và tàu điện ngầm đều tự động áp dụng giảm giá chuyển tuyến khi quẹt thẻ giao thông, và khi xuống xe cũng phải quẹt thẻ để tính đúng cước phí.',
          uz: "Avtobus va metrolarda transport kartangizni oʻqitganingizda avtomatik ravishda chegirmalar qoʻllaniladi va toʻgʻri toʻlov hisoblanishini taʼminlash uchun tushayotganingizda ham kartani oʻqitishingiz shart.",
        ),
