                km: "ប្រសិនបើអ្នកភ្លេចស្កេនកាតរបស់អ្នកនៅពេលចុះ ថ្លៃសេវាមូលដ្ឋានអាចនឹងត្រូវគិតម្ដងទៀតក្នុងការធ្វើដំណើរលើកក្រោយរបស់អ្នក។",
