                si: "ඔබ බසයෙන් බසින විට ඔබේ කාඩ්පත ස්කෑන් කිරීමට අමතක වුවහොත්, ඔබේ ඊළඟ ගමන සඳහා මූලික ගාස්තුව නැවත අය කළ හැක.",
