                en: 'The time limit and number of transfers allowed vary by region, so check your local government\'s public transportation guidelines.',
                tr: "Aktarma için tanınan süre sınırı ve aktarma sayısı bölgeden bölgeye değişir, bu nedenle yerel yönetiminizin toplu taşıma yönergelerini kontrol edin.",
                tg: "Мӯҳлати интиқол ва шумораи интиқолҳо аз рӯи минтақа фарқ мекунанд, аз ин рӯ, дастурҳои нақлиёти ҷамъиятии ҳукумати маҳаллии худро тафтиш кунед.",
