                km: "ដែនកំណត់ពេលវេលា និងចំនួននៃការផ្ទេរប្រែប្រួលពីតំបន់មួយទៅតំបន់មួយទៀត ដូច្នេះសូមពិនិត្យមើលគោលការណ៍ណែនាំនៃការដឹកជញ្ជូនសាធារណៈរបស់រដ្ឋាភិបាលមូលដ្ឋានរបស់អ្នក។",
