                bn: "স্থানান্তরের জন্য অনুমোদিত সময়সীমা এবং স্থানান্তরের সংখ্যা অঞ্চলভেদে ভিন্ন হয়, তাই আপনার স্থানীয় সরকারের গণপরিবহন নির্দেশিকা পরীক্ষা করুন।",
