                lo: "ໄລຍະເວລາທີ່ອະນຸຍາດໃຫ້ຕໍ່ລົດ ແລະ ຈໍານວນການຕໍ່ລົດແຕກຕ່າງກັນໄປໃນແຕ່ລະພາກພື້ນ, ດັ່ງນັ້ນກະລຸນາກວດເບິ່ງຄໍາແນະນໍາການຂົນສົ່ງສາທາລະນະຂອງລັດຖະບານທ້ອງຖິ່ນຂອງທ່ານ.",
