                ur: "معاہدہ شدہ ممالک (وہ ممالک جو کورین ڈرائیونگ لائسنس کو تسلیم کرتے ہیں) سے حاصل کردہ لائسنس: صرف دستاویزات کی جانچ اور اہلیت کے ٹیسٹ (جسمانی معائنہ) کے ذریعے تبدیل کیے جا سکتے ہیں۔",
                th: "ใบขับขี่ที่ได้รับจากประเทศที่มีข้อตกลง (ประเทศที่ยอมรับใบขับขี่เกาหลี): สามารถแปลงได้โดยการตรวจสอบเอกสารและการทดสอบความสามารถ (การตรวจร่างกาย) เท่านั้น",
                ky: "Келишим түзгөн өлкөлөрдөн (Кореянын айдоочулук күбөлүктөрүн тааныган өлкөлөр) алынган айдоочулук күбөлүктөр: Документтерди текшерүү жана жөндөмдүүлүк тести (физикалык кароо) аркылуу гана которулат.",
                km: "ប័ណ្ណបើកបរដែលទទួលបានពីប្រទេសដែលមានកិច្ចព្រមព្រៀង (ប្រទេសដែលទទួលស្គាល់ប័ណ្ណបើកបររបស់កូរ៉េ)៖ អាចបំប្លែងបានដោយគ្រាន់តែពិនិត្យឯកសារ និងធ្វើតេស្តសមត្ថភាព (ការពិនិត្យរាងកាយ)។",
                id: "SIM dari negara yang menyetujui (negara yang mengakui SIM Korea): Dapat dikonversi hanya dengan pemeriksaan dokumen dan tes kemampuan (pemeriksaan fisik).",
                si: "ගිවිසුම්ගත රටවලින් (කොරියානු රියදුරු බලපත්‍ර පිළිගන්නා රටවල්) ලබාගත් රියදුරු බලපත්‍ර: ලේඛන පරීක්ෂා කිරීම සහ නිපුණතා පරීක්ෂණය (ශාරීරික පරීක්ෂණය) මගින් පමණක් පරිවර්තනය කළ හැක.",
                bn: "চুক্তিভুক্ত দেশগুলি থেকে প্রাপ্ত লাইসেন্স (যে দেশগুলি কোরিয়ান লাইসেন্সকে স্বীকৃতি দেয়): শুধুমাত্র নথি পর্যালোচনা এবং দক্ষতা পরীক্ষা (শারীরিক পরীক্ষা) দ্বারা রূপান্তরিত করা যেতে পারে।",
                my: "သဘောတူညီချက်ရရှိထားသော နိုင်ငံများ (ကိုရီးယားယာဉ်မောင်းလိုင်စင်များကို အသိအမှတ်ပြုသော နိုင်ငံများ) မှ ရရှိသော လိုင်စင်များ- စာရွက်စာတမ်းစစ်ဆေးခြင်းနှင့် ကျွမ်းကျင်မှုစစ်ဆေးခြင်း (ကိုယ်ခန္ဓာစစ်ဆေးခြင်း) ဖြင့်သာ ပြောင်းလဲနိုင်ပါသည်။",
                mn: "Гэрээт улсуудаас (Солонгосын жолооны үнэмлэхийг хүлээн зөвшөөрдөг улсууд) авсан жолооны үнэмлэх: Зөвхөн бичиг баримтын хяналт болон чадварын шалгалт (биеийн үзлэг) -ээр хөрвүүлж болно.",
                lo: "ໃບຂັບຂີ່ທີ່ໄດ້ຮັບຈາກປະເທດທີ່ມີຂໍ້ຕົກລົງ (ປະເທດທີ່ຮັບຮູ້ໃບຂັບຂີ່ເກົາຫຼີ): ສາມາດປ່ຽນໄດ້ໂດຍການກວດສອບເອກະສານ ແລະ ການທົດສອບຄວາມສາມາດ (ກວດສຸຂະພາບ) ເທົ່ານັ້ນ.",
                tet:
                    "Lisensa sira ne'ebé hetan husi nasaun ho akordu (nasaun sira ne'ebé rekoñese lisensa Koreia): Bele konverte ho revizaun dokumentu no teste abilidade (ezame fíziku) de'it.",
                ne: "सम्झौता भएका देशहरू (कोरियाली लाइसेन्सलाई मान्यता दिने देशहरू) बाट प्राप्त लाइसेन्सहरू: कागजात समीक्षा र योग्यता परीक्षण (शारीरिक परीक्षण) मार्फत मात्र रूपान्तरण गर्न सकिन्छ।",
                zh: '协议缔结国（认可韩国驾照的国家）驾照：只需材料审查和适性检查（体检）即可换领',
                vi: 'Bằng lái của quốc gia đã ký hiệp định (quốc gia công nhận bằng lái Hàn Quốc): Chỉ cần thẩm tra hồ sơ và kiểm tra năng lực thích ứng (khám sức khỏe) là có thể đổi bằng',
                uz: "Kelishuv mamlakatlari (Koreya guvohnomalarini tan oladigan mamlakatlar) guvohnomalari: Faqat hujjatlarni tekshirish va qobiliyat testidan (tibbiy koʻrik) oʻtish orqali almashtirilishi mumkin.",
              ),
              L10nText(
                ko: '협약 미체결국 면허: 적성검사 + 학과시험(객관식 40문항, 한국어·영어·중국어·베트남어 중 선택) 응시 필요',
                en: 'Licenses from non-agreement countries: Require an aptitude test plus a written exam (40 multiple-choice questions, available in Korean, English, Chinese, or Vietnamese)',
                tr: "Anlaşmasız ülkelerden alınan ehliyetler: Yetenek testi artı yazılı sınav (40 çoktan seçmeli soru, Korece, İngilizce, Çince veya Vietnamca dillerinde mevcut) gerektirir.",
                tg: "Шаҳодатномаҳои ронандагӣ, ки аз кишварҳои бесозишнома гирифта шудаанд: Санҷиши қобилият ва имтиҳони хаттӣ ( 40 саволи бисёрҷавоба, бо забонҳои кореягӣ, англисӣ, чинӣ ё ветнамӣ дастрас аст) талаб мекунанд.",
                fil:
                    "Mga lisensya sa pagmamaneho mula sa mga bansang walang kasunduan: Nangangailangan ng pagsusuri ng kakayahan kasama ang nakasulat na pagsusulit (40 multiple-choice na tanong, available sa Korean, English, Chinese, o Vietnamese).",
                ur: "غیر معاہدہ شدہ ممالک سے حاصل کردہ لائسنس: اہلیت کے ٹیسٹ کے علاوہ تحریری امتحان (40 کثیر انتخابی سوالات، کورین، انگریزی، چینی یا ویتنامی زبانوں میں دستیاب) کی ضرورت ہوتی ہے۔",
                th: "ใบขับขี่ที่ได้รับจากประเทศที่ไม่มีข้อตกลง: ต้องมีการทดสอบความสามารถและข้อสอบข้อเขียน (คำถามปรนัย 40 ข้อ มีให้บริการในภาษาเกาหลี, อังกฤษ, จีน หรือเวียดนาม)",
                ky: "Келишим түзбөгөн өлкөлөрдөн алынган айдоочулук күбөлүктөр: Жөндөмдүүлүк тестинен тышкары жазуу жүзүндөгү сынак (Корей, Англис, Кытай же Вьетнам тилдеринде жеткиликтүү 40 көп тандоо суроосу) талап кылынат.",
                km: "ប័ណ្ណបើកបរដែលទទួលបានពីប្រទេសដែលគ្មានកិច្ចព្រមព្រៀង៖ តម្រូវឱ្យមានការធ្វើតេស្តសមត្ថភាពបូកនឹងការប្រឡងសរសេរ (សំណួរពហុជម្រើស 40 មានជាភាសាកូរ៉េ អង់គ្លេស ចិន ឬវៀតណាម)។",
                id: "SIM dari negara yang tidak menyetujui: Membutuhkan tes kemampuan ditambah tes tertulis (40 pertanyaan pilihan ganda, tersedia dalam bahasa Korea, Inggris, Mandarin, atau Vietnam).",
                si: "ගිවිසුම්ගත නොවන රටවලින් ලබාගත් රියදුරු බලපත්‍ර: නිපුණතා පරීක්ෂණයට අමතරව ලිඛිත පරීක්ෂණයක් (බහුවරණ ප්‍රශ්න 40, කොරියානු, ඉංග්‍රීසි, චීන හෝ වියට්නාම භාෂාවලින් ලබා ගත හැක) අවශ්‍ය වේ.",
                bn: "অ-চুক্তিভুক্ত দেশগুলি থেকে প্রাপ্ত লাইসেন্স: দক্ষতা পরীক্ষা এবং লিখিত পরীক্ষা (40টি বহু-নির্বাচনী প্রশ্ন, কোরিয়ান, ইংরেজি, চীনা বা ভিয়েতনামী ভাষায় উপলব্ধ) প্রয়োজন।",
                my: "သဘောတူညီချက်မရရှိသေးသော နိုင်ငံများမှ ရရှိသော လိုင်စင်များ- ကျွမ်းကျင်မှုစစ်ဆေးခြင်းအပြင် စာရေးဖြေစာမေးပွဲ (40 မေးခွန်းပေါင်းစုံရွေးချယ်မှု၊ ကိုရီးယား၊ အင်္ဂလိပ်၊ တရုတ် သို့မဟုတ် ဗီယက်နမ်ဘာသာစကားများဖြင့် ရရှိနိုင်သည်) လိုအပ်ပါသည်။",
                mn: "Гэрээгүй улсуудаас авсан жолооны үнэмлэх: Чадварын шалгалт дээр нэмээд бичгийн шалгалт (40 олон сонголттой асуулт, Солонгос, Англи, Хятад эсвэл Вьетнам хэлээр авах боломжтой) шаардлагатай.",
                lo: "ໃບຂັບຂີ່ທີ່ໄດ້ຮັບຈາກປະເທດທີ່ບໍ່ມີຂໍ້ຕົກລົງ: ຕ້ອງມີການທົດສອບຄວາມສາມາດບວກກັບການສອບເສັງຂຽນ (ຄໍາຖາມແບບເລືອກຕອບ 40 ຂໍ້, ມີເປັນພາສາເກົາຫຼີ, ອັງກິດ, ຈີນ, ຫຼື ຫວຽດນາມ).",
                tet:
                    "Lisensa sira ne'ebé hetan husi nasaun la ho akordu: Presiza teste abilidade hamutuk ho ezame eskrita (pergunta mútlipla-eskolla 40, disponivel iha lian Koreia, Inglés, Xina ka Vietnamita).",
                ne: "सम्झौता नभएका देशहरूबाट प्राप्त लाइसेन्सहरू: योग्यता परीक्षणका साथै लिखित परीक्षा (40 बहुविकल्पीय प्रश्नहरू, कोरियाली, अंग्रेजी, चिनियाँ वा भियतनामी भाषाहरूमा उपलब्ध) आवश्यक पर्दछ।",
                zh: '非协议缔结国驾照：需参加适性检查及学科考试（40道客观题，可选韩语、英语、中文、越南语作答）',
                vi: 'Bằng lái của quốc gia chưa ký hiệp định: Cần kiểm tra năng lực thích ứng và thi lý thuyết (40 câu trắc nghiệm, được chọn tiếng Hàn, tiếng Anh, tiếng Trung hoặc tiếng Việt)',
                uz: "Kelishuvga kirmagan mamlakatlar guvohnomalari: Qobiliyat testi va yozma imtihon (40 ta koʻp tanlovli savol, koreys, ingliz, xitoy yoki vetnam tillarida mavjud) talab qilinadi.",
              ),
            ],
          ),
