                km: "ប័ណ្ណបើកបរអន្តរជាតិមានសុពលភាពត្រឹមតែ 1 ឆ្នាំគិតចាប់ពីថ្ងៃចេញ។",
                id: "SIM Internasional hanya berlaku selama 1 tahun sejak tanggal penerbitan.",
                si: "ජාත්‍යන්තර රියදුරු බලපත්‍රයක් නිකුත් කළ දින සිට වසර 1 ක් සඳහා පමණක් වලංගු වේ.",
                bn: "একটি আন্তর্জাতিক ড্রাইভিং লাইসেন্স ইস্যু করার তারিখ থেকে শুধুমাত্র 1 বছরের জন্য বৈধ।",
                my: "နိုင်ငံတကာ ယာဉ်မောင်းလိုင်စင်သည် ထုတ်ပေးသည့်နေ့မှစ၍ 1 နှစ်သာ အကျုံးဝင်ပါသည်။",
                mn: "Олон улсын жолооны үнэмлэх нь олгосон өдрөөс хойш зөвхөн 1 жил хүчинтэй.",
                lo: "ໃບຂັບຂີ່ສາກົນມີອາຍຸໃຊ້ໄດ້ພຽງແຕ່ 1 ປີ ນັບແຕ່ວັນທີ່ອອກ.",
                tet:
                    "Lisensa Kondusaun Internasionál válidu de'it ba tinan 1 husi data emisaun.",
                ne: "अन्तर्राष्ट्रिय ड्राइभिङ लाइसेन्स जारी भएको मितिबाट 1 वर्षको लागि मात्र मान्य हुन्छ।",
                zh: '国际驾照自签发之日起仅一年内有效。',
                vi: 'Bằng lái xe quốc tế chỉ có hiệu lực trong 1 năm kể từ ngày cấp.',
                uz: "Xalqaro haydovchilik guvohnomasi berilgan sanadan boshlab faqat 1 yil davomida amal qiladi.",
              ),
              L10nText(
                ko: '한국에 1년 이상 체류하며 운전하려면 국제운전면허증이 아니라 반드시 국내면허로 교환해야 합니다.',
                en: 'If you plan to stay in Korea for 1 year or more and drive, you must convert to a Korean license instead of relying on an International Driving Permit.',
                tr: "Kore'de 1 yıl veya daha uzun süre kalmayı ve araç kullanmayı planlıyorsanız, Uluslararası Sürücü Belgesine güvenmek yerine Kore ehliyetine dönüştürmeniz gerekir.",
                tg: "Агар шумо нақша дошта бошед, ки дар Корея 1 сол ё бештар аз он бимонед ва мошин ронед, шумо бояд онро ба шаҳодатномаи ронандагии Корея табдил диҳед, на ба шаҳодатномаи ронандагии байналмилалӣ такя кунед.",
                fil:
                    "Kung plano mong manatili sa Korea nang 1 taon o higit pa at magmaneho, sa halip na umasa sa International Driving Permit, kailangan mong i-convert ito sa Korean driver's license.",
                ur: "اگر آپ کوریا میں 1 سال یا اس سے زیادہ عرصے تک رہنے اور گاڑی چلانے کا ارادہ رکھتے ہیں، تو آپ کو بین الاقوامی ڈرائیونگ لائسنس پر انحصار کرنے کے بجائے اسے کورین لائسنس میں تبدیل کرنا چاہیے۔",
                th: "หากคุณวางแผนที่จะอยู่ในเกาหลีและขับรถเป็นเวลา 1 ปีหรือนานกว่านั้น คุณจะต้องแปลงเป็นใบขับขี่เกาหลีแทนที่จะพึ่งพาใบขับขี่สากล",
                ky: "Эгерде сиз Кореяда 1 жыл же андан көп убакыт калууну жана унаа айдоону пландаштырсаңыз, Эл аралык айдоочулук күбөлүгүнө таянбастан, Кореянын айдоочулук күбөлүгүнө которушуңуз керек.",
                km: "ប្រសិនបើអ្នកមានគម្រោងស្នាក់នៅ និងបើកបរនៅប្រទេសកូរ៉េលើសពី 1 ឆ្នាំ អ្នកត្រូវតែបំប្លែងទៅជាប័ណ្ណបើកបររបស់កូរ៉េ ជំនួសឱ្យការពឹងផ្អែកលើប័ណ្ណបើកបរអន្តរជាតិ។",
                id: "Jika Anda berencana untuk tinggal di Korea selama 1 tahun atau lebih dan mengemudi, Anda harus mengonversi ke SIM Korea daripada mengandalkan SIM Internasional.",
                si: "ඔබ කොරියාවේ වසර 1ක් හෝ ඊට වැඩි කාලයක් රැඳී සිටීමට සහ රිය පැදවීමට අදහස් කරන්නේ නම්, ජාත්‍යන්තර රියදුරු බලපත්‍රයක් මත විශ්වාසය තැබීමට වඩා කොරියානු රියදුරු බලපත්‍රයකට පරිවර්තනය කිරීම අවශ්‍ය වේ.",
                bn: "আপনি যদি কোরিয়াতে 1 বছর বা তার বেশি সময় ধরে থাকতে এবং গাড়ি চালাতে চান, তাহলে আন্তর্জাতিক ড্রাইভিং লাইসেন্সের উপর নির্ভর না করে আপনার কোরিয়ান লাইসেন্সে রূপান্তর করা উচিত।",
                my: "ကိုရီးယားတွင် 1 နှစ် သို့မဟုတ် ထို့ထက်ပို၍ နေထိုင်ရန်နှင့် ကားမောင်းရန် စီစဉ်ထားပါက နိုင်ငံတကာ ယာဉ်မောင်းလိုင်စင်ကို အားကိုးမည့်အစား ကိုရီးယားယာဉ်မောင်းလိုင်စင်သို့ ပြောင်းလဲသင့်ပါသည်။",
                mn: "Хэрэв та Солонгост 1 жил ба түүнээс дээш хугацаагаар оршин сууж, машин жолоодохыг төлөвлөж байгаа бол Олон улсын жолооны үнэмлэхэнд найдахын оронд Солонгосын жолооны үнэмлэх болгон хөрвүүлэх шаардлагатай.",
                lo: "ຖ້າທ່ານວາງແຜນທີ່ຈະຢູ່ໃນເກົາຫຼີ ແລະ ຂັບຂີ່ລົດເປັນເວລາ 1 ປີ ຫຼື ດົນກວ່ານັ້ນ, ທ່ານຈໍາເປັນຕ້ອງປ່ຽນເປັນໃບຂັບຂີ່ເກົາຫຼີ ແທນທີ່ຈະເພິ່ງໃບຂັບຂີ່ສາກົນ.",
                tet:
                    "Se Ita planeia atu hela no kondús iha Koreia ba tinan 1 ka liu, Ita presiza konverte ba lisensa kondusaun Koreia duke depende ba Lisensa Kondusaun Internasionál.",
                ne: "यदि तपाईं कोरियामा 1 वर्ष वा सोभन्दा बढी समय बस्ने र गाडी चलाउने योजना बनाउनुहुन्छ भने, अन्तर्राष्ट्रिय ड्राइभिङ लाइसेन्समा भर पर्नुको सट्टा कोरियाली लाइसेन्समा रूपान्तरण गर्नुपर्छ।",
                zh: '如果计划在韩居留一年以上并需要开车，必须换领韩国国内驾照，而不能仅凭国际驾照。',
                vi: 'Nếu lưu trú tại Hàn Quốc từ 1 năm trở lên và có nhu cầu lái xe, bạn bắt buộc phải đổi sang bằng lái trong nước chứ không thể chỉ dùng bằng lái xe quốc tế.',
                uz: "Agar siz Koreyada 1 yil yoki undan koʻproq qolishni va mashina haydashni rejalashtirmoqchi boʻlsangiz, Xalqaro haydovchilik guvohnomasiga tayanmasdan, Koreya guvohnomasiga almashtirishingiz shart.",
              ),
            ],
          ),
        ],
      ),
      BookPage(
