          ky: "Чет элдик айдоочулук күбөлүгүн Кореянын айдоочулук күбөлүгүнө которуу: Жол-жобо жана эскертүүлөр",
          km: "ការបំប្លែងប័ណ្ណបើកបរពីបរទេសទៅជាប័ណ្ណបើកបររបស់កូរ៉េ៖ នីតិវិធី និងកំណត់ចំណាំ",
          id: "Mengubah SIM Asing menjadi SIM Korea: Prosedur dan Catatan",
          si: "විදේශීය රියදුරු බලපත්‍රයක් කොරියානු රියදුරු බලපත්‍රයකට පරිවර්තනය කිරීම: ක්‍රියා පටිපාටිය සහ සටහන්",
          bn: "বিদেশী ড্রাইভিং লাইসেন্সকে কোরিয়ান ড্রাইভিং লাইসেন্সে রূপান্তর: পদ্ধতি এবং নোট",
          my: "နိုင်ငံခြားသား ယာဉ်မောင်းလိုင်စင်ကို ကိုရီးယားယာဉ်မောင်းလိုင်စင်သို့ ပြောင်းလဲခြင်း- လုပ်ထုံးလုပ်နည်းနှင့် မှတ်စုများ",
          mn: "Гадаадын жолооны үнэмлэхийг Солонгосын жолооны үнэмлэх болгон хөрвүүлэх: Журам ба тэмдэглэл",
          lo: "ການປ່ຽນໃບຂັບຂີ່ຕ່າງປະເທດເປັນໃບຂັບຂີ່ເກົາຫຼີ: ຂັ້ນຕອນ ແລະ ຂໍ້ຄວນລະວັງ",
          tet:
