          ne: "विदेशी ड्राइभिङ लाइसेन्सलाई कोरियाली ड्राइभिङ लाइसेन्समा रूपान्तरण गर्ने: प्रक्रिया र नोटहरू",
          zh: '外国驾照换领韩国驾照：办理程序与注意事项',
          vi: 'Đổi bằng lái nước ngoài sang bằng lái Hàn Quốc: Quy trình và lưu ý',
          uz: "Xorijiy haydovchilik guvohnomasini Koreya guvohnomasiga almashtirish: Tartib va eslatmalar",
        ),
        summary: L10nText(
          ko: '신청은 전국 운전면허시험장 또는 경찰서 민원실에서 접수하며, 신체검사료 등 소정의 수수료가 발생합니다.',
          en: 'Applications are accepted at driver\'s license test centers or police station civil affairs offices nationwide, and a set fee, including a physical exam fee, applies.',
          tr: "Başvurular ülke genelindeki sürücü belgesi sınav merkezlerinde veya polis karakolu sivil işler ofislerinde kabul edilmekte olup, fiziksel muayene ücreti dahil sabit bir ücret uygulanır.",
          tg: "Аризаҳо дар марказҳои имтиҳони шаҳодатномаи ронандагӣ дар саросари кишвар ё дар идораҳои корҳои шаҳрвандии шӯъбаи полис қабул карда мешаванд ва ҳаққи муқаррарӣ, аз ҷумла ҳаққи муоинаи ҷисмонӣ, ситонида мешавад.",
          fil:
              "Ang mga aplikasyon ay tinatanggap sa mga driver's license examination center sa buong bansa o sa mga civil affairs office ng istasyon ng pulisya, at mayroong nakapirming bayad kasama ang bayad sa physical examination.",
          ur: "درخواستیں ملک بھر کے ڈرائیونگ لائسنس امتحانی مراکز یا پولیس اسٹیشن کے سول افیئرز دفاتر میں قبول کی جاتی ہیں، اور جسمانی معائنے کی فیس سمیت ایک مقررہ فیس لاگو ہوتی ہے۔",
          th: "การสมัครสามารถทำได้ที่ศูนย์สอบใบขับขี่ทั่วประเทศ หรือสำนักงานกิจการพลเรือนของสถานีตำรวจ โดยมีค่าธรรมเนียมคงที่รวมค่าตรวจร่างกาย",
          ky: "Арыздар өлкө боюнча айдоочулук күбөлүгүн текшерүү борборлорунда же полиция бөлүмдөрүнүн жарандык иштер бөлүмдөрүндө кабыл алынат, физикалык кароо акысын кошкондо туруктуу төлөм алынат.",
          km: "ពាក្យសុំត្រូវបានទទួលយកនៅមជ្ឈមណ្ឌលប្រឡងប័ណ្ណបើកបរទូទាំងប្រទេស ឬការិយាល័យកិច្ចការស៊ីវិលរបស់ប៉ុស្តិ៍ប៉ូលីស ហើយថ្លៃសេវាថេរមួយត្រូវបានអនុវត្ត រួមទាំងថ្លៃពិនិត្យរាងកាយផងដែរ។",
          id: "Aplikasi diterima di pusat ujian SIM nasional atau kantor urusan sipil kantor polisi, dan biaya tetap berlaku, termasuk biaya pemeriksaan fisik.",
          si: "අයදුම්පත් දිවයින පුරා පිහිටි රියදුරු බලපත්‍ර විභාග මධ්‍යස්ථානවලින් හෝ පොලිස් ස්ථානවල සිවිල් කටයුතු කාර්යාලවලින් භාර ගන්නා අතර, ශාරීරික පරීක්ෂණ ගාස්තු ඇතුළුව ස්ථාවර ගාස්තුවක් අදාළ වේ.",
          bn: "আবেদনগুলি দেশব্যাপী ড্রাইভিং লাইসেন্স পরীক্ষা কেন্দ্র বা পুলিশ স্টেশন সিভিল অ্যাফেয়ার্স অফিসে গ্রহণ করা হয় এবং শারীরিক পরীক্ষার ফি সহ একটি নির্দিষ্ট ফি প্রযোজ্য।",
          my: "လျှောက်လွှာများကို နိုင်ငံတစ်ဝန်းရှိ ယာဉ်မောင်းလိုင်စင် စာမေးပွဲစင်တာများ သို့မဟုတ် ရဲစခန်း အရပ်ဘက်ရေးရာရုံးများတွင် လက်ခံပြီး ကိုယ်ခန္ဓာစစ်ဆေးခ အပါအဝင် သတ်မှတ်ထားသော အခကြေးငွေကို ကောက်ခံပါသည်။",
          mn: "Өргөдлийг улс даяар жолооны үнэмлэхний шалгалтын төвүүд эсвэл цагдаагийн хэлтсийн иргэний хэргийн албанд хүлээн авдаг бөгөөд биеийн үзлэгийн хураамжийг оролцуулаад тогтмол хураамж хэрэглэнэ.",
          lo: "ການສະໝັກແມ່ນໄດ້ຮັບການຍອມຮັບຢູ່ສູນສອບເສັງໃບຂັບຂີ່ທົ່ວປະເທດ ຫຼື ຫ້ອງການວຽກງານພົນລະເຮືອນຂອງສະຖານີຕໍາຫຼວດ, ແລະ ມີຄ່າທໍານຽມຄົງທີ່ລວມທັງຄ່າກວດສຸຂະພາບ.",
          tet:
              "Aplikasaun sira simu iha sentru ezame lisensa kondusaun iha nasaun tomak ka eskritóriu asuntu sivíl eskuadra polísia, no taxa fiksu ida aplika, inklui taxa ezame fíziku.",
          ne: "आवेदनहरू देशभरका ड्राइभिङ लाइसेन्स परीक्षण केन्द्रहरू वा प्रहरी चौकीका नागरिक मामिला कार्यालयहरूमा स्वीकार गरिन्छ, र शारीरिक परीक्षण शुल्क सहित एक निश्चित शुल्क लाग्छ।",
          zh: '可在全国各地的驾照考试场或警察署民愿室提交申请，需缴纳体检费等一定费用。',
          vi: 'Có thể nộp đơn tại trung tâm sát hạch bằng lái xe hoặc phòng dân nguyện của đồn cảnh sát trên toàn quốc, và sẽ phát sinh một khoản phí nhất định như phí khám sức khỏe.',
          uz: "Arizalar haydovchilik guvohnomasi sinov markazlarida yoki butun mamlakat boʻylab politsiya boʻlimlarining fuqarolik ishlari boʻlimlarida qabul qilinadi va tibbiy koʻrik toʻlovini oʻz ichiga olgan belgilangan toʻlov undiriladi.",
        ),
        blocks: [
          ContentBlock(
            title: L10nText(
              ko: '신청 절차',
              en: 'Application Procedure',
              tr: "Başvuru Prosedürü",
              tg: "Тартиби муроҷиат",
