              km: "នីតិវិធីដាក់ពាក្យ",
              id: "Prosedur Aplikasi",
              si: "අයදුම් කිරීමේ ක්‍රියා පටිපාටිය",
              bn: "আবেদন পদ্ধতি",
              my: "လျှောက်လွှာတင်ခြင်း လုပ်ထုံးလုပ်နည်း",
