            ),
            bullets: [
              L10nText(
                ko: '도로교통공단 안전운전 통합민원(safedriving.or.kr)에서 사전예약 후 방문 권장',
                en: 'It is recommended to make a reservation in advance through the Korea Road Traffic Authority\'s Integrated Civil Service for Safe Driving (safedriving.or.kr) before visiting',
                tr: "Ziyaret etmeden önce Kore Karayolu Trafik Kurumu'nun Güvenli Sürüş İçin Entegre Sivil Hizmetleri (safedriving.or.kr) aracılığıyla önceden rezervasyon yapılması önerilir.",
                tg: "Тавсия дода мешавад, ки пеш аз боздид тавассути Хадамоти муттаҳидаи шаҳрвандӣ барои ронандагии бехатар (safedriving.or.kr) аз Агентии роҳҳои Корея пешакӣ фармоиш дода шавад.",
                fil:
                    "Bago bumisita, inirerekomenda na mag-book nang maaga sa pamamagitan ng Integrated Civil Services for Safe Driving ng Korean Road Traffic Authority (safedriving.or.kr).",
                ur: "دورہ کرنے سے پہلے کوریا روڈ ٹریفک اتھارٹی کی سیف ڈرائیونگ کے لیے مربوط سول سروسز (safedriving.or.kr) کے ذریعے پیشگی ریزرویشن کرنے کی سفارش کی جاتی ہے۔",
                th: "ขอแนะนำให้จองล่วงหน้าผ่านบริการพลเรือนแบบบูรณาการเพื่อการขับขี่อย่างปลอดภัยของสำนักงานการจราจรทางบกเกาหลี (safedriving.or.kr) ก่อนเข้าเยี่ยมชม",
                ky: "Барардан мурун Кореянын Жол кыймылы агенттигинин Коопсуз айдоо үчүн интеграцияланган жарандык кызматтары (safedriving.or.kr) аркылуу алдын ала жазылуу сунушталат.",
                km: "មុនពេលទៅទស្សនា គួរណែនាំឱ្យកក់ទុកជាមុនតាមរយៈសេវាកម្មស៊ីវិលរួមបញ្ចូលគ្នាសម្រាប់ការបើកបរប្រកបដោយសុវត្ថិភាពរបស់ទីភ្នាក់ងារចរាចរណ៍ផ្លូវគោកកូរ៉េ (safedriving.or.kr)។",
                id: "Disarankan untuk membuat reservasi terlebih dahulu melalui Layanan Sipil Terpadu untuk Mengemudi Aman (safedriving.or.kr) dari Otoritas Lalu Lintas Jalan Korea sebelum berkunjung.",
                si: "සංචාරය කිරීමට පෙර, කොරියානු මාර්ග ගමනාගමන අධිකාරියේ (safedriving.or.kr) ආරක්ෂිත රිය පැදවීම සඳහා වන ඒකාබද්ධ සිවිල් සේවා හරහා කලින් වෙන්කරවා ගැනීම නිර්දේශ කෙරේ.",
                bn: "পরিদর্শন করার আগে কোরিয়া রোড ট্র্যাফিক অথরিটির সেফ ড্রাইভিং ইন্টিগ্রেটেড সিভিল সার্ভিসেস (safedriving.or.kr) এর মাধ্যমে একটি অগ্রিম রিজার্ভেশন করার পরামর্শ দেওয়া হয়।",
                my: "မသွားရောက်မီ ကိုရီးယားလမ်းအသွားအလာအာဏာပိုင်အဖွဲ့၏ ဘေးကင်းစွာမောင်းနှင်ရန် ပေါင်းစပ်အရပ်ဘက်ဝန်ဆောင်မှုများ (safedriving.or.kr) မှတစ်ဆင့် ကြိုတင်ဘွတ်ကင်လုပ်ရန် အကြံပြုအပ်ပါသည်။",
                mn: "Зочилохоосоо өмнө Солонгосын Замын хөдөлгөөний агентлагийн Аюулгүй жолоодлогын нэгдсэн иргэний үйлчилгээ (safedriving.or.kr) -ээр дамжуулан урьдчилан захиалга өгөхийг зөвлөж байна.",
                lo: "ແນະນໍາໃຫ້ຈອງລ່ວງໜ້າຜ່ານບໍລິການພົນລະເຮືອນລວມເພື່ອການຂັບຂີ່ປອດໄພຂອງອົງການຈະລາຈອນທາງບົກເກົາຫຼີ (safedriving.or.kr) ກ່ອນທີ່ຈະໄປຢ້ຽມຢາມ.",
                tet:
                    "Rekomenda atu halo rezerva uluk liuhusi Servisu Sivíl Integrada ba Kondusaun Segura husi Autoridade Tráfegu Estrada Koreia (safedriving.or.kr) antes vizita.",
                ne: "भ्रमण गर्नु अघि कोरियाली सडक यातायात प्राधिकरणको सुरक्षित ड्राइभिङका लागि एकीकृत नागरिक सेवाहरू (safedriving.or.kr) मार्फत अग्रिम आरक्षण गर्न सिफारिस गरिन्छ।",
                zh: '建议先通过道路交通公团安全驾驶综合民愿网站(safedriving.or.kr)预约后再前往办理',
                vi: 'Nên đặt lịch hẹn trước qua trang Dân nguyện tổng hợp lái xe an toàn của Cơ quan An toàn Giao thông Đường bộ Hàn Quốc (safedriving.or.kr) trước khi đến',
                uz: "Tashrif buyurishdan oldin Koreya Yoʻl Harakati Boshqarmasining Xavfsiz Haydash uchun Yagona Davlat Xizmati (safedriving.or.kr) orqali oldindan bron qilish tavsiya etiladi.",
              ),
              L10nText(
                ko: '접수 → 서류심사 → 적성검사(신체검사) → (미체결국은 학과시험) → 면허증 발급',
                en: 'Application → document screening → aptitude test (physical exam) → (written exam for non-agreement countries) → license issuance',
                tr: "Başvuru → belge incelemesi → yetenek testi (fiziksel muayene) → (anlaşmasız ülkeler için yazılı sınav) → ehliyet düzenleme",
                tg: "Муроҷиат → баррасии ҳуҷҷатҳо → санҷиши қобилият (муоинаи ҷисмонӣ) → (имтиҳони хаттӣ барои кишварҳои бесозишнома) → додани шаҳодатномаи ронандагӣ",
                fil:
                    "Aplikasyon → pagsusuri ng dokumento → pagsusuri ng kakayahan (physical examination) → (nakasulat na pagsusulit para sa mga bansang walang kasunduan) → pag-isyu ng lisensya",
                ur: "درخواست → دستاویزات کی جانچ → اہلیت کا ٹیسٹ (جسمانی معائنہ) → (غیر معاہدہ شدہ ممالک کے لیے تحریری امتحان) → لائسنس کا اجراء",
                th: "การสมัคร → การตรวจสอบเอกสาร → การทดสอบความสามารถ (การตรวจร่างกาย) → (ข้อสอบข้อเขียนสำหรับประเทศที่ไม่มีข้อตกลง) → การออกใบขับขี่",
                ky: "Арыз → документтерди текшерүү → жөндөмдүүлүк тести (физикалык кароо) → (келишим түзбөгөн өлкөлөр үчүн жазуу жүзүндөгү сынак) → айдоочулук күбөлүгүн берүү",
                km: "ការដាក់ពាក្យ → ការពិនិត្យឯកសារ → ការធ្វើតេស្តសមត្ថភាព (ការពិនិត្យរាងកាយ) → (ការប្រឡងសរសេរសម្រាប់ប្រទេសដែលគ្មានកិច្ចព្រមព្រៀង) → ការចេញប័ណ្ណបើកបរ",
                id: "Aplikasi → pemeriksaan dokumen → tes kemampuan (pemeriksaan fisik) → (tes tertulis untuk negara yang tidak menyetujui) → penerbitan SIM",
                si: "අයදුම්පත්‍රය → ලේඛන සමාලෝචනය → යෝග්‍යතා පරීක්ෂණය (ශාරීරික පරීක්ෂණය) → (ගිවිසුම්ගත නොවන රටවල් සඳහා ලිඛිත පරීක්ෂණය) → රියදුරු බලපත්‍රය නිකුත් කිරීම",
                bn: "আবেদন → নথি পর্যালোচনা → দক্ষতা পরীক্ষা (শারীরিক পরীক্ষা) → (অ-চুক্তিভুক্ত দেশগুলির জন্য লিখিত পরীক্ষা) → লাইসেন্স প্রদান",
                my: "လျှောက်လွှာတင်ခြင်း → စာရွက်စာတမ်းစစ်ဆေးခြင်း → ကျွမ်းကျင်မှုစစ်ဆေးခြင်း (ကိုယ်ခန္ဓာစစ်ဆေးခြင်း) → (သဘောတူညီချက်မရရှိသေးသော နိုင်ငံများအတွက် စာရေးဖြေစာမေးပွဲ) → ယာဉ်မောင်းလိုင်စင် ထုတ်ပေးခြင်း",
                mn: "Өргөдөл → бичиг баримтын хяналт → чадварын шалгалт (биеийн үзлэг) → (гэрээгүй улсуудын хувьд бичгийн шалгалт) → жолооны үнэмлэх олгох",
                lo: "ການສະໝັກ → ການກວດສອບເອກະສານ → ການທົດສອບຄວາມສາມາດ (ກວດສຸຂະພາບ) → (ການສອບເສັງຂຽນສໍາລັບປະເທດທີ່ບໍ່ມີຂໍ້ຕົກລົງ) → ການອອກໃບຂັບຂີ່.",
                tet:
                    "Aplikasaun → revizaun dokumentu → teste abilidade (ezame fíziku) → (ezame eskrita ba nasaun la ho akordu) → emisaun lisensa",
                ne: "आवेदन → कागजात समीक्षा → योग्यता परीक्षण (शारीरिक परीक्षण) → (सम्झौता नभएका देशहरूको लागि लिखित परीक्षा) → लाइसेन्स जारी",
                zh: '受理 → 材料审查 → 适性检查（体检）→（非协议国需参加学科考试）→ 发放驾照',
                vi: 'Nộp hồ sơ → thẩm tra hồ sơ → kiểm tra năng lực thích ứng (khám sức khỏe) → (thi lý thuyết đối với quốc gia chưa ký hiệp định) → cấp bằng lái',
