                th: "ค่าตรวจร่างกาย: 1 วอนสำหรับใบขับขี่รถขนาดใหญ่/พิเศษประเภทที่ 8.000 และ 7.000 วอนสำหรับใบขับขี่ประเภทอื่น ๆ (ณ วันที่ 2026; อาจมีการเปลี่ยนแปลงรายปี)",
                ky: "Физикалык кароо акысы: 1. Класстагы чоң/атайын унаа күбөлүктөрү үчүн 8.000 KRW, башка күбөлүктөр үчүн 7.000 KRW (2026 карата; жыл сайын өзгөрүшү мүмкүн)",
                km: "ថ្លៃពិនិត្យរាងកាយ៖ 8.000 វ៉ុនសម្រាប់ប័ណ្ណបើកបរយានយន្តធំ/ពិសេសថ្នាក់ទី 1 វ៉ុន និង 7.000 វ៉ុនសម្រាប់ប័ណ្ណបើកបរផ្សេងទៀត (គិតត្រឹម 2026; អាចប្រែប្រួលប្រចាំឆ្នាំ)",
                id: "Biaya pemeriksaan fisik: 1 won untuk SIM kendaraan besar/khusus Kelas 8.000, 7.000 won untuk SIM lainnya (per 2026; dapat berubah setiap tahun)",
                si: "ශාරීරික පරීක්ෂණ ගාස්තුව: 1. විශාල/විශේෂ වාහන බලපත්‍ර සඳහා වොන් 8.000, අනෙකුත් බලපත්‍ර සඳහා වොන් 7.000 (2026 වන විට; වාර්ෂිකව වෙනස් විය හැක)",
                bn: "শারীরিক পরীক্ষার ফি: ক্লাস 1 বড়/বিশেষ গাড়ির লাইসেন্সের জন্য 8.000 ওন, অন্যান্য লাইসেন্সের জন্য 7.000 ওন (2026 অনুযায়ী; বার্ষিক পরিবর্তিত হতে পারে)",
                my: "ကိုယ်ခန္ဓာစစ်ဆေးခ- 1 တန်း ကြီးမားသော/အထူးယာဉ်လိုင်စင်များအတွက် 8.000 ဝမ်၊ အခြားလိုင်စင်များအတွက် 7.000 ဝမ် (2026 မှစ၍၊ နှစ်စဉ်ပြောင်းလဲနိုင်သည်)",
