                lo: "ຄ່າກວດສຸຂະພາບ: 1. ສໍາລັບໃບຂັບຂີ່ປະເພດລົດໃຫຍ່/ລົດພິເສດແມ່ນ 8.000 ວອນ, ສໍາລັບໃບຂັບຂີ່ອື່ນໆແມ່ນ 7.000 ວອນ (ນັບແຕ່ 2026; ອາດຈະມີການປ່ຽນແປງປະຈໍາປີ).",
