                uz: "Tibbiy koʻrik toʻlovi: 1-toifali katta/maxsus transport vositasi guvohnomalari uchun 8 000 von, boshqa guvohnomalar uchun 7 000 von (2026-yil holatiga koʻra; har yili oʻzgarishi mumkin).",
