                ur: "آپ کے ملک کے لیے درکار دستاویزات کی مکمل فہرست کے لیے سب سے درست ذریعہ کوریا روڈ ٹریفک اتھارٹی کی سیف ڈرائیونگ انٹیگریٹڈ پبلک سروس ہے۔",
                th: "แหล่งข้อมูลที่ถูกต้องที่สุดสำหรับรายการเอกสารที่จำเป็นสำหรับประเทศของคุณคือบริการสาธารณะแบบบูรณาการเพื่อการขับขี่อย่างปลอดภัยของสำนักงานการจราจรทางบกเกาหลี",
                ky: "Сиздин өлкөңүз үчүн керектүү документтердин толук тизмеси үчүн эң так булак Кореянын Жол кыймылы агенттигинин Коопсуз айдоо интеграцияланган мамлекеттик кызматы болуп саналат.",
                km: "សម្រាប់បញ្ជីពេញលេញនៃឯកសារដែលត្រូវការសម្រាប់ប្រទេសរបស់អ្នក ប្រភពត្រឹមត្រូវបំផុតគឺសេវាកម្មសាធារណៈរួមបញ្ចូលគ្នានៃការបើកបរប្រកបដោយសុវត្ថីភាពរបស់ទីភ្នាក់ងារចរាចរណ៍ផ្លូវគោកកូរ៉េ។",
