                bn: "আপনার দেশের জন্য প্রয়োজনীয় নথির সম্পূর্ণ তালিকার জন্য সবচেয়ে সঠিক উৎস হল কোরিয়া রোড ট্র্যাফিক অথরিটির সেফ ড্রাইভিং ইন্টিগ্রেটেড পাবলিক সার্ভিস।",
                my: "သင့်နိုင်ငံအတွက် လိုအပ်သော စာရွက်စာတမ်းများ၏ အပြည့်အစုံစာရင်းအတွက် အတိကျဆုံးရင်းမြစ်မှာ ကိုရီးယားလမ်းအသွားအလာအာဏာပိုင်အဖွဲ့၏ ဘေးကင်းစွာမောင်းနှင်ရန် ပေါင်းစပ်ပြည်သူ့ဝန်ဆောင်မှုဖြစ်သည်။",
                mn: "Танай улсад шаардлагатай бичиг баримтын бүрэн жагсаалтыг авах хамгийн найдвартай эх сурвалж бол Солонгосын Замын хөдөлгөөний агентлагийн Аюулгүй жолоодлогын нэгдсэн төрийн үйлчилгээ юм.",
                lo: "ສໍາລັບແຫຼ່ງຂໍ້ມູນທີ່ຖືກຕ້ອງທີ່ສຸດສໍາລັບລາຍຊື່ເອກະສານທີ່ຈໍາເປັນສໍາລັບປະເທດຂອງທ່ານ, ກະລຸນາອ້າງອີງໃສ່ບໍລິການສາທາລະນະລວມເພື່ອການຂັບຂີ່ປອດໄພຂອງອົງການຈະລາຈອນທາງບົກເກົາຫຼີ.",
                tet:
                    "Ba lista kompleta dokumentu presiza ba Ita-nia nasaun, fonte ne'ebé loos liu mak Servisu Públiku Integrada Kondusaun Segura husi Autoridade Tráfegu Estrada Koreia.",
                ne: "तपाईंको देशका लागि आवश्यक कागजातहरूको पूर्ण सूचीको लागि सबैभन्दा सही स्रोत कोरियाली सडक यातायात प्राधिकरणको सुरक्षित ड्राइभिङ एकीकृत सार्वजनिक सेवा हो।",
                zh: '各国具体所需材料，以道路交通公团安全驾驶综合民愿网站的信息为准，最为准确。',
                vi: 'Để biết chính xác hồ sơ cần thiết theo từng quốc gia, nên kiểm tra tại Dân nguyện tổng hợp lái xe an toàn của Cơ quan An toàn Giao thông Đường bộ Hàn Quốc là chính xác nhất.',
                uz: "Mamlakatingiz uchun talab qilinadigan aniq hujjatlar boʻyicha eng aniq maʼlumot manbai Koreya Yoʻl Harakati Boshqarmasining Xavfsiz Haydash uchun Yagona Davlat Xizmatidir.",
              ),
