                tg: "Ҳатто пас аз гирифтани шаҳодатномаи ронандагии Корея, барои нигоҳ доштани эътибори он, шумо бояд вобаста ба намуди шаҳодатномаи ронандагӣ давра ба давра аз санҷиши салоҳият гузаред.",
                fil:
                    "Kahit na nakakuha ka na ng Korean driver's license, kailangan mo pa ring sumailalim sa pana-panahong pagsusuri ng kakayahan, depende sa uri ng lisensya, upang mapanatili ang bisa nito.",
                ur: "کورین ڈرائیونگ لائسنس حاصل کرنے کے بعد بھی، اس کی میعاد برقرار رکھنے کے لیے لائسنس کی قسم کے لحاظ سے وقتاً فوقتاً اہلیت کے ٹیسٹ سے گزرنا ضروری ہے۔",
                th: "แม้หลังจากได้รับใบขับขี่เกาหลีแล้ว คุณยังคงต้องเข้ารับการทดสอบความสามารถเป็นระยะ ๆ ขึ้นอยู่กับประเภทของใบขับขี่ เพื่อรักษาสถานะการใช้งาน",
                ky: "Кореянын айдоочулук күбөлүгүн алгандан кийин да, анын жарактуулугун сактоо үчүн айдоочулук күбөлүгүнүн түрүнө жараша мезгил-мезгили менен квалификациялык тесттен өтүп туруу керек.",
                km: "ទោះបីជាបន្ទាប់ពីទទួលបានប័ណ្ណបើកបររបស់កូរ៉េក៏ដោយ អ្នកត្រូវតែឆ្លងកាត់ការធ្វើតេស្តសមត្ថភាពតាមកាលកំណត់ អាស្រ័យលើប្រភេទប័ណ្ណបើកបរ ដើម្បីរក្សាសុពលភាពរបស់វា។",
                id: "Bahkan setelah mendapatkan SIM Korea, Anda harus menjalani tes kualifikasi secara berkala tergantung pada jenis SIM untuk menjaga validitasnya.",
                si: "ඔබ කොරියානු රියදුරු බලපත්‍රයක් ලබා ගත්තද, එහි වලංගුභාවය පවත්වා ගැනීම සඳහා රියදුරු බලපත්‍ර වර්ගය අනුව වරින් වර යෝග්‍යතා පරීක්ෂණයකට භාජනය විය යුතුය.",
                bn: "কোরিয়ান লাইসেন্স পাওয়ার পরেও, এর বৈধতা বজায় রাখার জন্য আপনাকে লাইসেন্সের প্রকারের উপর নির্ভর করে পর্যায়ক্রমে একটি যোগ্যতা পরীক্ষায় অংশ নিতে হবে।",
                my: "ကိုရီးယားယာဉ်မောင်းလိုင်စင် ရရှိပြီးနောက်တွင်ပင် ၎င်း၏တရားဝင်မှုကို ထိန်းသိမ်းထားရန် ယာဉ်မောင်းလိုင်စင်အမျိုးအစားပေါ် မူတည်၍ အရည်အချင်းစစ် စာမေးပွဲကို အခါအားလျော်စွာ ဖြေဆိုရပါမည်။",
                mn: "Солонгосын жолооны үнэмлэх авсны дараа ч гэсэн хүчинтэй байдлыг хадгалахын тулд жолооны үнэмлэхний төрлөөс хамаарч үе үе чадварын шалгалт өгөх шаардлагатай.",
                lo: "ເຖິງແມ່ນວ່າທ່ານຈະໄດ້ຮັບໃບຂັບຂີ່ເກົາຫຼີແລ້ວ, ທ່ານຈໍາເປັນຕ້ອງໄດ້ຮັບການທົດສອບຄວາມສາມາດເປັນໄລຍະໆ ຂຶ້ນຢູ່ກັບປະເພດຂອງໃບຂັບຂີ່ ເພື່ອຮັກສາຄວາມຖືກຕ້ອງຂອງມັນ.",
                tet:
                    "Maski depois hetan lisensa kondusaun Koreia, Ita presiza halo teste kualifikasaun periódiku, depende ba tipu lisensa, atu mantein ninia validade.",
                ne: "कोरियाली लाइसेन्स प्राप्त गरेपछि पनि, यसको वैधता कायम राख्न लाइसेन्सको प्रकार अनुसार आवधिक रूपमा योग्यता परीक्षण गराउनु पर्छ।",
                zh: '即使取得韩国国内驾照后，根据驾照种类不同，仍需定期接受适性检查，驾照才能维持有效。',
                vi: 'Ngay cả sau khi có bằng lái trong nước, tùy loại bằng lái mà bạn vẫn phải định kỳ kiểm tra năng lực thích ứng thì bằng lái mới được duy trì.',
                uz: "Koreya guvohnomasini olganingizdan keyin ham, uning amal qilish muddatini saqlab qolish uchun guvohnoma turiga qarab, davriy ravishda qobiliyat testidan oʻtishingiz shart.",
              ),
              L10nText(
                ko: '적성검사 기간을 넘기면 면허가 취소될 수 있으니 갱신 안내를 놓치지 마세요.',
                en: 'If you miss the aptitude test deadline, your license may be revoked, so do not miss the renewal notice.',
                tr: "Yeterlilik testi son tarihini kaçırırsanız, ehliyetiniz iptal edilebilir, bu yüzden yenileme bildirimini kaçırmayın.",
                tg: "Агар шумо мӯҳлати санҷиши салоҳиятро аз даст диҳед, шаҳодатномаи ронандагии шумо метавонад бекор карда шавад, аз ин рӯ огоҳиномаи навсозиро аз даст надиҳед.",
                fil:
                    "Kung makaligtaan mo ang deadline ng pagsusuri ng kakayahan, maaaring makansela ang iyong lisensya, kaya huwag palampasin ang abiso sa pag-renew.",
                ur: "اگر آپ اہلیت کے ٹیسٹ کی آخری تاریخ سے محروم ہو جاتے ہیں، تو آپ کا لائسنس منسوخ کیا جا سکتا ہے، اس لیے تجدید کے نوٹیفکیشن کو مت چھوڑیں۔",
                th: "หากคุณพลาดกำหนดเวลาการทดสอบความสามารถ ใบขับขี่ของคุณอาจถูกยกเลิกได้ ดังนั้นอย่าพลาดการแจ้งเตือนการต่ออายุ",
                ky: "Эгерде сиз квалификациялык тесттин мөөнөтүн өткөрүп жиберсеңиз, айдоочулук күбөлүгүңүз жокко чыгарылышы мүмкүн, андыктан жаңыртуу билдирүүсүн өткөрүп жибербеңиз.",
                km: "ប្រសិនបើអ្នកខកខានកាលបរិច្ឆេទផុតកំណត់នៃការធ្វើតេស្តសមត្ថភាព ប័ណ្ណបើកបររបស់អ្នកអាចនឹងត្រូវលុបចោល ដូច្នេះកុំខកខានការជូនដំណឹងបន្ត។",
                id: "Jika Anda melewatkan batas waktu tes kualifikasi, SIM Anda dapat dibatalkan, jadi jangan lewatkan pemberitahuan perpanjangan.",
                si: "ඔබ යෝග්‍යතා පරීක්ෂණයේ අවසාන දිනය මග හැරියහොත්, ඔබේ රියදුරු බලපත්‍රය අවලංගු විය හැකි බැවින්, අලුත් කිරීමේ දැනුම්දීම අතපසු නොකරන්න.",
                bn: "আপনি যদি যোগ্যতা পরীক্ষার সময়সীমা মিস করেন, তাহলে আপনার লাইসেন্স বাতিল হতে পারে, তাই নবায়নের বিজ্ঞপ্তি মিস করবেন না।",
                my: "အရည်အချင်းစစ် စာမေးပွဲ နောက်ဆုံးရက်ကို လွဲချော်ပါက သင့်ယာဉ်မောင်းလိုင်စင်ကို ပယ်ဖျက်နိုင်သောကြောင့် သက်တမ်းတိုးခြင်း အကြောင်းကြားစာကို လက်လွတ်မခံပါနှင့်။",
                mn: "Хэрэв та чадварын шалгалтын эцсийн хугацааг алдвал таны жолооны үнэмлэх хүчингүй болж болзошгүй тул сунгах мэдэгдлийг алдахгүй байхыг анхаарна уу.",
                lo: "ຖ້າທ່ານພາດກໍານົດເວລາການທົດສອບຄວາມສາມາດ, ໃບຂັບຂີ່ຂອງທ່ານອາດຈະຖືກຍົກເລີກ, ດັ່ງນັ້ນຢ່າພາດການແຈ້ງເຕືອນການຕໍ່ອາຍຸ.",
                tet:
                    "Se Ita lakon data limite teste kualifikasaun, Ita-nia lisensa bele kansela, entaun keta lakon notifikasaun renovasaun.",
                ne: "यदि तपाईंले योग्यता परीक्षणको अन्तिम मिति छुटाउनुभयो भने, तपाईंको लाइसेन्स रद्द हुन सक्छ, त्यसैले नवीकरण सूचना नछुटाउनुहोस्।",
                zh: '如果错过适性检查期限，驾照可能会被吊销，请务必留意更新通知。',
                vi: 'Nếu quá thời hạn kiểm tra năng lực thích ứng, bằng lái có thể bị thu hồi, vì vậy đừng bỏ lỡ thông báo gia hạn.',
                uz: "Agar siz malaka testining oxirgi muddatini oʻtkazib yuborsangiz, litsenziyangiz bekor qilinishi mumkin, shuning uchun yangilash toʻgʻrisidagi bildirishnomani oʻtkazib yubormang.",
              ),
